INSERT INTO lessons (title, sub_title, status, icon, is_locked, sort_order) VALUES ('Oxford 5000', 'Từ vựng nâng cao B2–C1', 'New', 'book', 0, 6);
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('abolish', 'verb', 'əˈbɒlɪʃ', 'to officially end a law, a system or an institution', 'This tax should be abolished.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('abortion', 'noun', 'əˈbɔːʃn', 'the deliberate ending of a pregnancy at an early stage', 'to support/oppose abortion', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('abstract', 'adjective', 'ˈæbstrækt', 'based on general ideas and not on any particular real person, thing or situation', 'abstract knowledge/principles', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('absurd', 'adjective', 'əbˈsɜːd', 'extremely silly; not logical and sensible', 'That uniform makes the guards look absurd.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('abundance', 'noun', 'əˈbʌndəns', 'a large quantity that is more than enough', 'The brochure promised beautiful walks with an abundance of wildlife.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('academy', 'noun', 'əˈkædəmi', 'a school or college for special training', 'She trained at the Royal Academy of Music.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accelerate', 'verb', 'əkˈseləreɪt', 'to happen faster or earlier; to make something happen faster or earlier', 'Inflation continues to accelerate.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('acceptance', 'noun', 'əkˈseptəns', 'the act of accepting a gift, an invitation, an offer, etc.', 'Please confirm your acceptance of this offer in writing.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accessible', 'adjective', 'əkˈsesəbl', 'that can be reached, entered, used, seen, etc.', 'The remote desert area is accessible only by helicopter.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accommodate', 'verb', 'əˈkɒmədeɪt', 'to provide somebody with a room or place to sleep, live or sit', 'The hotel can accommodate up to 500 guests.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accomplish', 'verb', 'əˈkʌmplɪʃ', 'to succeed in doing or completing something', 'The first part of the plan has been safely accomplished.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accomplishment', 'noun', 'əˈkʌmplɪʃmənt', 'an impressive thing that is done or achieved after a lot of work', 'It was one of the President''s greatest accomplishments.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accordance', 'noun', 'əˈkɔːdns', 'according to a rule or the way that somebody says that something should be done', 'in accordance with legal requirements', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accordingly', 'adverb', 'əˈkɔːdɪŋli', 'in a way that is appropriate to what has been done or said in a particular situation', 'We have to discover his plans and act accordingly.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accountability', 'noun', 'əˌkaʊntəˈbɪləti', 'the fact of being responsible for your decisions or actions and expected to explain them when you are asked', 'proposals for greater police accountability', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accountable', 'adjective', 'əˈkaʊntəbl', 'responsible for your decisions or actions and expected to explain them when you are asked', 'The state spends taxpayers’ money and should be held accountable.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accountant', 'noun', 'əˈkaʊntənt', 'a person whose job is to keep or check financial accounts', 'We talked to the company’s chief accountant.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accumulate', 'verb', 'əˈkjuːmjəleɪt', 'to gradually get more and more of something over a period of time', 'I seem to have accumulated a lot of books.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accumulation', 'noun', 'əˌkjuːmjəˈleɪʃn', 'the process of gradually increasing or getting more and more of something over a period of time', 'the accumulation of wealth', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accuracy', 'noun', 'ˈækjərəsi', 'the state of being exact or correct; the ability to do something with skill and without making mistakes', 'They questioned the accuracy of the information in the file.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accusation', 'noun', 'ˌækjuˈzeɪʃn', 'a statement saying that you think a person is guilty of doing something wrong or illegal; the fact of accusing somebody', 'I don''t want to make an accusation until I have some proof.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('accused', 'noun', 'ði əˈkjuːzd', 'a person who is on trial for committing a crime', 'The accused was found innocent.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('acquisition', 'noun', 'ˌækwɪˈzɪʃn', 'the act of getting something, especially knowledge, a skill, etc.', 'theories of child language acquisition', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('acre', 'noun', 'ˈeɪkə(r)', 'a unit for measuring an area of land; 4 840 square yards or about 4 050 square metres', '3 000 acres of parkland', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('activate', 'verb', 'ˈæktɪveɪt', 'to make something such as a device or chemical process start working', 'The burglar alarm is activated by movement.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('activation', 'noun', 'ˌæktɪˈveɪʃn', 'the act of making something such as a device or chemical process start working', 'The activation of several target genes results in two major effects.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('activist', 'noun', 'ˈæktɪvɪst', 'a person who works to achieve political or social change, especially as a member of an organization with particular aims', 'human/civil/animal rights activists', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('acute', 'adjective', 'əˈkjuːt', 'very serious or severe', 'There is an acute shortage of water.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ad', 'noun', 'æd', 'a notice, picture or film telling people about a product, job or service', 'The TV ads were first run last year.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('adaptation', 'noun', 'ˌædæpˈteɪʃn', 'the action or process of changing something, or of being changed, to suit a new purpose or situation', 'the adaptation of buildings for military purposes', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('addiction', 'noun', 'əˈdɪkʃn', 'the condition of being unable to stop using or doing something as a habit, especially something harmful', 'cocaine addiction', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('additionally', 'adverb', 'əˈdɪʃənəli', 'in a way that is more than was first mentioned or is usual', 'Additionally, the bus service will run on Sundays, every two hours.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('adhere', 'verb', 'ədˈhɪə(r)', 'to stick to something', 'Once in the bloodstream, the bacteria adhere to the surface of the red cells.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('adjacent', 'adjective', 'əˈdʒeɪsnt', 'next to something', 'The planes landed on adjacent runways.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('adjustment', 'noun', 'əˈdʒʌstmənt', 'a small change made to something in order to correct or improve it', 'I''ve made a few adjustments to the design.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('administer', 'verb', 'ədˈmɪnɪstə(r)', 'to manage and organize the affairs of a company, an organization, a country, etc.', 'to administer a charity/fund/school', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('administration', 'noun', 'ədˌmɪnɪˈstreɪʃn', 'the activities that are done in order to plan, organize and run a business, school or other institution', 'Administration costs are passed on to the customer.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('administrative', 'adjective', 'ədˈmɪnɪstrətɪv', 'connected with organizing the work of a business or an institution', 'an administrative job/assistant/error', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('administrator', 'noun', 'ədˈmɪnɪstreɪtə(r)', 'a person whose job is to manage and organize the public or business affairs of a company or an institution, or a person who works in an office dealing with records, accounts, etc.', 'Such organizational decisions are made by the hospital administrators.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('admission', 'noun', 'ədˈmɪʃn', 'the act of accepting somebody into an institution, organization, etc.; the right to enter a place or to join an institution or organization', 'Hospital admission is not necessary in most cases.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('adolescent', 'noun', 'ˌædəˈlesnt', 'a young person who is developing from a child into an adult', 'adolescents between the ages of 13 and 18 and the problems they face', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('adoption', 'noun', 'əˈdɒpʃn', 'the act of adopting a child; the fact of being adopted', 'She put the baby up for adoption.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('adverse', 'adjective', 'ˈædvɜːs', 'negative and unpleasant; not likely to produce a good result', 'adverse change/circumstances/weather conditions', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('advocate', 'noun, verb', 'ˈædvəkət', 'a person who supports or speaks in favour of somebody or of a public plan or action', 'advocate for something/somebody, an advocate for hospital workers', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('aesthetic', 'adjective', 'iːsˈθetɪk', 'connected with beauty and art and the understanding of beautiful things', 'the aesthetic appeal of the songs', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('affordable', 'adjective', 'əˈfɔːdəbl', 'cheap enough that people can afford to pay it or buy it', 'We offer quality products at affordable prices.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('aftermath', 'noun', 'ˈɑːftəmæθ', 'the situation that exists as a result of an important (and usually unpleasant) event, especially a war, an accident, etc.', 'in the aftermath of something, A lot of rebuilding took place in the aftermath of the war.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('agenda', 'noun', 'əˈdʒendə', 'a list of items to be discussed at a meeting', 'We have a very full agenda of issues to discuss.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('aggression', 'noun', 'əˈɡreʃn', 'feelings of anger and hate that may result in threatening or violent behaviour', 'The research shows that computer games may cause aggression.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('agricultural', 'adjective', 'ˌæɡrɪˈkʌltʃərəl', 'connected with the science or practice of farming', 'agricultural policy/land/production/development', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('agriculture', 'noun', 'ˈæɡrɪkʌltʃə(r)', 'the science or practice of farming', 'The number of people employed in agriculture has fallen in the last decade.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ah', 'exclamation', 'ɑː', 'used to express surprise, pleasure or sympathy, or when you disagree with somebody', 'Ah, there you are!', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('aide', 'noun', 'eɪd', 'a person who helps another person, especially a politician, in their job', 'White House aides', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('AIDS', 'noun', 'eɪdz', 'a serious illness caused by a virus called HIV that attacks the body’s ability to resist infection (the abbreviation for ‘Acquired Immune Deficiency Syndrome’)', 'the AIDS epidemic', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('airline', 'noun', 'ˈeəlaɪn', 'a company that provides regular flights to take passengers and goods to different places', 'an airline pilot/passenger', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('albeit', 'conjunction', 'ˌɔːlˈbiːɪt', 'although', 'He finally agreed, albeit reluctantly, to help us.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('album', 'noun', 'ˈælbəm', 'a book in which you keep photographs, stamps, etc.', 'a photo album', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('alert', 'adjective, noun, verb', 'əˈlɜːt', 'able to think quickly; quick to notice things', 'Suddenly he found himself awake and fully alert.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('alien', 'adjective, noun', 'ˈeɪliən', 'strange and frightening; different from what you are used to', 'an alien environment', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('align', 'verb', 'əˈlaɪn', 'to arrange something in the correct position, or to be in the correct position, in relation to something else, especially in a straight line', 'Make sure the shelf is aligned with the top of the cupboard.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('alignment', 'noun', 'əˈlaɪnmənt', 'arrangement in a straight line', 'the alignment of the sun, moon and earth at a particular time', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('alike', 'adjective, adverb', 'əˈlaɪk', 'very similar', 'My sister and I do not look alike.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('allegation', 'noun', 'ˌæləˈɡeɪʃn', 'a public statement that is made without giving proof, accusing somebody of doing something that is wrong or illegal', 'to investigate/deny/withdraw an allegation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('allege', 'verb', 'əˈledʒ', 'to state something as a fact but without giving proof', 'allege (that)…, The prosecution alleges (that) she was driving carelessly.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('allegedly', 'adverb', 'əˈledʒɪdli', 'expressed as though something is a fact but without giving any proof', 'crimes allegedly committed during the war', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('alliance', 'noun', 'əˈlaɪəns', 'an agreement between countries, political parties, etc. to work together in order to achieve something that they all want', 'to form/make an alliance', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('allocate', 'verb', 'ˈæləkeɪt', 'to give something officially to somebody/something for a particular purpose', 'allocate something (for something), A large sum has been allocated for buying new books for the library.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('allocation', 'noun', 'ˌæləˈkeɪʃn', 'an amount of money, space, etc. that is given to somebody for a particular purpose', 'We have spent our entire allocation for the year.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('allowance', 'noun', 'əˈlaʊəns', 'an amount of money that is given to somebody regularly or for a particular purpose', 'an allowance of $20 a day', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('aluminium', 'noun', 'ˌæljəˈmɪniəm', 'a chemical element. Aluminium is a light, silver-grey metal used for making pans, etc.', 'aluminium saucepans/window frames', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('amateur', 'adjective, noun', 'ˈæmətə(r)', 'doing something for pleasure or interest, not as a job', 'an amateur photographer', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ambassador', 'noun', 'æmˈbæsədə(r)', 'an official who lives in a foreign country as the senior representative there of their own country', 'the British Ambassador to Italy/in Rome', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ambitious', 'adjective', 'æmˈbɪʃəs', 'determined to be successful, rich, powerful, etc.', 'a fiercely ambitious young manager', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('amend', 'verb', 'əˈmend', 'to change a law, document, statement, etc. slightly in order to correct a mistake or to improve it', 'He asked to see the amended version.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('amendment', 'noun', 'əˈmendmənt', 'a small change or improvement that is made to a document or proposed new law; the process of changing a document or proposed new law', 'to introduce/propose/table an amendment (= to suggest it)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('amid', 'preposition', 'əˈmɪd', 'in the middle of or during something, especially something that causes excitement or fear', 'He finished his speech amid tremendous applause.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('among', 'preposition', 'əˈmʌŋ', 'surrounded by somebody/something; in the middle of somebody/something', 'a house among the trees', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('analogy', 'noun', 'əˈnælədʒi', 'a comparison of one thing with another thing that has similar features; a feature that is similar', 'analogy (between A and B), The teacher drew an analogy between the human heart and a pump.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('analyse', 'verb', 'ˈænəlaɪz', 'to examine the nature or structure of something, especially by separating it into its parts, in order to understand or explain it', 'analyse something, The job involves collecting and analysing data.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('analyst', 'noun', 'ˈænəlɪst', 'a person whose job involves examining facts or materials in order to give an opinion on them', 'a political/financial analyst', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ancestor', 'noun', 'ˈænsestə(r)', 'a person in your family who lived a long time ago', 'His ancestors had come to America from Ireland.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('anchor', 'noun', 'ˈæŋkə(r)', 'a heavy metal object that is attached to a rope or chain and dropped over the side of a ship or boat to keep it in one place', 'to drop anchor', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('angel', 'noun', 'ˈeɪndʒl', 'a spirit who is believed to be a servant of God, and is sent by God to deliver a message or perform a task. Angels are often shown dressed in white, with wings.', 'a host of angels', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('animation', 'noun', 'ˌænɪˈmeɪʃn', 'the process of making films, videos and computer games in which drawings, models or images of people and animals seem to move', 'computer/cartoon animation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('announcement', 'noun', 'əˈnaʊnsmənt', 'a spoken or written statement that informs people about something', 'to make an announcement', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('anonymous', 'adjective', 'əˈnɒnɪməs', 'with a name that is not known or that is not made public', 'an anonymous donor', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('any more', 'adverb', 'ˌeni ˈmɔː(r)', 'often used at the end of negative sentences and at the end of questions, to mean ‘any longer’', 'She doesn''t live here any more.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('anybody', 'pronoun', 'ˈenibɒdi', 'used instead of somebody in negative sentences and in questions after if/whether, and after verbs such as prevent, forbid, avoid, etc.', 'Is there anybody who can help me?', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('anyone', 'pronoun', 'ˈeniwʌn', 'used instead of someone in negative sentences and in questions after if/whether, and after verbs such as prevent, forbid, avoid, etc.', 'Is anyone there?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('apology', 'noun', 'əˈpɒlədʒi', 'a word or statement saying sorry for something that has been done wrong or that causes a problem', 'to offer/make/demand/accept an apology', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('app', 'noun', 'æp', 'a piece of software that you can download to a device such as a smartphone or tablet, for example to look up information or to play a game', 'You first need to install the app on your device.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('apparatus', 'noun', 'ˌæpəˈreɪtəs', 'the tools or other pieces of equipment that are needed for a particular activity or task', 'a piece of laboratory apparatus', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('appealing', 'adjective', 'əˈpiːlɪŋ', 'attractive or interesting', 'Spending the holidays in Britain wasn''t a prospect that I found particularly appealing.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('appetite', 'noun', 'ˈæpɪtaɪt', 'physical desire for food', 'He suffered from headaches and loss of appetite.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('applaud', 'verb', 'əˈplɔːd', 'to show your approval of somebody/something by clapping your hands (= hitting your open hands together several times)', 'He started to applaud and the others joined in.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('applicable', 'adjective', 'əˈplɪkəbl', 'that can be said to be true in the case of somebody/something', 'Give details of children where applicable (= if you have any).', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('applicant', 'noun', 'ˈæplɪkənt', 'a person who makes a formal request for something (= applies for it), especially for a job, a place at a college or university, etc.', 'There were over 500 applicants for the job.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('appreciation', 'noun', 'əˌpriːʃiˈeɪʃn', 'pleasure that you have when you recognize and enjoy the good qualities of somebody/something', 'She shows little appreciation of good music.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('appropriate', 'adjective', 'əˈprəʊpriət', 'suitable, acceptable or correct for the particular circumstances', 'an appropriate response/measure/method', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('appropriately', 'adverb', 'əˈprəʊpriətli', 'in a way that is suitable, acceptable or correct for the particular circumstances', 'The government has been accused of not responding appropriately to the needs of the homeless.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('April', 'noun', 'ˈeɪprəl', 'the fourth month of the year, between March and May', 'in April, She was born in April.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('arbitrary', 'adjective', 'ˈɑːbɪtrəri', 'not seeming to be based on a reason, system or plan and sometimes seeming unfair', 'The choice of players for the team seemed completely arbitrary.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('architect', 'noun', 'ˈɑːkɪtekt', 'a person whose job is designing buildings', 'The house was designed by architect Louis Kahn.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('architectural', 'adjective', 'ˌɑːkɪˈtektʃərəl', 'relating to architecture and buildings', 'architectural features', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('architecture', 'noun', 'ˈɑːkɪtektʃə(r)', 'the art and study of designing buildings', 'to study architecture', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('archive', 'noun', 'ˈɑːkaɪv', 'a collection of historical documents or records of a government, a family, a place or an organization; the place where these records are stored', 'the National Sound Archive', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('arena', 'noun', 'əˈriːnə', 'a place with a flat open area in the middle and seats around it where people can watch sports and entertainment', 'a concert at Wembley Arena', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('arguably', 'adverb', 'ˈɑːɡjuəbli', 'used (often before a comparative or superlative adjective) when you are stating an opinion that you believe you could give reasons to support', 'He is arguably the best actor of his generation.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('array', 'noun', 'əˈreɪ', 'a group or collection of things or people, often one that is large or impressive', 'a vast array of bottles of different shapes and sizes', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('arrive', 'verb', 'əˈraɪv', 'to get to a place, especially at the end of a journey', 'I''ll wait until they arrive.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('articulate', 'verb', 'ɑːˈtɪkjuleɪt', 'to express or explain your thoughts or feelings clearly in words', 'She struggled to articulate her thoughts.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('artwork', 'noun', 'ˈɑːtwɜːk', 'pictures and photographs prepared for books, magazines, etc.', 'Can you let me have the finished artwork for the poster by Friday?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ash', 'noun', 'æʃ', 'the grey or black powder that is left after something, especially tobacco, wood or coal, has burnt', 'cigarette ash', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('aspiration', 'noun', 'ˌæspəˈreɪʃn', 'a strong desire to have or do something', 'I didn''t realize you had political aspirations.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('aspire', 'verb', 'əˈspaɪə(r)', 'to have a strong desire to achieve or to become something', 'aspire (to something), She aspired to a scientific career.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assassination', 'noun', 'əˌsæsɪˈneɪʃn', 'the murder of an important or famous person, especially for political reasons', 'The president survived a number of assassination attempts.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assault', 'noun, verb', 'əˈsɔːlt', 'the crime of attacking somebody physically', 'Both men were charged with assault.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assemble', 'verb', 'əˈsembl', 'to come together as a group; to bring people or things together as a group', 'All the students were asked to assemble in the main hall.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assembly', 'noun', 'əˈsembli', 'a group of people who have been elected to meet together regularly and make decisions or laws for a particular region or country', 'state/legislative/federal/local assemblies', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assert', 'verb', 'əˈsɜːt', 'to state clearly and definitely that something is true', 'assert that…, She continued to assert that she was innocent.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assertion', 'noun', 'əˈsɜːʃn', 'a statement saying that you strongly believe something to be true', 'He was correct in his assertion that the minister had been lying.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assess', 'verb', 'əˈses', 'to make a judgement about the nature or quality of somebody/something', 'assess somebody/something, Accurately assessing environmental impacts is very complex.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assessment', 'noun', 'əˈsesmənt', 'an opinion or a judgement about somebody/something that has been thought about very carefully', 'a detailed assessment of the risks involved', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('asset', 'noun', 'ˈæset', 'a person or thing that is valuable or useful to somebody/something', 'In his job, patience is an invaluable asset.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assign', 'verb', 'əˈsaɪn', 'to give somebody something that they can use, or some work or responsibility', 'assign something (to somebody), The teacher assigned a different task to each of the children.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assignment', 'noun', 'əˈsaɪnmənt', 'a task or piece of work that somebody is given to do, usually as part of their job or studies', 'Students are required to complete all homework assignments.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('associated', 'adjective', 'əˈsəʊsieɪtɪd', 'if one thing is associated with another, the two things are connected because they happen together or one thing causes the other', 'associated with doing something, the risks associated with taking drugs', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assumption', 'noun', 'əˈsʌmpʃn', 'a belief or feeling that something is true or that something will happen, although there is no proof', 'an underlying/implicit assumption', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('assurance', 'noun', 'əˈʃʊərəns', 'a statement that something will certainly be true or will certainly happen, particularly when there has been doubt about it', 'They called for assurances that the government is committed to its education policy.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('astonishing', 'adjective', 'əˈstɒnɪʃɪŋ', 'very surprising; difficult to believe', 'She ran 100m in an astonishing 10.6 seconds.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('asylum', 'noun', 'əˈsaɪləm', 'protection that a government gives to people who have left their own country, usually because they were in danger for political reasons', 'to seek/apply for/be granted asylum', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('at', 'preposition', 'ət', 'used to say where something/somebody is or where something happens', 'at the corner of the street', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('athlete', 'noun', 'ˈæθliːt', 'a person who competes in sports', 'Olympic athletes', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('atrocity', 'noun', 'əˈtrɒsəti', 'a cruel and violent act, especially in a war', 'In the war, both sides committed atrocities.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('attachment', 'noun', 'əˈtætʃmənt', 'a document that you send to somebody using email', 'No attachment was included.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('attain', 'verb', 'əˈteɪn', 'to succeed in getting something, usually after a lot of effort', 'Most of our students attained five ‘A’ grades in their exams.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('attendance', 'noun', 'əˈtendəns', 'the act of being present at a place, for example at school', 'Attendance at these lectures is not compulsory.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('attribute', 'noun, verb', 'ˈætrɪbjuːt', 'a quality or feature of somebody/something', 'Patience is one of the most important attributes in a teacher.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('auction', 'noun', 'ˈɔːkʃn', 'a public sale in which things are sold to the person who offers the most money for them', 'an auction of paintings', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('audio', 'adjective', 'ˈɔːdiəʊ', 'connected with sound that is recorded', 'audio and video recordings/files/clips', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('audit', 'noun', 'ˈɔːdɪt', 'an official examination of business and financial records to see that they are true and correct', 'an annual audit', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('August', 'noun', 'ˈɔːɡəst', 'the 8th month of the year, between July and September', 'She was born in August.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('authentic', 'adjective', 'ɔːˈθentɪk', 'known to be real and what somebody claims it is and not a copy', 'I don''t know if the painting is authentic.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('authorize', 'verb', 'ˈɔːθəraɪz', 'to give official permission for something, or for somebody to do something', 'authorize something, I can authorize payments up to £5 000.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('auto', 'noun', 'ˈɔːtəʊ', 'a car', 'the auto industry', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('autonomy', 'noun', 'ɔːˈtɒnəmi', 'the freedom for a country, a region or an organization to govern itself independently', 'a campaign in Wales for greater autonomy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('availability', 'noun', 'əˌveɪləˈbɪləti', 'the fact that something is possible to get, buy or find', 'the availability of cheap flights', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('await', 'verb', 'əˈweɪt', 'to wait for somebody/something', 'He is in custody awaiting trial.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('awareness', 'noun', 'əˈweənəs', 'knowing something; knowing that something exists and is important', 'awareness of something, an awareness of the importance of eating a healthy diet', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('baby', 'noun', 'ˈbeɪbi', 'a very young child or animal', 'The baby''s crying!', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('backdrop', 'noun', 'ˈbækdrɒp', 'everything that can be seen around an event or scene', 'The mountains provided a dramatic backdrop for our picnic.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('backing', 'noun', 'ˈbækɪŋ', 'help and support from somebody to do something; financial support for something', 'The police gave the proposals their full backing.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('backup', 'noun', 'ˈbækʌp', 'extra help or support that you can get if necessary', 'The police had backup from the army.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('badge', 'noun', 'bædʒ', 'a small piece of metal or plastic, with a design or words on it, that a person wears or carries to show that they belong to an organization, support something, have achieved something, have a particular rank, etc.', 'She wore a badge saying ‘Vote for Coates’.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bail', 'noun', 'beɪl', 'money that somebody agrees to pay if a person accused of a crime does not appear at their trial. When bail has been arranged, the accused person is allowed to go free until the trial.', 'Can anyone put up bail for you?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('balanced', 'adjective', 'ˈbælənst', 'keeping or showing a balance so that different things or different parts of something exist in equal or correct amounts', 'The programme presented a balanced view of the two sides of the conflict.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ballet', 'noun', 'ˈbæleɪ', 'a style of dancing that tells a dramatic story with music but no talking or singing', 'She wants to be a ballet dancer.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('balloon', 'noun', 'bəˈluːn', 'a small bag made of very thin rubber that becomes larger and rounder when you fill it with air or gas. Balloons are brightly coloured and used as decorations or toys.', 'to blow up/burst/pop a balloon', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ballot', 'noun', 'ˈbælət', 'the system of voting in writing and usually in secret; an occasion on which a vote is held', 'The chairperson is chosen by secret ballot.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('banana', 'noun', 'bəˈnɑːnə', 'a long curved fruit with a thick yellow skin and that is soft inside, which grows on trees in hot countries', 'a bunch of bananas', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('banner', 'noun', 'ˈbænə(r)', 'a long piece of cloth with a message on it that is carried between two poles or hung in a public place to show support for something', 'A huge banner over the street said ‘Welcome home’.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bare', 'adjective', 'beə(r)', 'not covered by any clothes', 'She likes to walk around in bare feet.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('barely', 'adverb', 'ˈbeəli', 'in a way that is just possible but only with difficulty', 'He could barely read and write.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('barrel', 'noun', 'ˈbærəl', 'a large round container, usually made of wood or metal, with flat ends and, usually, curved sides', 'a beer/wine barrel', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('baseball', 'noun', 'ˈbeɪsbɔːl', 'a game played especially in the US by two teams of nine players, using a bat and ball. Each player tries to hit the ball and then run around four bases before the other team can return the ball.', 'a baseball bat/team/cap/fan/player/game', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('based', 'adjective', 'beɪst', 'if one thing is based on another, it uses it or is developed from it', 'The movie is based on a real-life incident.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('basement', 'noun', 'ˈbeɪsmənt', 'a room or rooms in a building, partly or completely below the level of the ground', 'Kitchen goods are sold in the basement.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('basket', 'noun', 'ˈbɑːskɪt', 'a container for holding or carrying things. Baskets are made of long thin pieces of material that bends and twists easily, for example plastic, wire or wicker.', 'a shopping basket', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('basketball', 'noun', 'ˈbɑːskɪtbɔːl', 'a game played by two teams of five players, using a large ball which players try to throw into a high net hanging from a ring', 'a basketball game/coach/team/player', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bass', 'noun', 'beɪs', 'the lowest tone or part in music, for instruments or voices', 'He always plays his stereo with the bass turned right up.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bat', 'noun, verb', 'bæt', 'a piece of wood with a handle, made in various shapes and sizes, and used for hitting the ball in games such as baseball, cricket and table tennis', 'a baseball/cricket bat', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('battlefield', 'noun', 'ˈbætlfiːld', 'a place where a battle is being fought or has been fought', 'heavy casualties on the battlefield', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('be', 'verb, auxiliary verb', 'bi', 'used when you are naming people or things, describing them or giving more information about them', '+ noun, Today is Monday.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('beam', 'noun', 'biːm', 'a line of light, electromagnetic waves or particles', 'narrow beams of light/sunlight', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bean', 'noun', 'biːn', 'a seed, or pod containing seeds, of a climbing plant, eaten as a vegetable. There are several types of bean and the plants that they grow on are also called beans.', 'green beans', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('beast', 'noun', 'biːst', 'an animal, especially one that is large or dangerous, or one that is unusual', 'wild/savage/ferocious beasts', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bee', 'noun', 'biː', 'a black and yellow flying insect that can sting (= touch your skin and make you feel a sharp pain).Bees live in large groups and make honey (= a sweet sticky substance that is good to eat).', 'Bees were buzzing in the clover.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('beg', 'verb', 'beɡ', 'to ask somebody for something especially in an anxious way because you want or need it very much', 'Now you have to beg and plead.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('behaviour', 'noun', 'bɪˈheɪvjə(r)', 'the way that somebody behaves, especially towards other people', 'good/bad behaviour', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('being', 'noun', 'ˈbiːɪŋ', 'existence', 'The Irish Free State came into being in 1922.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('beloved', 'adjective', 'bɪˈlʌvɪd', 'loved very much', 'in memory of our dearly beloved son, John', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bench', 'noun', 'bentʃ', 'a long seat for two or more people, usually made of wood', 'a park bench', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('benchmark', 'noun', 'ˈbentʃmɑːk', 'something that can be measured and used as a standard that other things can be compared with', 'Tests at the age of seven provide a benchmark against which the child''s progress at school can be measured.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('beneficial', 'adjective', 'ˌbenɪˈfɪʃl', 'improving a situation; having a helpful or useful effect', 'A good diet is beneficial to health.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('beneficiary', 'noun', 'ˌbenɪˈfɪʃəri', 'a person who gains as a result of something', 'Who will be the main beneficiary of the cuts in income tax?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('besides', 'adverb, preposition', 'bɪˈsaɪdz', 'used for making an extra comment that adds to what you have just said', 'I don''t really want to go. Besides, it''s too late now.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('best', 'adjective, adverb, noun', 'best', 'of the most excellent type or quality', 'That''s the best movie I''ve ever seen!', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('betray', 'verb', 'bɪˈtreɪ', 'to give information about somebody/something to an enemy', 'betray somebody/something, He was offered money to betray his colleagues.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('better', 'adjective, adverb, noun', 'ˈbetə(r)', 'of a higher standard or less poor quality; not as bad as something else', 'We''re hoping for better weather tomorrow.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bias', 'noun', 'ˈbaɪəs', 'a strong feeling in favour of or against one group of people, or one side in an argument, often not based on fair judgement', 'accusations of political bias in news programmes (= that reports are unfair and show favour to one political party)', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bicycle', 'noun', 'ˈbaɪsɪkl', 'a road vehicle with two wheels that you ride by pushing the pedals with your feet', 'He got on his bicycle and rode off.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bike', 'noun', 'baɪk', 'a bicycle', 'I used to ride my bike around the neighbourhood for hours.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('billion', 'number', 'ˈbɪljən', '1 000 000 000; one thousand million', 'Worldwide sales reached 2.5 billion.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bind', 'verb', 'baɪnd', 'to tie somebody/something with rope, string, etc. so that they/it cannot move or are held together strongly', 'bind somebody/something to something, She was bound to a chair.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('biography', 'noun', 'baɪˈɒɡrəfi', 'the story of a person’s life written by somebody else; this type of writing', 'Boswell’s biography of Johnson', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('biological', 'adjective', 'ˌbaɪəˈlɒdʒɪkl', 'connected with the science of biology', 'the biological sciences', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bishop', 'noun', 'ˈbɪʃəp', 'a senior priest in charge of the work of the Church in a city or district', 'the Bishop of Oxford', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bizarre', 'adjective', 'bɪˈzɑː(r)', 'very strange or unusual', 'a bizarre situation/incident/story', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('blanket', 'noun', 'ˈblæŋkɪt', 'a large cover, often made of wool, used especially on beds to keep people warm', 'It’s cold tonight—can I have another blanket?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('blast', 'noun, verb', 'blɑːst', 'an explosion or a powerful movement of air caused by an explosion', 'a bomb blast', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bleed', 'verb', 'bliːd', 'to lose blood, especially from a wound or an injury', 'My finger''s bleeding.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('blend', 'noun, verb', 'blend', 'a mixture of different types of the same thing', 'a blend of tea', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bless', 'verb', 'bles', 'to ask God to protect somebody/something', 'They brought the children to Jesus and he blessed them.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('blessing', 'noun', 'ˈblesɪŋ', 'God’s help and protection, or a prayer asking for this', 'to pray for God’s blessing', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('blog', 'noun', 'blɒɡ', 'a website where an individual person, or people representing an organization, write regularly about recent events or topics that interest them, usually with photos and links to other websites that they find interesting', 'This is a link to the museum''s blog.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('blonde', 'adjective', 'blɒnd', 'pale gold in colour', 'She had long blonde hair.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('boast', 'verb', 'bəʊst', 'to talk in a way that shows you are too proud of something that you have or can do', 'I don''t want to boast, but I can actually speak six languages.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bold', 'adjective', 'bəʊld', 'brave and confident; not afraid to say what you feel or to take risks', 'It was a bold move on their part to open a business in France.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bombing', 'noun', 'ˈbɒmɪŋ', 'an occasion when a bomb is dropped or left somewhere; the act of doing this', 'recent bombings in major cities', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bond', 'noun', 'bɒnd', 'something that forms a connection between people or groups, such as a feeling of friendship or shared ideas and experiences', 'the bond that links us', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bonus', 'noun', 'ˈbəʊnəs', 'an extra amount of money that is added to a payment, especially to somebody’s wages or salary as a reward', 'a £100 Christmas bonus', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('booking', 'noun', 'ˈbʊkɪŋ', 'an arrangement that you make in advance to buy a ticket to travel somewhere, go to the theatre, etc.', 'a booking form/hall/clerk', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('boom', 'noun', 'buːm', 'a sudden increase in trade and economic activity; a period of wealth and success', 'Living standards improved rapidly during the post-war boom.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('boost', 'noun, verb', 'buːst', 'something that helps or encourages somebody/something', 'a great/tremendous/welcome boost', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('born', 'verb', 'bɔːn', 'to come out of your mother’s body at the beginning of your life', 'I was born in 1976.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bounce', 'verb', 'baʊns', 'if something bounces or you bounce it, it moves quickly away from a surface it has just hit or you make it do this', 'The ball bounced twice before he could reach it.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bound', 'adjective', 'baʊnd', 'certain or likely to happen, or to do or be something', 'There are bound to be changes when the new system is introduced.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('boundary', 'noun', 'ˈbaʊndri', 'a real or imagined line that marks the limits or edges of something and separates it from other things or places; a dividing line', 'After the war the national boundaries were redrawn.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bow', 'noun, verb', 'baʊ', 'the act of bending your head or the upper part of your body forward in order to say hello or goodbye to somebody or to show respect', 'She gave a slight bow of her head in greeting.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('breach', 'noun, verb', 'briːtʃ', 'a failure to do something that must be done by law', 'a breach of contract/copyright/warranty', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('breakdown', 'noun', 'ˈbreɪkdaʊn', 'an occasion when a vehicle or machine stops working', 'a breakdown on the motorway', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('breakthrough', 'noun', 'ˈbreɪkθruː', 'an important development that may lead to an agreement or achievement', 'to make/achieve a breakthrough', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bride', 'noun', 'braɪd', 'a woman on her wedding day, or just before or just after it', 'a toast to the bride and groom', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('broadband', 'noun', 'ˈbrɔːdbænd', 'a way of connecting to the internet that allows you to receive information, including pictures, etc., very quickly and that is always active (so that the user does not have to connect each time)', 'plans to provide rural areas with fast broadband', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('broadcaster', 'noun', 'ˈbrɔːdkɑːstə(r)', 'a person whose job is presenting or talking on television or radio programmes', 'She is a writer and broadcaster on environmental matters.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('browser', 'noun', 'ˈbraʊzə(r)', 'a computer program that lets you look at or read documents on the World Wide Web', 'What do you use as your default browser?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('brutal', 'adjective', 'ˈbruːtl', 'violent and cruel', 'a brutal attack/murder/rape/killing', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('buck', 'noun', 'bʌk', 'a US, Australian or New Zealand dollar; a South African rand; an Indian rupee', 'They cost ten bucks.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('buddy', 'noun', 'ˈbʌdi', 'a friend', 'an old college buddy of mine', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('buffer', 'noun', 'ˈbʌfə(r)', 'a thing or person that reduces a shock or protects somebody/something against difficulties', 'buffer against something, Support from family and friends acts as a buffer against stress.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bug', 'noun', 'bʌɡ', 'any small insect', 'There''s a bug crawling up your arm.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bulk', 'noun', 'bʌlk', 'the main part of something; most of something', 'The bulk of the population lives in cities.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('burden', 'noun', 'ˈbɜːdn', 'a duty, responsibility, etc. that causes worry, difficulty or hard work', 'to bear/carry/ease/reduce/share the burden', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('bureaucracy', 'noun', 'bjʊəˈrɒkrəsi', 'the system of official rules and ways of doing things that a government or an organization has, especially when these seem to be too complicated', 'unnecessary/excessive bureaucracy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('burial', 'noun', 'ˈberiəl', 'the act or ceremony of burying a dead body', 'a burial place/mound/site', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('businessman', 'noun', 'ˈbɪznəsmæn', 'a man who works in business, especially at a high level', 'a group of visiting Italian politicians and businessmen', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cabin', 'noun', 'ˈkæbɪn', 'a small room on a ship in which you live or sleep', 'I lay in my cabin feeling miserably seasick.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cafe', 'noun', 'ˈkæfeɪ', 'a place where you can buy drinks and simple meals. Alcohol is not usually served in British or American cafes.', 'There are small shops and pavement cafes around every corner.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('campus', 'noun', 'ˈkæmpəs', 'the buildings of a university or college and the land around them', 'university/college campuses', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('canal', 'noun', 'kəˈnæl', 'a long straight passage dug in the ground and filled with water for boats and ships to travel along; a smaller passage used for carrying water to fields, crops, etc.', 'the Panama/Suez Canal', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('candle', 'noun', 'ˈkændl', 'a round stick of wax with a piece of string (called a wick) through the middle that is lit to give light as it burns', 'a flickering candle', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cannot', 'modal verb', 'ˈkænɒt', 'the negative of can; can not', 'I cannot believe the price of the tickets!', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('canvas', 'noun', 'ˈkænvəs', 'a strong heavy rough material used for making tents, sails, etc. and by artists for painting on', 'tents made from heavy canvas', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('capability', 'noun', 'ˌkeɪpəˈbɪləti', 'the ability or qualities necessary to do something', 'Age affects the range of a person''s capabilities.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('capitalism', 'noun', 'ˈkæpɪtəlɪzəm', 'an economic system in which a country’s businesses and industry are controlled and run for profit by private owners rather than by the government', 'the growth of industrial capitalism in the West', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('capitalist', 'adjective', 'ˈkæpɪtəlɪst', 'based on the principles of capitalism', 'a capitalist society/system/economy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('carbon', 'noun', 'ˈkɑːbən', 'a chemical element. Carbon is found in all living things, existing in a pure state as diamond and graphite.', 'carbon fibre', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cargo', 'noun', 'ˈkɑːɡəʊ', 'the goods carried in a ship, an aircraft or a motor vehicle', 'The tanker began to spill its cargo of oil.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('carriage', 'noun', 'ˈkærɪdʒ', 'a separate section of a train for carrying passengers', 'a railway carriage', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cartoon', 'noun', 'kɑːˈtuːn', 'a humorous drawing in a newspaper or magazine, especially one about politics or events in the news', 'a political/satirical cartoon', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('carve', 'verb', 'kɑːv', 'to make objects, patterns, etc. by cutting away material from a piece of wood or stone, or another hard material', 'carve something, a carved doorway', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('casino', 'noun', 'kəˈsiːnəʊ', 'a public building or room where people play gambling games for money', 'a new hotel and casino in Las Vegas', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('casual', 'adjective', 'ˈkæʒuəl', 'not formal', 'casual clothes (= comfortable clothes that you choose to wear in your free time)', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('casualty', 'noun', 'ˈkæʒuəlti', 'a person who is killed or injured in war or in an accident', 'Our primary objective is reducing road casualties.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('catalogue', 'noun', 'ˈkætəlɒɡ', 'a complete list of items, for example of things that people can look at or buy', 'a mail-order catalogue (= a book showing goods for sale to be sent to people’s homes)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cater', 'verb', 'ˈkeɪtə(r)', 'to provide food and drinks for a social event', '(British English), cater for somebody/something, Most of our work now involves catering for weddings.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cattle', 'noun', 'ˈkætl', 'cows and bulls that are kept as farm animals for their milk or meat', 'a herd of cattle', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('caution', 'noun', 'ˈkɔːʃn', 'care that you take in order to avoid danger or mistakes; the fact of not taking any risks', 'extreme/great caution', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cautious', 'adjective', 'ˈkɔːʃəs', 'being careful about what you say or do, especially to avoid danger or mistakes; not taking any risks', 'The government has been cautious in its response to the report.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cave', 'noun', 'keɪv', 'a large hole in the side of a hill or cliff or under the ground', 'the mouth (= the entrance) of the cave', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('celebrity', 'noun', 'səˈlebrəti', 'a famous person', 'a celebrity chef', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cemetery', 'noun', 'ˈsemətri', 'an area of land used for burying dead people, especially one that is not next to a church', 'He was buried in a private cemetery.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('certainty', 'noun', 'ˈsɜːtnti', 'the state of being certain', 'There is no certainty that the president''s removal would end the civil war.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('chairman', 'noun', 'ˈtʃeəmən', 'the person in charge of a meeting, who tells people when they can speak, etc.', 'Sir Herbert took it upon himself to act as chairman.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('challenging', 'adjective', 'ˈtʃælɪndʒɪŋ', 'difficult in an interesting way that tests your ability', 'challenging work/questions/problems', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('champion', 'noun', 'ˈtʃæmpiən', 'a person, team, etc. that has won a competition, especially in a sport', 'the world/European/national/Olympic champion', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('championship', 'noun', 'ˈtʃæmpiənʃɪp', 'a competition to find the best player or team in a particular sport', 'the National Basketball Association Championship', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('chaos', 'noun', 'ˈkeɪɒs', 'a complete lack of order', 'economic/political/domestic chaos', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('characterize', 'verb', 'ˈkærəktəraɪz', 'to be typical of a person, place or thing', 'the rolling hills that characterize this part of England', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('charm', 'noun', 'tʃɑːm', 'the power of pleasing or attracting people', 'He was a man of great charm.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('charming', 'adjective', 'ˈtʃɑːmɪŋ', 'very pleasant or attractive', 'The cottage is tiny, but it''s charming.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('charter', 'noun', 'ˈtʃɑːtə(r)', 'a written statement describing the rights that a particular group of people should have', 'the European Social Charter of workers’ rights', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cheer', 'noun, verb', 'tʃɪə(r)', 'a shout of joy, support or praise', 'A great cheer went up from the crowd.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('chef', 'noun', 'ʃef', 'a person whose job is to cook, especially the most senior person in a restaurant, hotel, etc.', 'a new book by celebrity chef Jamie Oliver', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('childhood', 'noun', 'ˈtʃaɪldhʊd', 'the period of somebody’s life when they are a child', 'childhood, adolescence, and adulthood', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('choir', 'noun', 'ˈkwaɪə(r)', 'a group of people who sing together, for example in church services or public performances', 'She sings in the school choir.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('chronic', 'adjective', 'ˈkrɒnɪk', 'lasting for a long time; difficult to cure', 'chronic bronchitis/arthritis/asthma', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('chunk', 'noun', 'tʃʌŋk', 'a thick, solid piece that has been cut or broken off something', 'a chunk of cheese/masonry', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('circuit', 'noun', 'ˈsɜːkɪt', 'a line, route or journey around a place', 'The race ended with eight laps of a city centre circuit.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('circulate', 'verb', 'ˈsɜːkjəleɪt', 'when a liquid, gas or air circulates or is circulated, it moves continuously around a place or system', 'The condition prevents the blood from circulating freely.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('circulation', 'noun', 'ˌsɜːkjəˈleɪʃn', 'the movement of blood around the body', 'Regular exercise will improve blood circulation.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cite', 'verb', 'saɪt', 'to mention something as a reason or an example, or in order to support what you are saying', 'cite something, She cited examples of companies the city has helped relocate or expand.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('citizenship', 'noun', 'ˈsɪtɪzənʃɪp', 'the legal right to belong to a particular country', 'They were granted full French citizenship.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('civic', 'adjective', 'ˈsɪvɪk', 'officially connected with a town or city', 'civic buildings/leaders', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('civilian', 'adjective, noun', 'səˈvɪliən', 'connected with people who are not members of the armed forces or the police', 'He left the army and returned to civilian life.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('civilization', 'noun', 'ˌsɪvəlaɪˈzeɪʃn', 'a state of human society that is very developed and organized', 'the technology of modern civilization', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clarify', 'verb', 'ˈklærəfaɪ', 'to make something clearer or easier to understand', 'clarify something, to clarify a situation/problem/issue', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clarity', 'noun', 'ˈklærəti', 'the quality of being expressed clearly', 'a lack of clarity in the law', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clash', 'noun', 'klæʃ', 'a short fight between two groups of people', 'Clashes broke out between police and demonstrators.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('classical', 'adjective', 'ˈklæsɪkl', 'relating to classical music', 'a classical composer/musician/pianist', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('classification', 'noun', 'ˌklæsɪfɪˈkeɪʃn', 'the act or process of putting people or things into a group or class (= of classifying them)', 'a style of music that defies classification (= is like no other)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('classify', 'verb', 'ˈklæsɪfaɪ', 'to arrange something in groups according to features that they have in common', 'The books in the library are classified according to subject.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clause', 'noun', 'klɔːz', 'a group of words that includes a subject and a verb, and forms a sentence or part of a sentence', 'in a clause, There are languages that require the subject to come before the object in a clause.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cliff', 'noun', 'klɪf', 'a high area of rock with a very steep side, often at the edge of the sea or ocean', 'the cliff edge/top', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cling', 'verb', 'klɪŋ', 'to hold on tightly to somebody/something', 'cling to somebody/something, survivors clinging to a raft', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clinic', 'noun', 'ˈklɪnɪk', 'a building or part of a hospital where people can go for special medical treatment or advice', 'Your local family planning clinic can give you advice about birth control.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clinical', 'adjective', 'ˈklɪnɪkl', 'relating to the examination and treatment of patients and their illnesses', 'clinical research (= done on patients, not just considering theory)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clip', 'noun', 'klɪp', 'a short part of a film that is shown separately', 'Here is a clip from her latest movie.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('closure', 'noun', 'ˈkləʊʒə(r)', 'the situation when a factory, school, hospital, etc. shuts permanently', 'factory closures', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('clue', 'noun', 'kluː', 'an object, a piece of evidence or some information that helps the police solve a crime', 'The burglar left no clues.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cluster', 'noun', 'ˈklʌstə(r)', 'a group of things of the same type that grow or appear close together', 'The telescope is focused on a dense cluster of stars at the edge of the galaxy.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coalition', 'noun', 'ˌkəʊəˈlɪʃn', 'a government formed by two or more political parties working together', 'The two parties have formed a coalition.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coastal', 'adjective', 'ˈkəʊstl', 'of or near a coast', 'coastal waters/resorts/scenery', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cocktail', 'noun', 'ˈkɒkteɪl', 'a drink usually made from a mixture of one or more spirits (= strong alcoholic drinks) and fruit juice. It can also be made without alcohol.', 'a cocktail bar/cabinet/lounge/shaker ', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cognitive', 'adjective', 'ˈkɒɡnətɪv', 'connected with mental processes of understanding', 'a child’s cognitive development', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coincide', 'verb', 'ˌkəʊɪnˈsaɪd', 'to take place at the same time', 'It''s a pity our trips to New York don''t coincide.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coincidence', 'noun', 'kəʊˈɪnsɪdəns', 'the fact of two things happening at the same time by chance, in a surprising way', 'a strange/an extraordinary/a remarkable coincidence', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('collaborate', 'verb', 'kəˈlæbəreɪt', 'to work together with somebody in order to produce or achieve something', 'Researchers around the world are collaborating to develop a new vaccine.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('collaboration', 'noun', 'kəˌlæbəˈreɪʃn', 'the act of working with another person or group of people to create or produce something', 'It was a collaboration that produced extremely useful results.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('collective', 'adjective', 'kəˈlektɪv', 'done or shared by all members of a group of people; involving a whole group or society', 'collective leadership/decision-making/responsibility', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('collector', 'noun', 'kəˈlektə(r)', 'a person who collects things, either as a hobby or as a job', 'a stamp collector', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('collision', 'noun', 'kəˈlɪʒn', 'an accident in which two vehicles or people crash into each other', 'collision between A and B, a collision between two trains', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('colonial', 'adjective', 'kəˈləʊniəl', 'connected with or belonging to a country that controls another country', 'a colonial power', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('colony', 'noun', 'ˈkɒləni', 'a country or an area that is governed by people from another, more powerful, country', 'former British colonies', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('colour', 'noun', 'ˈkʌlə(r)', 'the appearance that things have that results from the way in which they reflect light. Red, orange and green are colours.', 'What''s your favourite colour?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('colourful', 'adjective', 'ˈkʌləfl', 'full of bright colours or having a lot of different colours', 'colourful shop windows', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('columnist', 'noun', 'ˈkɒləmnɪst', 'a journalist who writes regular articles for a newspaper or magazine', 'a newspaper columnist', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('combat', 'noun, verb', 'ˈkɒmbæt', 'fighting or a fight, especially during a time of war', 'in combat, He was killed in combat.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('comic', 'adjective, noun', 'ˈkɒmɪk', 'humorous and making you laugh', 'a comic monologue/story', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('commander', 'noun', 'kəˈmɑːndə(r)', 'a person who is in charge of something, especially an officer in charge of a particular group of soldiers or a military operation', 'military/allied/field/flight commanders', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('commence', 'verb', 'kəˈmens', 'to begin to happen; to begin something', 'The meeting is scheduled to commence at noon.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('commentary', 'noun', 'ˈkɒməntri', 'a spoken description of an event that is given while it is happening, especially on the radio or television', 'a sports commentary', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('commentator', 'noun', 'ˈkɒmənteɪtə(r)', 'a person who describes an event while it is happening, especially on television or radio', 'a television/sports commentator', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('commerce', 'noun', 'ˈkɒmɜːs', 'trade, especially between countries; the buying and selling of goods and services', 'Leaders of industry and commerce met at the summit in Paris.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('commissioner', 'noun', 'kəˈmɪʃənə(r)', 'a member of a commission (= an official group of people who are responsible for controlling something or finding out about something)', 'the Church Commissioners (= the group of people responsible for controlling the financial affairs of the Church of England)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('commodity', 'noun', 'kəˈmɒdəti', 'a product or a raw material that can be bought and sold', 'rice, flour and other basic commodities', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('communist', 'adjective', 'ˈkɒmjənɪst', 'connected with communism', 'communist ideology', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('companion', 'noun', 'kəmˈpænjən', 'a person or an animal that travels with you or spends a lot of time with you', 'travelling companions', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('comparable', 'adjective', 'ˈkɒmpərəbl', 'similar to somebody/something else and able to be compared', 'A comparable house in the south of the city would cost twice as much.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('comparative', 'adjective', 'kəmˈpærətɪv', 'measured or judged by how similar or different it is to something else', 'Then he was living in comparative comfort (= compared with others or with his own life at a previous time).', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compassion', 'noun', 'kəmˈpæʃn', 'a strong feeling of sympathy for people or animals who are suffering and a desire to help them', 'to feel/show compassion', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compel', 'verb', 'kəmˈpel', 'to force somebody to do something; to make something necessary', 'compel somebody to do something, The law can compel fathers to make regular payments for their children.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compelling', 'adjective', 'kəmˈpelɪŋ', 'that makes you pay attention to it because it is so interesting and exciting', 'Her latest book makes compelling reading.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compensate', 'verb', 'ˈkɒmpenseɪt', 'to provide something good to balance or reduce the bad effects of damage, loss, etc.', 'Nothing can compensate for the loss of a loved one.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compensation', 'noun', 'ˌkɒmpenˈseɪʃn', 'something, especially money, that somebody gives you because they have hurt you, or damaged something that you own; the act of giving this to somebody', 'to claim/award/receive compensation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('competence', 'noun', 'ˈkɒmpɪtəns', 'the ability to do something well', 'to gain a high level of competence in English', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('competent', 'adjective', 'ˈkɒmpɪtənt', 'having enough skill or knowledge to do something well or to the necessary standard', 'He''s very competent in his work.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('competitor', 'noun', 'kəmˈpetɪtə(r)', 'a person who takes part in a competition', 'Over 200 competitors entered the race.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compile', 'verb', 'kəmˈpaɪl', 'to produce a book, list, report, etc. by bringing together different items, articles, songs, etc.; to collect information in order to produce a book, list, etc.', 'We are trying to compile a list of suitable people for the job.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('complement', 'verb', 'ˈkɒmplɪment', 'to add to something in a way that improves it or makes it more attractive', 'The excellent menu is complemented by a good wine list.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('completion', 'noun', 'kəmˈpliːʃn', 'the act or process of finishing something; the state of being finished and complete', 'the completion of the new hospital building', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('complexity', 'noun', 'kəmˈpleksəti', 'the state of being formed of many parts; the state of being difficult to understand', 'the increasing complexity of modern telecommunication systems', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compliance', 'noun', 'kəmˈplaɪəns', 'the practice of obeying rules or requests made by people in authority', 'compliance (with something), procedures that must be followed to ensure full compliance with the law', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('complication', 'noun', 'ˌkɒmplɪˈkeɪʃn', 'a thing that makes a situation more complicated or difficult', 'The bad weather added a further complication to our journey.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('comply', 'verb', 'kəmˈplaɪ', 'to obey a rule, an order, etc.; to meet particular standards', 'They refused to comply with the UN resolution.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('component', 'noun', 'kəmˈpəʊnənt', 'one of several parts of which something is made', 'the different organizations involved in the design of the various components ', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compose', 'verb', 'kəmˈpəʊz', 'to write music', 'Mozart composed his last opera shortly before he died.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('composer', 'noun', 'kəmˈpəʊzə(r)', 'a person who writes music, especially classical music', 'Verdi was a prolific composer of operas.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('composition', 'noun', 'ˌkɒmpəˈzɪʃn', 'the different parts that something is made of; the way in which the different parts are organized', 'the chemical composition of the soil', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compound', 'noun', 'ˈkɒmpaʊnd', 'a thing consisting of two or more separate things combined together', 'compounds derived from rainforest plants', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('comprehensive', 'adjective', 'ˌkɒmprɪˈhensɪv', 'including all, or almost all, the items, details, facts, information, etc., that may be involved', 'a comprehensive list of addresses', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('comprise', 'verb', 'kəmˈpraɪz', 'to have somebody/something as parts or members', 'comprise something, The collection comprises 327 paintings.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compromise', 'noun, verb', 'ˈkɒmprəmaɪz', 'an agreement made between two people or groups in which each side gives up some of the things they want so that both sides are happy at the end', 'After lengthy talks the two sides finally reached a compromise.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compulsory', 'adjective', 'kəmˈpʌlsəri', 'that must be done because of a law or a rule', 'English is a compulsory subject at this level.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('compute', 'verb', 'kəmˈpjuːt', 'to calculate something', 'The losses were computed at £5 million.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conceal', 'verb', 'kənˈsiːl', 'to hide somebody/something', 'conceal somebody/something, The paintings were concealed beneath a thick layer of plaster.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('concede', 'verb', 'kənˈsiːd', 'to admit that something is true, logical, etc. after first denying it or resisting it', '+ speech, ‘Not bad,’ she conceded grudgingly.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conceive', 'verb', 'kənˈsiːv', 'to form an idea, a plan, etc. in your mind', 'He conceived the idea of transforming the old power station into an arts centre.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conception', 'noun', 'kənˈsepʃn', 'an understanding or a belief of what something/somebody is or what something/somebody should be', 'conception of something, Marx’s conception of social justice', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('concession', 'noun', 'kənˈseʃn', 'something that you allow or do, or allow somebody to have, in order to end an argument or to make a situation less difficult', 'The firm will be forced to make concessions if it wants to avoid a strike.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('condemn', 'verb', 'kənˈdem', 'to say very strongly that you think something is bad, usually for moral reasons', 'condemn somebody/something, The government issued a statement condemning the killings.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('confer', 'verb', 'kənˈfɜː(r)', 'to discuss something with somebody, in order to exchange opinions or get advice', 'He wanted to confer with his colleagues before reaching a decision.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('confess', 'verb', 'kənˈfes', 'to admit, especially formally or to the police, that you have done something wrong or illegal', 'After hours of questioning, the suspect confessed.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('confession', 'noun', 'kənˈfeʃn', 'a statement that a person makes, admitting that they are guilty of a crime; the act of making such a statement', 'After hours of questioning by police, she made a full confession.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('configuration', 'noun', 'kənˌfɪɡəˈreɪʃn', 'an arrangement of the parts of something or a group of things; the form or shape that this arrangement produces', 'configuration of something, The design is based on four configurations of squares.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('confirmation', 'noun', 'ˌkɒnfəˈmeɪʃn', 'a statement, letter, etc. that shows that something is true, correct or definite', 'I''m still waiting for confirmation of the test results.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('confrontation', 'noun', 'ˌkɒnfrʌnˈteɪʃn', 'a situation in which there is anger between people or groups who disagree because they have different opinions', 'confrontation (with somebody), She wanted to avoid another confrontation with her father.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('congratulate', 'verb', 'kənˈɡrætʃəleɪt', 'to tell somebody that you are pleased about their success or achievements', 'I congratulated them all on their results.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('congregation', 'noun', 'ˌkɒŋɡrɪˈɡeɪʃn', 'a group of people who are gathered together in a church for a religious service, not including the priest and choir', 'The congregation stood to sing the hymn.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('congressional', 'adjective', 'kənˈɡreʃənl', 'related to or belonging to a congress or the Congress in the US', 'a congressional committee/bill', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('connected', 'adjective', 'kəˈnektɪd', '(of two or more things or people) having a link between them', 'We do not believe that the incidents are connected.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conquer', 'verb', 'ˈkɒŋkə(r)', 'to take control of a country or city and its people by force', 'The Normans conquered England in 1066.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conscience', 'noun', 'ˈkɒnʃəns', 'the part of your mind that tells you whether your actions are right or wrong', 'to have a clear/guilty conscience (= to feel that you have done right/wrong)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consciousness', 'noun', 'ˈkɒnʃəsnəs', 'the state of being able to use your senses and mental powers to understand what is happening', 'I can''t remember any more—I must have lost consciousness.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consecutive', 'adjective', 'kənˈsekjətɪv', 'following one after another in a continuous series ', 'She was absent for nine consecutive days.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consensus', 'noun', 'kənˈsensəs', 'an opinion that all members of a group agree with', 'consensus (about/on something), She is skilled at achieving consensus on sensitive issues.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consent', 'noun, verb', 'kənˈsent', 'permission to do something, especially given by somebody in authority', 'The written consent of a parent is required.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consequently', 'adverb', 'ˈkɒnsɪkwəntli', 'as a result; therefore', 'This poses a threat to agriculture and the food chain, and consequently to human health.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conservation', 'noun', 'ˌkɒnsəˈveɪʃn', 'the protection of the natural environment', 'to be interested in wildlife conservation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conserve', 'verb', 'kənˈsɜːv', 'to protect something and prevent it from being changed or destroyed', 'new laws to conserve wildlife in the area', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consist', 'verb', 'kənˈsɪst', '', NULL, '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consistency', 'noun', 'kənˈsɪstənsi', 'the quality of always behaving in the same way or of having the same opinions, standard, etc.; the quality of being consistent', 'She has played with great consistency all season.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consistent', 'adjective', 'kənˈsɪstənt', 'always behaving in the same way, or having the same opinions, standards, etc.', 'a consistent approach to the problem', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consistently', 'adverb', 'kənˈsɪstəntli', 'always the same', 'Her work has been of a consistently high standard.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consolidate', 'verb', 'kənˈsɒlɪdeɪt', 'to make a position of power or success stronger so that it is more likely to continue', 'With this new movie he has consolidated his position as the country''s leading director.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conspiracy', 'noun', 'kənˈspɪrəsi', 'a secret plan by a group of people to do something harmful or illegal', 'conspiracy (to do something), a conspiracy to overthrow the government', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('constituency', 'noun', 'kənˈstɪtʃuənsi', 'a district that elects its own representative to parliament', 'Unemployment is high in her constituency.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('constitute', 'verb', 'ˈkɒnstɪtjuːt', 'to be considered to be something', 'Does such an activity constitute a criminal offence?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('constitution', 'noun', 'ˌkɒnstɪˈtjuːʃn', 'the system of laws and basic principles that a state, a country or an organization is governed by', 'your right to vote under the constitution', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('constitutional', 'adjective', 'ˌkɒnstɪˈtjuːʃənl', '', NULL, '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('constraint', 'noun', 'kənˈstreɪnt', 'a thing that limits something, or limits your freedom to do something', 'constraints of time/money/space', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consultant', 'noun', 'kənˈsʌltənt', 'a person who knows a lot about a particular subject and is employed to give advice about it to other people', 'a technology/design consultant', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consultation', 'noun', 'ˌkɒnslˈteɪʃn', 'the act of discussing something with somebody or with a group of people before making a decision about it', 'a consultation document/paper/period/process', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consume', 'verb', 'kənˈsjuːm', 'to use something, especially fuel, energy or time', 'The electricity industry consumes large amounts of fossil fuels.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('consumption', 'noun', 'kənˈsʌmpʃn', 'the act of using energy, food or materials; the amount used', 'the production of fuel for domestic consumption (= to be used in the country where it is produced)', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contemplate', 'verb', 'ˈkɒntəmpleɪt', 'to think about whether you should do something, or how you should do something', 'contemplate something, You''re too young to be contemplating retirement.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contempt', 'noun', 'kənˈtempt', 'the feeling that somebody/something is without value and deserves no respect at all', 'with contempt, She looked at him with contempt.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contend', 'verb', 'kənˈtend', 'to say that something is true, especially in an argument', 'I would contend that the minister''s thinking is flawed on this point.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contender', 'noun', 'kənˈtendə(r)', 'a person or team with a chance of winning a competition', 'contender (for something), a contender for a gold medal in the Olympics', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contention', 'noun', 'kənˈtenʃn', 'anger between people who disagree', 'One area of contention is the availability of nursery care.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('continually', 'adverb', 'kənˈtɪnjuəli', 'in a way that is repeated many times so that it is annoying', 'They argue continually about money.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contractor', 'noun', 'kənˈtræktə(r)', 'a person or company that has a contract to do work or provide goods or services for another company', 'a building/roofing/electrical contractor ', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contradiction', 'noun', 'ˌkɒntrəˈdɪkʃn', 'a lack of agreement between facts, opinions, actions, etc.', 'contradiction (between A and B), There is a contradiction between the two sets of figures.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contrary', 'adjective, noun', 'ˈkɒntrəri', '', NULL, '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('contributor', 'noun', 'kənˈtrɪbjətə(r)', 'a person who writes articles for a magazine, book or website, or who talks on a radio or television programme or at a meeting', 'a regular contributor to this magazine', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('controversial', 'adjective', 'ˌkɒntrəˈvɜːʃl', 'causing a lot of angry public discussion and disagreement', 'a highly controversial topic', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('controversy', 'noun', 'ˈkɒntrəvɜːsi', 'public discussion and argument about something that many people strongly disagree about, think is bad, or are shocked by', 'to arouse/cause controversy', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('convenience', 'noun', 'kənˈviːniəns', 'the quality of being useful, easy or suitable for somebody', 'We have provided seats for the convenience of our customers.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conversion', 'noun', 'kənˈvɜːʃn', 'the act or process of changing something from one form, use or system to another', 'Their main business is the conversion of farm buildings into family homes.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('convey', 'verb', 'kənˈveɪ', 'to make ideas, feelings, etc. known to somebody', 'convey something, Colours like red convey a sense of energy and strength.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('convict', 'verb', 'kənˈvɪkt', 'to decide and state officially in court that somebody is guilty of a crime', 'be convicted (of something), He was convicted of fraud.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('conviction', 'noun', 'kənˈvɪkʃn', 'the act of finding somebody guilty of a crime in court; the fact of having been found guilty', 'He plans to appeal against his conviction.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('convinced', 'adjective', 'kənˈvɪnst', 'completely sure about something', 'Sam nodded but he didn''t look convinced.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('convincing', 'adjective', 'kənˈvɪnsɪŋ', 'that makes somebody believe that something is true', 'a convincing argument/explanation/case', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cooperate', 'verb', 'kəʊˈɒpəreɪt', 'to work together with somebody else in order to achieve something', 'The two groups agreed to cooperate with each other.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cooperative', 'adjective', 'kəʊˈɒpərətɪv', 'involving doing something together or working together with others towards a shared aim', 'Cooperative activity is essential to effective community work.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coordinate', 'verb', 'kəʊˈɔːdɪneɪt', 'to organize the different parts of an activity and the people involved in it so that it works well', 'coordinate something, They appointed a new manager to coordinate the work of the team.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coordination', 'noun', 'kəʊˌɔːdɪˈneɪʃn', 'the act of making parts of something, groups of people, etc. work together in an efficient and organized way', 'The aim was to improve the coordination of services.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coordinator', 'noun', 'kəʊˈɔːdɪneɪtə(r)', 'a person who organizes the different parts of an activity and the people involved in it so that it works well', 'The campaign needs an effective coordinator.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cop', 'noun', 'kɒp', 'a police officer', 'Somebody call the cops!', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cope', 'verb', 'kəʊp', 'to deal successfully with something difficult', 'I got to the stage where I wasn''t coping any more.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('copper', 'noun', 'ˈkɒpə(r)', 'a chemical element. Copper is a soft red-brown metal used for making electric wires, pipes and coins.', 'a copper mine', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('copyright', 'noun', 'ˈkɒpiraɪt', 'if a person or an organization holds the copyright on a piece of writing, music, etc., they are the only people who have the legal right to publish, broadcast, perform it, etc., and other people must ask their permission to use it or any part of it', 'Copyright expires seventy years after the death of the author.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('corporate', 'adjective', 'ˈkɔːpərət', 'connected with a large business company ', 'corporate finance/profits/tax', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('corporation', 'noun', 'ˌkɔːpəˈreɪʃn', 'a large business company', 'multinational corporations', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('correction', 'noun', 'kəˈrekʃn', 'a change that makes something more accurate than it was before', 'I''ve made a few small corrections to your report.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('correlate', 'verb', 'ˈkɒrəleɪt', 'if two or more facts, figures, etc. correlate or if a fact, figure, etc. correlates with another, the facts are closely connected and affect or depend on each other', 'The figures do not seem to correlate.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('correlation', 'noun', 'ˌkɒrəˈleɪʃn', 'a connection between two things in which one thing changes as the other does', 'correlation between A and B, There is a direct correlation between exposure to sun and skin cancer.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('correspond', 'verb', 'ˌkɒrəˈspɒnd', 'to be the same as or match something', 'Your account and hers do not correspond.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('correspondence', 'noun', 'ˌkɒrəˈspɒndəns', 'the letters, emails, etc. a person sends and receives', 'personal/private correspondence', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('correspondent', 'noun', 'ˌkɒrəˈspɒndənt', 'a person who reports news from a particular country or on a particular subject for a newspaper or a television or radio station', 'She''s the BBC''s political correspondent.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('corresponding', 'adjective', 'ˌkɒrəˈspɒndɪŋ', 'matching or connected with something that you have just mentioned', 'A change in the money supply brings a corresponding change in expenditure.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('corridor', 'noun', 'ˈkɒrɪdɔː(r)', 'a long narrow passage in a building, with doors that open into rooms on either side', 'His room is along the corridor.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('corrupt', 'adjective', 'kəˈrʌpt', 'willing to use their power to do dishonest or illegal things in return for money or to get an advantage', 'It was seen as the only way to overthrow a corrupt regime.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('corruption', 'noun', 'kəˈrʌpʃn', 'dishonest or illegal behaviour, especially of people in authority', 'allegations of bribery and corruption', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('costly', 'adjective', 'ˈkɒstli', 'costing a lot of money, especially more than you want to pay', 'Buying new furniture may prove too costly.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('costume', 'noun', 'ˈkɒstjuːm', 'the clothes worn by people from a particular place or during a particular historical period', 'an exhibition of Victorian costumes', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('councillor', 'noun', 'ˈkaʊnsələ(r)', 'a member of a city or county council', 'Councillor Ann Jones', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('counselling', 'noun', 'ˈkaʊnsəlɪŋ', 'professional advice about a problem', 'The couple decided to go for relationship counselling.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('counsellor', 'noun', 'ˈkaʊnsələ(r)', 'a person who has been trained to advise people with problems, especially personal problems', 'I went to see a debt counsellor and she agreed to come to the bank with me.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('counterpart', 'noun', 'ˈkaʊntəpɑːt', 'a person or thing that has the same position or function as somebody/something else in a different place or situation', 'The Foreign Minister held talks with his Chinese counterpart.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('countless', 'adjective', 'ˈkaʊntləs', 'very many; too many to be counted or mentioned', 'I''ve warned her countless times.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coup', 'noun', 'kuː', 'a sudden change of government that is illegal and often violent', 'He seized power in a military coup in 2008.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('courtesy', 'noun', 'ˈkɜːtəsi', 'polite behaviour that shows respect for other people', 'I was treated with the utmost courtesy by the staff.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('coverage', 'noun', 'ˈkʌvərɪdʒ', 'the reporting of news and sport in the media', 'media/newspaper/press coverage', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('crawl', 'verb', 'krɔːl', 'to move forward on your hands and knees or with your body close to the ground', 'Our baby is just starting to crawl.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('creation', 'noun', 'kriˈeɪʃn', 'the act or process of making something that is new, or of causing something to exist that did not exist before', 'Job creation needs to be the top priority.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('creative', 'adjective', 'kriˈeɪtɪv', 'involving the use of skill and the imagination to produce something new or a work of art', 'a course on creative writing (= writing stories, plays and poems)', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('creativity', 'noun', 'ˌkriːeɪˈtɪvəti', 'the use of skill and imagination to produce something new or to produce art', 'Creativity and originality are more important than technical skill.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('creator', 'noun', 'kriˈeɪtə(r)', 'a person who has made or invented a particular thing', 'Walt Disney, the creator of Mickey Mouse', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('credibility', 'noun', 'ˌkredəˈbɪləti', 'the quality that somebody/something has that makes people believe or trust them', 'to gain/lack/lose credibility', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('credible', 'adjective', 'ˈkredəbl', 'that can be believed or trusted', 'a credible explanation/witness', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('creep', 'verb', 'kriːp', 'to move slowly, quietly and carefully, because you do not want to be seen or heard', 'I crept up the stairs, trying not to wake my parents.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('crew', 'noun', 'kruː', 'all the people working on a ship, plane, etc.', 'crew members', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('critic', 'noun', 'ˈkrɪtɪk', 'a person who expresses opinions about the good and bad qualities of books, music, etc.', 'a film/an art/a music critic', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('critically', 'adverb', 'ˈkrɪtɪkli', 'in a way that says what you think is bad about somebody/something', 'She spoke critically of her father.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('critique', 'noun', 'krɪˈtiːk', 'a piece of written criticism of a set of ideas, a work of art, etc.', 'She wrote a feminist critique of Freud''s theories.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('crude', 'adjective', 'kruːd', 'in its natural state, before it has been processed or refined', 'crude oil/metal', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cruise', 'noun, verb', 'kruːz', 'a journey by sea, visiting different places, especially as a holiday', 'I''d love to go on a round-the-world cruise.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('crystal', 'noun', 'ˈkrɪstl', 'a small piece of a substance with many even sides, that is formed naturally when the substance becomes solid', 'ice/salt crystals', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cue', 'noun', 'kjuː', 'an action or event that is a signal for somebody to do something', 'cue (for something), Jon''s arrival was a cue for more champagne.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cult', 'adjective, noun', 'kʌlt', 'very popular with a particular group of people', 'a cult movie/book', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cultivate', 'verb', 'ˈkʌltɪveɪt', 'to prepare and use land for growing plants or crops', 'The land around here has never been cultivated.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('curiosity', 'noun', 'ˌkjʊəriˈɒsəti', 'a strong desire to know about something', 'Children show curiosity about everything.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('currency', 'noun', 'ˈkʌrənsi', 'the system of money that a country uses', 'trading in foreign currencies', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('curriculum', 'noun', 'kəˈrɪkjələm', 'the subjects that are included in a course of study or taught in a school, college, etc.', 'The school curriculum should be as broad as possible.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('custody', 'noun', 'ˈkʌstədi', 'the legal right or duty to take care of or keep somebody/something; the act of taking care of something/somebody', 'Who will have custody of the children?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cute', 'adjective', 'kjuːt', 'pretty and attractive', 'a cute little baby', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cutting', 'noun', 'ˈkʌtɪŋ', 'an article or a story that you cut from a newspaper or magazine and keep', 'newspaper/press cuttings', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('cynical', 'adjective', 'ˈsɪnɪkl', 'believing that people only do things to help themselves rather than for good or honest reasons', 'a cynical view/smile', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dairy', 'adjective, noun', 'ˈdeəri', 'made from milk', 'dairy products/produce', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dam', 'noun', 'dæm', 'a barrier that is built across a river in order to stop the water from flowing, used especially to make a reservoir (= a lake for storing water) or to produce electricity', 'the Narmada dam in India', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('damaging', 'adjective', 'ˈdæmɪdʒɪŋ', 'causing damage; having a bad effect on somebody/something', 'damaging consequences/effects', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('darkness', 'noun', 'ˈdɑːknəs', 'the state of being dark, without any light', 'After a few minutes our eyes got used to the darkness.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('database', 'noun', 'ˈdeɪtəbeɪs', 'an organized set of data that is stored in a computer and can be looked at and used in various ways', 'The database is updated monthly.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dawn', 'noun', 'dɔːn', 'the time of day when light first appears', 'at dawn, They start work at dawn.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deadline', 'noun', 'ˈdedlaɪn', 'a point in time by which something must be done', 'I prefer to work to a deadline.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deadly', 'adjective', 'ˈdedli', 'causing or likely to cause death', 'a deadly weapon/disease', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dealer', 'noun', 'ˈdiːlə(r)', 'a person whose business is buying and selling a particular product', 'an art/antique dealer', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('debris', 'noun', 'ˈdebriː', 'pieces of wood, metal, building materials, etc. that are left after something has been destroyed', 'Emergency teams are still clearing the debris from the plane crash.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('debut', 'noun', 'ˈdeɪbjuː', 'the first public appearance of a performer or sports player', 'He will make his debut for the first team this week.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('December', 'noun', 'dɪˈsembə(r)', 'the 12th and last month of the year', 'She was born in December.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('decent', 'adjective', 'ˈdiːsnt', 'of a good enough standard or quality', 'a decent meal/place to live ', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('decision-making', 'noun', 'dɪˈsɪʒn meɪkɪŋ', 'the process of deciding about something important, especially in a group of people or in an organization', 'responsibility for decision-making', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('decisive', 'adjective', 'dɪˈsaɪsɪv', 'very important for the final result of a particular situation', 'a decisive factor/victory/battle', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deck', 'noun', 'dek', 'the top outside floor of a ship or boat', 'on deck, I was the only person on deck at that time of night.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('declaration', 'noun', 'ˌdekləˈreɪʃn', 'an official or formal statement, especially about the plans of a government or an organization; the act of making such a statement', 'to issue/sign a declaration', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dedicated', 'adjective', 'ˈdedɪkeɪtɪd', 'working hard at something because it is very important to you', 'a dedicated teacher', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dedication', 'noun', 'ˌdedɪˈkeɪʃn', 'the hard work and effort that somebody puts into an activity or a purpose because they think it is important', 'hard work and dedication', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deed', 'noun', 'diːd', 'a thing that somebody does that is usually very good or very bad', 'It''s a stirring tale of heroic deeds.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deem', 'verb', 'diːm', 'to have a particular opinion about somebody/something', 'deem somebody/something + noun, The evening was deemed a great success.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('default', 'noun', 'dɪˈfɔːlt', 'what happens or appears if you do not make any other choice or change, especially in a computer program', 'The default is fifty lines.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('defect', 'noun', 'ˈdiːfekt', 'a fault in something or in the way it has been made that means that it is not perfect', 'a defect in the glass', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('defender', 'noun', 'dɪˈfendə(r)', 'a player who must stop the other team from scoring in games such as football (soccer), hockey, etc.', 'a passionate defender of human rights', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('defensive', 'adjective', 'dɪˈfensɪv', 'protecting somebody/something against attack', 'As a defensive measure he built a series of coastal forts and watchtowers.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deficiency', 'noun', 'dɪˈfɪʃnsi', 'the state of not having, or not having enough of, something that is essential', 'deficiency (in something), Vitamin deficiency in the diet can cause illness.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deficit', 'noun', 'ˈdefɪsɪt', 'the amount by which money spent or owed is greater than money earned in a particular period of time', 'a budget/trade deficit', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('defy', 'verb', 'dɪˈfaɪ', 'to refuse to obey or show respect for somebody in authority, a law, a rule, etc.', 'I wouldn''t have dared to defy my teachers.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('delegate', 'noun', 'ˈdelɪɡət', 'a person who is chosen or elected to represent the views of a group of people and vote and make decisions for them', 'Congress delegates rejected the proposals.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('delegation', 'noun', 'ˌdelɪˈɡeɪʃn', 'a group of people who represent the views of an organization, a country, etc.', 'the Dutch delegation to the United Nations', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('delete', 'verb', 'dɪˈliːt', 'to remove something that has been written or printed, or that has been stored on a computer', 'Your name has been deleted from the list.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('delicious', 'adjective', 'dɪˈlɪʃəs', 'having a very pleasant taste or smell', 'Who cooked this? It''s absolutely delicious.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('democracy', 'noun', 'dɪˈmɒkrəsi', 'a system of government in which the people of a country can vote to elect their representatives', 'parliamentary democracy', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('democratic', 'adjective', 'ˌdeməˈkrætɪk', 'controlled by representatives who are elected by the people of a country; connected with this system', 'a democratic country', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('demon', 'noun', 'ˈdiːmən', 'an evil spirit', 'The people believed the girl was possessed by demons.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('demonstration', 'noun', 'ˌdemənˈstreɪʃn', 'a public meeting or a march (= an organized walk by many people) at which people show that they are protesting against or supporting somebody/something', 'to take part in/go on a demonstration', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('denial', 'noun', 'dɪˈnaɪəl', 'a statement that something is not true or does not exist; the action of denying something', 'denial (of something), the prisoner’s repeated denials of the charges against him', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('denounce', 'verb', 'dɪˈnaʊns', 'to strongly criticize somebody/something that you think is wrong, illegal, etc.', 'denounce somebody/something, She publicly denounced the government''s handling of the crisis.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dense', 'adjective', 'dens', 'containing a lot of people, things, plants, etc. with little space between them', 'a dense crowd/forest', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('density', 'noun', 'ˈdensəti', 'the quality of being dense; the degree to which something is dense', 'The population density in this city is very high.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('depart', 'verb', 'dɪˈpɑːt', 'to leave a place, especially to start a trip', 'depart (for…) (from…), Flights for Rome depart from Terminal 3.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dependence', 'noun', 'dɪˈpendəns', 'the state of needing the help and support of somebody/something in order to survive or be successful', 'Our relationship was based on mutual dependence.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dependent', 'adjective', 'dɪˈpendənt', 'needing somebody/something in order to survive or be successful', 'a woman with several dependent children', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('depict', 'verb', 'dɪˈpɪkt', 'to show an image of somebody/something in a picture', 'depict somebody/something (as somebody/something), a painting depicting the Virgin and Child', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deploy', 'verb', 'dɪˈplɔɪ', 'to move soldiers or weapons into a position where they are ready for military action', '2 000 troops were deployed in the area.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deployment', 'noun', 'dɪˈplɔɪmənt', 'the act of moving soldiers or weapons into a position where they are ready for military action', 'the deployment of peacekeeping forces', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('depression', 'noun', 'dɪˈpreʃn', 'a medical condition in which a person feels very sad, anxious and without hope and often has physical symptoms such as being unable to sleep, etc.', 'She was diagnosed as having clinical depression.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deprive', 'verb', 'dɪˈpraɪv', '', NULL, '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deputy', 'noun', 'ˈdepjuti', 'a person who is the next most important person below a business manager, a head of a school, a political leader, etc. and who does that person’s job when they are away', 'I''m acting as deputy till the manager returns.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('descend', 'verb', 'dɪˈsend', 'to come or go down from a higher to a lower level', 'The plane began to descend.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('descent', 'noun', 'dɪˈsent', 'an action of coming or going down', 'The plane began its descent to Heathrow.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('designate', 'verb', 'ˈdezɪɡneɪt', 'to say officially that somebody/something has a particular character or name; to describe somebody/something in a particular way', 'be designated (as) something, This area has been designated (as) a National Park.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('designer', 'noun', 'dɪˈzaɪnə(r)', 'a person whose job is to decide how things such as clothes, furniture, tools, etc. will look or work by making drawings, plans or patterns', 'one of the country''s top fashion designers', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('desirable', 'adjective', 'dɪˈzaɪərəbl', 'that you would like to have or do; worth having or doing', 'She chatted for a few minutes about the qualities she considered desirable in a secretary.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('desktop', 'noun', 'ˈdesktɒp', 'a screen on a computer that shows the icons of programs and files that can be used', 'desktop icons', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('destination', 'noun', 'ˌdestɪˈneɪʃn', 'a place to which somebody/something is going or being sent', 'popular tourist/holiday destinations like the Bahamas', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('destructive', 'adjective', 'dɪˈstrʌktɪv', 'causing destruction or damage', 'The war demonstrated the destructive power of modern weapons.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('detain', 'verb', 'dɪˈteɪn', 'to keep somebody in an official place, such as a police station, a prison or a hospital, and prevent them from leaving', 'One man has been detained for questioning.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('detect', 'verb', 'dɪˈtekt', 'to discover or notice something, especially something that is not easy to see, hear, etc.', 'The tests are designed to detect the disease early.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('detection', 'noun', 'dɪˈtekʃn', 'the process of discovering or noticing something, especially something that is not easy to see, hear, etc.; the fact of being discovered or noticed ', 'crime prevention and detection', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('detective', 'noun', 'dɪˈtektɪv', 'a person, especially a police officer, whose job is to investigate crimes and catch criminals', 'a police/homicide/undercover detective', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('detention', 'noun', 'dɪˈtenʃn', 'the state of being kept in a place, especially a prison, and prevented from leaving', 'They were sentenced to 12 months'' detention in a young offender institution.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('deteriorate', 'verb', 'dɪˈtɪəriəreɪt', 'to become worse', 'Her health deteriorated rapidly, and she died shortly afterwards.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('devastate', 'verb', 'ˈdevəsteɪt', 'to completely destroy a place or an area', 'The bomb devastated much of the old part of the city.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('devil', 'noun', 'ˈdevl', 'the most powerful evil being', 'belief in the Devil', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('devise', 'verb', 'dɪˈvaɪz', 'to invent something new or a new way of doing something', 'A new system has been devised to control traffic in the city.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('diagnose', 'verb', 'ˈdaɪəɡnəʊz', 'to say exactly what an illness or the cause of a problem is', 'diagnose something, The test is used to diagnose a variety of diseases.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('diagnosis', 'noun', 'ˌdaɪəɡˈnəʊsɪs', 'the act of discovering or identifying the exact cause of an illness or a problem', 'a diagnosis of lung cancer', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dialogue', 'noun', 'ˈdaɪəlɒɡ', 'a conversation in a book, play or film or in language teaching materials', 'Learners are asked to listen to three short dialogues.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dictate', 'verb', 'dɪkˈteɪt', 'to tell somebody what to do, especially in an annoying way', 'dictate something (to somebody), They are in no position to dictate terms (= tell other people what to do).', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dictator', 'noun', 'dɪkˈteɪtə(r)', 'a political leader who has complete power over a country, especially one who has gained it using military force', 'The country suffered at the hands of a series of military dictators.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('differ', 'verb', 'ˈdɪfə(r)', 'to be different from somebody/something', 'They hold differing views.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('differentiate', 'verb', 'ˌdɪfəˈrenʃieɪt', 'to recognize or show that two things are not the same', 'differentiate (between) A and B, It''s difficult to differentiate between the two varieties.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('digital', 'adjective', 'ˈdɪdʒɪtl', 'using a system of receiving and sending information as a series of the numbers one and zero, showing that an electronic signal is there or is not there', 'a digital camera ', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dignity', 'noun', 'ˈdɪɡnəti', 'a calm and serious manner that deserves respect', 'She accepted the criticism with quiet dignity.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dilemma', 'noun', 'dɪˈlemə', 'a situation that makes problems, often one in which you have to make a very difficult choice between things of equal importance', 'I could see no way of resolving this moral dilemma.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dimension', 'noun', 'daɪˈmenʃn', 'a measurement in space, for example how high, wide or long something is', 'We measured the dimensions of the kitchen.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('diminish', 'verb', 'dɪˈmɪnɪʃ', 'to become smaller, weaker, etc.; to make something become smaller, weaker, etc.', 'The world''s resources are rapidly diminishing.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dip', 'verb', 'dɪp', 'to put something quickly into a liquid and take it out again', 'dip something (into something), He dipped the brush into the paint.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('diplomat', 'noun', 'ˈdɪpləmæt', 'a person whose job is to represent his or her country in a foreign country, for example, in an embassy', 'Washington''s top diplomat in Havana', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('diplomatic', 'adjective', 'ˌdɪpləˈmætɪk', 'connected with managing relations between countries (= diplomacy)', 'a diplomatic crisis', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('directory', 'noun', 'dəˈrektəri', 'a book or electronic resource containing lists of information, usually in alphabetical order, for example people’s phone numbers or the names and addresses of businesses in a particular area', 'a telephone/trade directory', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disability', 'noun', 'ˌdɪsəˈbɪləti', 'a physical or mental condition that makes it difficult for somebody to do some things that most other people can do', 'a physical/developmental/intellectual disability', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disastrous', 'adjective', 'dɪˈzɑːstrəs', 'very bad, harmful or unsuccessful', 'a disastrous harvest/fire/result', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disc', 'noun', 'dɪsk', 'a thin flat round object', 'He wears an identity disc around his neck.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('discard', 'verb', 'dɪˈskɑːd', 'to get rid of something that you no longer want or need', 'discard somebody/something, The room was littered with discarded newspapers.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('discharge', 'verb', 'dɪsˈtʃɑːdʒ', 'to give somebody official permission to leave the police or the armed forces; to make somebody leave the police or the armed forces', 'be discharged from something, He was discharged from the army following his injury.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disclose', 'verb', 'dɪsˈkləʊz', 'to give somebody information about something, especially something that was previously secret', 'disclose something (to somebody), The spokesman refused to disclose details of the takeover to the press.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disclosure', 'noun', 'dɪsˈkləʊʒə(r)', 'the act of making something known or public that was previously secret or private', 'the newspaper’s disclosure of defence secrets', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('discourage', 'verb', 'dɪsˈkʌrɪdʒ', 'to try to prevent something or to prevent somebody from doing something, especially by making it difficult to do or by showing that you do not approve of it', 'discourage (doing) something, a campaign to discourage smoking among teenagers', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('discourse', 'noun', 'ˈdɪskɔːs', 'a long and serious treatment or discussion of a subject in speech or writing', 'discourse on something, a discourse on issues of gender and sexuality', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('discretion', 'noun', 'dɪˈskreʃn', 'the freedom or power to decide what should be done in a particular situation', 'I''ll leave it up to you to use your discretion.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('discrimination', 'noun', 'dɪˌskrɪmɪˈneɪʃn', 'the practice of treating somebody or a particular group in society less fairly than others', 'age/racial/gender/sex discrimination (= because of somebody’s age, race or sex)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dismissal', 'noun', 'dɪsˈmɪsl', 'the act of dismissing somebody from their job; an example of this', 'He still hopes to win his claim against unfair dismissal.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disorder', 'noun', 'dɪsˈɔːdə(r)', 'a condition or illness that causes problems with the way part of the body or brain works', 'a blood/bowel disorder', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('displace', 'verb', 'dɪsˈpleɪs', 'to take the place of somebody/something', 'be displaced (by somebody/something), Gradually factory workers have been displaced by machines.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disposal', 'noun', 'dɪˈspəʊzl', 'the act of getting rid of something', 'The council is responsible for waste disposal and street cleaning.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dispose', 'verb', 'dɪˈspəʊz', 'to arrange things or people in a particular way or position', 'The visitors disposed themselves in a circle round the statue.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dispute', 'noun, verb', 'dɪˈspjuːt', 'an argument between two people, groups or countries; discussion about a subject on which people disagree', 'industrial/pay disputes', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disrupt', 'verb', 'dɪsˈrʌpt', 'to make it difficult for something to continue in the normal way', 'Demonstrators succeeded in disrupting the meeting.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('disruption', 'noun', 'dɪsˈrʌpʃn', 'a situation in which it is difficult for something to continue in the normal way; the act of stopping something from continuing in the normal way', 'We aim to help you move house with minimum disruption to yourself.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('distant', 'adjective', 'ˈdɪstənt', 'far away in space or time', 'the distant sound of music', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('distinct', 'adjective', 'dɪˈstɪŋkt', 'easily or clearly heard, seen, felt, etc.', 'There was a distinct smell of gas.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('distinction', 'noun', 'dɪˈstɪŋkʃn', 'a clear difference or contrast especially between people or things that are similar or related', 'distinctions between traditional and modern societies', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('distinctive', 'adjective', 'dɪˈstɪŋktɪv', 'having a quality or characteristic that makes something different and easily noticed', 'clothes with a distinctive style', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('distort', 'verb', 'dɪˈstɔːt', 'to change the shape, appearance or sound of something so that it is strange or not clear', 'a fairground mirror that distorts your shape', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('distract', 'verb', 'dɪˈstrækt', 'to take somebody’s attention away from what they are trying to do', 'You''re distracting me from my work.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('distress', 'noun, verb', 'dɪˈstres', 'a feeling of great worry or unhappiness; great mental pain', 'The newspaper article caused the actor considerable distress.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dive', 'noun, verb', 'daɪv', 'a jump into deep water with your head first and your arms in front of you', 'a spectacular high dive (= from high above the water)', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('diverse', 'adjective', 'daɪˈvɜːs', 'very different from each other and of various kinds', 'People from diverse cultures were invited to the event.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('diversity', 'noun', 'daɪˈvɜːsəti', 'a range of many people or things that are very different from each other', 'the biological diversity of the rainforests', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('divert', 'verb', 'daɪˈvɜːt', 'to make somebody/something change direction', 'be diverted, The course of the stream has now been diverted.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('divine', 'adjective', 'dɪˈvaɪn', 'coming from or connected with God or a god', 'divine law/love/will', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('doctor', 'noun', 'ˈdɒktə(r)', 'a person who has been trained in medical science, whose job is to treat people who are ill or injured', 'You''d better see a doctor about that cough.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('doctrine', 'noun', 'ˈdɒktrɪn', 'a belief or set of beliefs held and taught by a Church, a political party, etc.', 'the doctrine of parliamentary sovereignty', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('documentary', 'noun', 'ˌdɒkjuˈmentri', 'a film or a radio or television programme giving facts about something', 'There were some interesting interviews in the documentary.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('documentation', 'noun', 'ˌdɒkjumenˈteɪʃn', 'the documents that are required for something, or that give evidence or proof of something', 'I couldn''t enter the country because I didn''t have all the necessary documentation.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('domain', 'noun', 'dəˈmeɪn', 'an area of knowledge or activity; especially one that somebody is responsible for', 'Financial matters are her domain.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dominance', 'noun', 'ˈdɒmɪnəns', 'the fact of being more important, powerful or easy to notice than somebody/something else', 'political/economic dominance', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dominant', 'adjective', 'ˈdɒmɪnənt', 'more important, powerful or easy to notice than other things', 'The firm has achieved a dominant position in the world market.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('donate', 'verb', 'dəʊˈneɪt', 'to give money, food, clothes, etc. to somebody/something, especially a charity', 'donate something to somebody/something, He donated thousands of pounds to charity.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('donation', 'noun', 'dəʊˈneɪʃn', 'something that is given to a person or an organization such as a charity, in order to help them; the act of giving something in this way', 'a generous/large/small donation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('donor', 'noun', 'ˈdəʊnə(r)', 'a person or an organization that makes a gift of money, clothes, food, etc. to a charity, etc.', 'international aid donors (= countries that give money, etc. to help other countries)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dose', 'noun', 'dəʊs', 'an amount of a medicine or a drug that is taken once, or regularly over a period of time', 'a high/low/lethal dose', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('download', 'noun, verb', 'ˈdaʊnləʊd', 'data that is downloaded from another computer system', 'A staggering 99.8 % of digital music downloads are to mobile handsets. ', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('downtown', 'adjective, adverb, noun', 'ˌdaʊnˈtaʊn', 'in, towards or typical of the centre of a city, especially its main business area', 'a downtown store', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('drain', 'verb', 'dreɪn', 'to make something empty or dry by removing the liquid from it; to become empty or dry in this way', 'Drain and rinse the pasta.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('drift', 'verb', 'drɪft', 'to move along smoothly and slowly in water or air', 'Clouds drifted across the sky.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('drought', 'noun', 'draʊt', 'a long period of time when there is little or no rain', 'Farmers are facing ruin after two years of severe drought.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('drown', 'verb', 'draʊn', 'to die because you have been underwater too long and you cannot breathe; to kill somebody by holding them underwater', 'Two children drowned after falling into the river.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dual', 'adjective', 'ˈdjuːəl', 'having two parts or aspects', 'his dual role as composer and conductor', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dub', 'verb', 'dʌb', 'to give somebody/something a particular name, often in a humorous or critical way', 'The media dubbed anorexia ‘the slimming disease’.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dumb', 'adjective', 'dʌm', 'stupid', 'That was a pretty dumb thing to do.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('duo', 'noun', 'ˈdjuːəʊ', 'two people who perform together or are often seen or thought of together', 'the comedy duo Laurel and Hardy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('duration', 'noun', 'djuˈreɪʃn', 'the length of time that something lasts or continues', 'The school was used as a hospital for the duration of the war.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('dynamic', 'adjective, noun', 'daɪˈnæmɪk', 'having a lot of energy and a strong personality', 'a dynamic leader', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eager', 'adjective', 'ˈiːɡə(r)', 'very interested and excited by something that is going to happen or about something that you want to do; showing this', 'eager crowds outside the stadium', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('earnings', 'noun', 'ˈɜːnɪŋz', 'the money that you earn for the work that you do', 'a rise in average earnings', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('earthquake', 'noun', 'ˈɜːθkweɪk', 'a sudden, violent shaking of the earth’s surface', 'a devastating/massive/powerful earthquake', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('echo', 'noun, verb', 'ˈekəʊ', 'the reflecting of sound off a wall or inside a particular space so that a noise appears to be repeated; a sound that is reflected back in this way', 'There was an echo on the phone and I couldn''t hear clearly.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ecological', 'adjective', 'ˌiːkəˈlɒdʒɪkl', 'connected with the relation of plants and living creatures to each other and to their environment', 'We risk upsetting the ecological balance of the area.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('economics', 'noun', 'ˌiːkəˈnɒmɪks', 'the study of how a society organizes its money, trade and industry', 'He studied politics and economics at Yale.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('economist', 'noun', 'ɪˈkɒnəmɪst', 'a person who studies or writes about economics', 'the World Bank''s chief economist', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('edit', 'verb', 'ˈedɪt', 'to prepare a piece of writing, a book, etc. to be published by correcting the mistakes, making improvements to it, etc.', 'edit (something), This draft text will need to be edited.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('editorial', 'adjective', 'ˌedɪˈtɔːriəl', 'connected with the task of preparing something such as a newspaper, a book or a television or radio programme, to be published or broadcast', 'the magazine’s editorial staff', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('educational', 'adjective', 'ˌedʒuˈkeɪʃənl', 'connected with education', 'children with special educational needs', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('educator', 'noun', 'ˈedʒukeɪtə(r)', 'a person whose job is to teach or educate people', 'adult educators (= who teach adults)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('effectiveness', 'noun', 'ɪˈfektɪvnəs', 'the fact of producing the result that is wanted or intended; the fact of producing a successful result', 'to check the effectiveness of the security system', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('efficiency', 'noun', 'ɪˈfɪʃnsi', 'the quality of doing something well with no waste of time or money', 'improvements in efficiency at the factory', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ego', 'noun', 'ˈiːɡəʊ', 'your sense of your own value and importance', 'He has the biggest ego of anyone I''ve ever met.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eight', 'number', 'eɪt', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eighteen', 'number', 'ˌeɪˈtiːn', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eighty', 'number', 'ˈeɪti', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('elaborate', 'adjective', 'ɪˈlæbərət', 'very complicated and detailed; carefully prepared and organized', 'elaborate designs', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('electoral', 'adjective', 'ɪˈlektərəl', 'connected with elections', 'electoral systems/reforms', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('electronics', 'noun', 'ɪˌlekˈtrɒnɪks', 'the branch of science and technology that studies electric currents in electronic equipment', 'the electronics industry', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('elementary', 'adjective', 'ˌelɪˈmentri', 'in or connected with the first stages of a course of study', 'an elementary English course', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('elephant', 'noun', 'ˈelɪfənt', 'a very large animal with thick grey skin, large ears, two curved outer teeth called tusks and a long nose called a trunk. There are two types of elephant, the African and the Asian.', 'herds of elephants', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('elevate', 'verb', 'ˈelɪveɪt', 'to give somebody/something a higher position or rank, often more important than they deserve ', 'elevate somebody/something (to something), He elevated many of his friends to powerful positions within the government.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eleven', 'number', 'ɪˈlevn', '11', 'There are only eleven of these rare animals left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eligible', 'adjective', 'ˈelɪdʒəbl', 'a person who is eligible for something or to do something, is able to have or do it because they have the right qualifications, are the right age, etc.', 'eligible (for something), Only those over 70 are eligible for the special payment.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eliminate', 'verb', 'ɪˈlɪmɪneɪt', 'to remove or get rid of something', 'eliminate something, Credit cards eliminate the need to carry a lot of cash.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('elite', 'noun', 'eɪˈliːt', 'a small group of people in a society, etc. who are powerful and have a lot of influence, because they are rich, intelligent, etc.', 'a member of the ruling/intellectual elite', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('email', 'noun, verb', 'ˈiːmeɪl', 'a way of sending messages and data to other people by means of computers connected together in a network', 'I will be on vacation for a week in November, with no access to email.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('embark', 'verb', 'ɪmˈbɑːk', 'to get onto a ship or plane; to put somebody/something onto a ship or plane', 'We stood on the pier and watched as they embarked.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('embassy', 'noun', 'ˈembəsi', 'a group of officials led by an ambassador who represent their government in a foreign country', 'embassy officials', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('embed', 'verb', 'ɪmˈbed', 'to fix something in a substance or solid object', 'be embedded in something, an operation to remove glass that was embedded in his leg', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('embody', 'verb', 'ɪmˈbɒdi', 'to express or represent an idea or a quality', 'embody something, a politician who embodied the hopes of black youth', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('embrace', 'verb', 'ɪmˈbreɪs', 'to put your arms around somebody as a sign of love or friendship', 'They embraced and promised to keep in touch.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('emergence', 'noun', 'ɪˈmɜːdʒəns', 'the fact of somebody/something moving out of or away from something and becoming possible to see', 'the island’s emergence from the sea 3 000 years ago', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('emission', 'noun', 'ɪˈmɪʃn', 'the production or sending out of light, heat, gas, etc.', 'the emission of carbon dioxide into the atmosphere', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('empirical', 'adjective', 'ɪmˈpɪrɪkl', 'based on experiments or experience rather than ideas or theories', 'empirical evidence/knowledge/research', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('empower', 'verb', 'ɪmˈpaʊə(r)', 'to give somebody the power or authority to do something', 'be empowered (to do something), The courts were empowered to impose the death sentence for certain crimes.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enact', 'verb', 'ɪˈnækt', 'to pass a law', '(be) enacted (by somebody/something), legislation enacted by parliament', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('encompass', 'verb', 'ɪnˈkʌmpəs', 'to include a large number or range of things', 'The job encompasses a wide range of responsibilities.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('encouraging', 'adjective', 'ɪnˈkʌrɪdʒɪŋ', 'that gives somebody support, courage or hope', 'This month''s unemployment figures are not very encouraging.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('endeavour', 'noun', 'ɪnˈdevə(r)', 'an attempt to do something, especially something new or difficult', 'There have been great advances in the field of scientific endeavour.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('endless', 'adjective', 'ˈendləs', 'very large in size or amount and seeming to have no end', 'endless patience', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('endorse', 'verb', 'ɪnˈdɔːs', 'to say publicly that you support a person, statement or course of action', 'I wholeheartedly endorse his remarks.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('endorsement', 'noun', 'ɪnˈdɔːsmənt', 'a public statement or action showing that you support somebody/something', 'The election victory is a clear endorsement of their policies.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('endure', 'verb', 'ɪnˈdjʊə(r)', 'to experience and deal with something that is painful or unpleasant without giving up', 'endure something, They had to endure a long wait before the case came to trial.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enforce', 'verb', 'ɪnˈfɔːs', 'to make sure that people obey a particular law or rule', 'enforce something, It''s the job of the police to enforce the law.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enforcement', 'noun', 'ɪnˈfɔːsmənt', 'the act of making people obey a particular law or rule', 'strict enforcement of regulations', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('engagement', 'noun', 'ɪnˈɡeɪdʒmənt', 'an agreement to marry somebody; the period during which two people are engaged', 'Their engagement was announced in the local paper.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('engaging', 'adjective', 'ɪnˈɡeɪdʒɪŋ', 'interesting or pleasant in a way that attracts your attention', 'an engaging smile', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enhance', 'verb', 'ɪnˈhɑːns', 'to increase or further improve the good quality, value or status of somebody/something', 'This is an opportunity to enhance the reputation of the company.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enquire', 'verb', 'ɪnˈkwaɪə(r)', 'to ask somebody for some information', 'enquire about somebody/something, I called the station to enquire about train times.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enrich', 'verb', 'ɪnˈrɪtʃ', 'to improve the quality of something, often by adding something to it', 'The study of science has enriched all our lives.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enrol', 'verb', 'ɪnˈrəʊl', 'to arrange for yourself or for somebody else to officially join a course, school, etc.', 'You need to enrol before the end of August.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ensue', 'verb', 'ɪnˈsjuː', 'to happen after or as a result of another event', 'An argument ensued.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enterprise', 'noun', 'ˈentəpraɪz', 'a company or business', 'He is in charge of an enterprise with a turnover of $26 billion.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('enthusiast', 'noun', 'ɪnˈθjuːziæst', 'a person who is very interested in something and spends a lot of time doing it', 'a football enthusiast', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('entity', 'noun', 'ˈentəti', 'something that exists separately from other things and has its own identity', 'The unit has become part of a larger department and no longer exists as a separate entity.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('entrepreneur', 'noun', 'ˌɒntrəprəˈnɜː(r)', 'a person who makes money by starting or running businesses, especially when this involves taking financial risks', 'A creative entrepreneur, he was continually dreaming up new projects.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('epidemic', 'noun', 'ˌepɪˈdemɪk', 'a large number of cases of a particular disease or medical condition happening at the same time in a particular community', 'the outbreak of a flu epidemic', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('episode', 'noun', 'ˈepɪsəʊd', 'one part of a story that is broadcast on television or radio in several parts', 'The next episode has not yet been filmed.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('equality', 'noun', 'iˈkwɒləti', 'the fact of being equal in rights, status, advantages, etc.', 'racial/social/gender equality', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('equation', 'noun', 'ɪˈkweɪʒn', 'a statement showing that two amounts or values are equal, for example 2x + y = 54', 'the numbers on the right-hand side of the equation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('equip', 'verb', 'ɪˈkwɪp', 'to provide yourself/somebody/something with the things that are needed for a particular purpose or activity', 'equip something, to be fully/poorly equipped', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('era', 'noun', 'ˈɪərə', 'a period of time, usually in history, that is different from other periods because of particular characteristics or events', 'the Victorian/modern/post-war era', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('erect', 'verb', 'ɪˈrekt', 'to build something', 'The church was erected in 1582.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('erupt', 'verb', 'ɪˈrʌpt', 'when a volcano erupts or burning rocks, smoke, etc. erupt or are erupted, the burning rocks, etc. are thrown out from the volcano', 'The volcano could erupt at any time.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('escalate', 'verb', 'ˈeskəleɪt', 'to become greater, worse, more serious, etc.; to make something greater, worse, more serious, etc.', 'the escalating costs of healthcare', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('essence', 'noun', 'ˈesns', 'the most important quality or feature of something, that makes it what it is', 'His paintings capture the essence of France.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('establishment', 'noun', 'ɪˈstæblɪʃmənt', 'an organization, a large institution or a hotel', 'The visa is for foreign nationals wishing to study at a university, college or similar educational establishment.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('eternal', 'adjective', 'ɪˈtɜːnl', 'without an end; existing or continuing forever', 'the promise of eternal life in heaven', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ethic', 'noun', 'ˈeθɪk', 'moral principles that control or influence a person’s behaviour', 'professional/business/medical ethics', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ethical', 'adjective', 'ˈeθɪkl', 'connected with beliefs and principles about what is right and wrong', 'ethical issues/standards/questions/dilemmas', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ethnic', 'adjective', 'ˈeθnɪk', 'connected with or belonging to a group of people that share a cultural tradition', 'ethnic background/origin', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evacuate', 'verb', 'ɪˈvækjueɪt', 'to move people from a place of danger to a safer place', 'evacuate something, Police evacuated nearby buildings.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evaluate', 'verb', 'ɪˈvæljueɪt', 'to form an opinion of the amount, value or quality of something after thinking about it carefully', 'evaluate something, The trial will evaluate the effectiveness of the different drugs.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evaluation', 'noun', 'ɪˌvæljuˈeɪʃn', 'the act of forming an opinion of the amount, value or quality of something after thinking about it carefully', 'an evaluation of the healthcare system', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('everybody', 'pronoun', 'ˈevribɒdi', 'every person; all people', 'Everybody knows Tom.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('everyday', 'adjective', 'ˈevrideɪ', 'used or happening every day or regularly; ordinary', 'Change is a part of everyday life in business.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('everyone', 'pronoun', 'ˈevriwʌn', 'every person; all people', 'Everyone cheered and clapped.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evident', 'adjective', 'ˈevɪdənt', 'clear; easily seen', 'The orchestra played with evident enjoyment.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evoke', 'verb', 'ɪˈvəʊk', 'to bring a feeling, a memory or an image into your mind', 'The music evoked memories of her youth.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evolution', 'noun', 'ˌiːvəˈluːʃn', 'the slow steady development of plants, animals, etc. during the history of the earth, as they adapt to changes in their environment', 'the evolution of the human species', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evolutionary', 'adjective', 'ˌiːvəˈluːʃənri', 'connected with evolution; connected with slow steady development and change', 'evolutionary theory', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('evolve', 'verb', 'ɪˈvɒlv', 'to develop gradually, especially from a simple to a more complicated form; to develop something in this way', 'evolve (from something) (into something), The idea evolved from a drawing I discovered in the attic.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exceed', 'verb', 'ɪkˈsiːd', 'to be greater than a particular number or amount', 'The price will not exceed £100.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('excellence', 'noun', 'ˈeksələns', 'the quality of being extremely good', 'a reputation for academic excellence', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exceptional', 'adjective', 'ɪkˈsepʃənl', 'unusually good', 'At the age of five he showed exceptional talent as a musician.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('excess', 'adjective, noun', 'ˈekses', 'in addition to an amount that is necessary, usual or legal', 'Excess food is stored as fat.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('excessive', 'adjective', 'ɪkˈsesɪv', 'greater than what seems reasonable or appropriate', 'They complained about the excessive noise coming from the upstairs flat.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exclusion', 'noun', 'ɪkˈskluːʒn', 'the act of preventing somebody/something from entering a place or taking part in something', 'exclusion (of somebody/something) (from something), He was disappointed with his exclusion from the England squad.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exclusive', 'adjective', 'ɪkˈskluːsɪv', 'only to be used by one particular person or group; only given to one particular person or group', 'The hotel has exclusive access to the beach.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exclusively', 'adverb', 'ɪkˈskluːsɪvli', 'for only one particular person, group or use', 'The resort caters almost exclusively for a high-society public.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('execute', 'verb', 'ˈeksɪkjuːt', 'to kill somebody, especially as a legal punishment', 'be executed (for something), He was executed for treason.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('execution', 'noun', 'ˌeksɪˈkjuːʃn', 'the act of killing somebody, especially as a legal punishment', 'He faced execution by hanging for murder.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exert', 'verb', 'ɪɡˈzɜːt', 'to use power or influence to affect somebody/something', 'He exerted all his authority to make them accept the plan.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exile', 'noun', 'ˈeksaɪl', 'the state of being sent to live in another country that is not your own, especially for political reasons or as a punishment', 'a place of exile', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exotic', 'adjective', 'ɪɡˈzɒtɪk', 'from or in another country, especially a tropical one; seeming exciting and unusual because it seems to be connected with foreign countries', 'brightly-coloured exotic flowers/plants/birds', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('expansion', 'noun', 'ɪkˈspænʃn', 'an act of increasing or making something increase in size, amount or importance', 'a period of rapid economic expansion', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('expedition', 'noun', 'ˌekspəˈdɪʃn', 'an organized journey with a particular purpose, especially to find out about a place that is not well known', 'to plan/lead/go on an expedition', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('expenditure', 'noun', 'ɪkˈspendɪtʃə(r)', 'the act of spending or using money; an amount of money spent', 'a reduction in public/government/military expenditure', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('experimental', 'adjective', 'ɪkˌsperɪˈmentl', 'based on new ideas, forms or methods that are used to find out what effect they have', 'The school''s experimental teaching methods include letting the children decide what to study.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('expertise', 'noun', 'ˌekspɜːˈtiːz', 'expert knowledge or skill in a particular subject, activity or job', 'professional/scientific/technical, etc. expertise', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('expire', 'verb', 'ɪkˈspaɪə(r)', 'to be no longer legally acceptable because the period of time for which it could be used has ended', 'When does your driving licence expire?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('explicit', 'adjective', 'ɪkˈsplɪsɪt', 'clear and easy to understand, so that you have no doubt what is meant', 'He gave me very explicit directions on how to get there.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('explicitly', 'adverb', 'ɪkˈsplɪsɪtli', 'clearly or directly, so that the meaning is easy to understand', 'The report states explicitly that the system was to blame.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exploit', 'verb', 'ɪkˈsplɔɪt', 'to treat a person or situation as an opportunity to gain an advantage for yourself', 'He exploited his father''s name to get himself a job.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exploitation', 'noun', 'ˌeksplɔɪˈteɪʃn', 'a situation in which somebody treats somebody else in an unfair way, especially in order to make money from their work', 'the exploitation of children', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exploration', 'noun', 'ˌekspləˈreɪʃn', 'the act of travelling through a place in order to find out about it or look for something in it', 'Budgets for space exploration have been cut back.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('explosive', 'adjective, noun', 'ɪkˈspləʊsɪv', 'easily able or likely to explode', 'an explosive device (= a bomb)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('exposure', 'noun', 'ɪkˈspəʊʒə(r)', 'the state of being in a place or situation where there is no protection from something harmful or unpleasant', 'prolonged exposure to harmful radiation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('extensively', 'adverb', 'ɪkˈstensɪvli', 'in a way that covers a large area', 'She has travelled extensively.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('external', 'adjective', 'ɪkˈstɜːnl', 'connected with or located on the outside of something/somebody', 'the external walls of the building', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('extract', 'noun, verb', 'ˈekstrækt', 'a short passage from a book, piece of music, etc. that gives you an idea of what the whole thing is like', 'The following extract is taken from her new novel.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('extremist', 'noun', 'ɪkˈstriːmɪst', 'a person whose opinions, especially about religion or politics, are extreme, and who may do things that are violent or illegal for what they believe', 'left-wing/right-wing/political/religious extremists', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fabric', 'noun', 'ˈfæbrɪk', 'material made by weaving wool, cotton, silk, etc., used for making clothes, curtains, etc. and for covering furniture', 'They sell a wide variety of printed cotton fabric.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fabulous', 'adjective', 'ˈfæbjələs', 'extremely good', 'They put on a fabulous performance.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('facilitate', 'verb', 'fəˈsɪlɪteɪt', 'to make an action or a process possible or easier', 'The new trade agreement should facilitate more rapid economic growth.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('faction', 'noun', 'ˈfækʃn', 'a small group of people within a larger one, whose members have some different aims and beliefs to those of the larger group', 'There are rival factions within the administration.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('faculty', 'noun', 'ˈfæklti', 'a department or group of related departments in a college or university', 'the Faculty of Law', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fade', 'verb', 'feɪd', 'to become or to make something become paler or less bright', 'The curtains had faded in the sun.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('failed', 'adjective', 'feɪld', 'not successful', 'a failed writer', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fairness', 'noun', 'ˈfeənəs', 'the quality of treating people equally or in a way that is reasonable', 'The fairness of the judicial system is being questioned.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fake', 'adjective', 'feɪk', 'not what somebody claims it is; appearing to be something it is not', 'There were a few stalls selling fake designer clothing.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fantastic', 'adjective', 'fænˈtæstɪk', 'extremely good; excellent', 'He''s done a fantastic job.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fantasy', 'noun', 'ˈfæntəsi', 'a pleasant situation that you imagine but that is unlikely to happen', 'He spoke of his childhood fantasies about becoming a famous football player.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fare', 'noun', 'feə(r)', 'the money that you pay to travel by bus, plane, taxi, etc.', 'bus/taxi fares', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fascinating', 'adjective', 'ˈfæsɪneɪtɪŋ', 'extremely interesting and attractive', 'a fascinating story', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fatal', 'adjective', 'ˈfeɪtl', 'causing or ending in death', 'a fatal accident/blow/illness', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fate', 'noun', 'feɪt', 'the things, especially bad things, that will happen or have happened to somebody/something', 'The fate of the three men is unknown.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('favourable', 'adjective', 'ˈfeɪvərəbl', 'making people have a good opinion of somebody/something', 'She made a favourable impression on his parents.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('feat', 'noun', 'fiːt', 'an action or a piece of work that needs skill, strength or courage', 'The tunnel is a remarkable feat of engineering.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('February', 'noun', 'ˈfebruəri', 'the 2nd month of the year, between January and March', 'She was born in February.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('feedback', 'noun', 'ˈfiːdbæk', 'advice, criticism or information about how good or useful something or somebody’s work is', 'customer/user feedback', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('feminist', 'adjective, noun', 'ˈfemənɪst', 'having or based on the belief that women should have the same rights and opportunities as men', 'feminist demands/ideas/theories', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fibre', 'noun', 'ˈfaɪbə(r)', 'the part of food that helps to keep a person healthy by keeping the bowels working and moving other food quickly through the body', 'dietary fibre', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fiction', 'noun', 'ˈfɪkʃn', 'a type of literature that describes imaginary people and events, not real ones', 'a work of popular fiction', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fierce', 'adjective', 'fɪəs', 'angry and aggressive in a way that is frightening', 'a fierce dog', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fifteen', 'number', 'ˌfɪfˈtiːn', '15', 'He''s in the first fifteen.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fifth', 'ordinal number', 'fɪfθ', '5th', 'Today is the fifth (of May).', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fifty', 'number', 'ˈfɪfti', '50', 'She was born in the fifties.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('film-maker', 'noun', 'ˈfɪlm meɪkə(r)', '', NULL, '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('filter', 'noun, verb', 'ˈfɪltə(r)', 'a device containing paper, sand, chemicals, etc. that a liquid or gas is passed through in order to remove any materials that are not wanted', 'an air/oil filter', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('finding', 'noun', 'ˈfaɪndɪŋ', 'information that is discovered as the result of research into something', 'Our research findings indicate that pregnant women benefit from this treatment.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('firearm', 'noun', 'ˈfaɪərɑːm', 'a gun that can be carried', 'The police were issued with firearms.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('firefighter', 'noun', 'ˈfaɪəfaɪtə(r)', 'a person whose job is to put out fires', 'Firefighters were called to a house in Summertown.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('firework', 'noun', 'ˈfaɪəwɜːk', 'a small device containing powder that burns or explodes and produces bright coloured lights and loud noises, used especially at celebrations', '(British English), to let off a few fireworks', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('firstly', 'adverb', 'ˈfɜːstli', 'used to introduce the first of a list of points you want to make in a speech or piece of writing', 'There are two reasons for this decision: firstly…', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fitness', 'noun', 'ˈfɪtnəs', 'the state of being physically healthy and strong', 'a magazine on health and fitness', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('five', 'number', 'faɪv', '5', 'There are only five cookies left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fixture', 'noun', 'ˈfɪkstʃə(r)', 'a sports event that has been arranged to take place on a particular date and at a particular place', 'There are plans to make the race an annual fixture.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('flaw', 'noun', 'flɔː', 'a mistake in something that means that it is not correct or does not work correctly', 'The argument is full of fundamental flaws.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('flawed', 'adjective', 'flɔːd', 'having a flaw; not perfect or correct', 'seriously/fundamentally/fatally flawed', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('flee', 'verb', 'fliː', 'to leave a person or place very quickly, especially because you are afraid of possible danger', 'She burst into tears and fled.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fleet', 'noun', 'fliːt', 'a group of military ships commanded by the same person', 'a fleet of destroyers', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('flexibility', 'noun', 'ˌfleksəˈbɪləti', 'the ability to change to suit new conditions or situations', 'The new system offers a much greater degree of flexibility in the way work is organized.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('flexible', 'adjective', 'ˈfleksəbl', 'able to change to suit new conditions or situations', 'a more flexible approach', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('flourish', 'verb', 'ˈflʌrɪʃ', 'to develop quickly and become successful or common', 'Few businesses are flourishing in the present economic climate.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fluid', 'noun', 'ˈfluːɪd', 'a liquid; a substance that can flow', 'body fluids (= for example, blood)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('folk', 'adjective, noun', 'fəʊk', 'traditional and typical of the ordinary people of a country or community', 'We visited an exhibition of folk art.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fond', 'adjective', 'fɒnd', 'having warm or loving feelings for somebody, especially somebody you have known for a long time', 'Over the years, I have grown quite fond of her.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fool', 'noun', 'fuːl', 'a person who you think behaves or speaks in a way that lacks intelligence or good judgement', 'Don''t be such a fool!', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('footage', 'noun', 'ˈfʊtɪdʒ', 'part of a film showing a particular event', 'old film footage of the moon landing', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('forbid', 'verb', 'fəˈbɪd', 'to order somebody not to do something; to order that something must not be done', 'forbid somebody (from doing something), He forbade them from mentioning the subject again.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('foreigner', 'noun', 'ˈfɒrənə(r)', 'a person who comes from a different country', 'The fact that I was a foreigner was a big disadvantage.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('forge', 'verb', 'fɔːdʒ', 'to put a lot of effort into making something successful or strong so that it will last', 'a move to forge new links between management and workers', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('format', 'noun', 'ˈfɔːmæt', 'the general arrangement, plan, design, etc. of something', 'The format of the new quiz show has proved popular.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('formation', 'noun', 'fɔːˈmeɪʃn', 'the action of forming something; the process of being formed', 'the formation of a new government', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('formulate', 'verb', 'ˈfɔːmjuleɪt', 'to create or prepare something carefully, giving particular attention to the details', 'formulate something, to formulate a policy/theory/plan/proposal', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('forth', 'adverb', 'fɔːθ', 'away from a place; out', 'They set forth at dawn.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('forthcoming', 'adjective', 'ˌfɔːθˈkʌmɪŋ', 'going to happen, be published, etc. very soon', 'the forthcoming elections', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fortunate', 'adjective', 'ˈfɔːtʃənət', 'having or bringing an advantage, an opportunity, a piece of good luck, etc.', 'Remember those less fortunate than yourselves.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fortunately', 'adverb', 'ˈfɔːtʃənətli', 'by good luck', 'I was late, but fortunately the meeting hadn''t started.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('forty', 'number', 'ˈfɔːti', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('forum', 'noun', 'ˈfɔːrəm', 'an event or medium where people can exchange opinions and ideas on a particular issue; a meeting organized for this purpose', 'forum (on something), to hold an international forum on drug abuse', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fossil', 'noun', 'ˈfɒsl', 'the parts of a dead animal or a plant that have become hard and turned into rock', 'fossils over two million years old', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('foster', 'verb', 'ˈfɒstə(r)', 'to encourage something to develop', 'The club''s aim is to foster better relations within the community.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('founder', 'noun', 'ˈfaʊndə(r)', 'a person who starts an organization, institution, etc. or causes something to be built', 'the founder and president of the company', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('four', 'number', 'fɔː(r)', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fourteen', 'number', 'ˌfɔːˈtiːn', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fourth', 'ordinal number', 'fɔːθ', '4th', 'Today is the fourth (of May).', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fraction', 'noun', 'ˈfrækʃn', 'a small part or amount of something', 'Only a small fraction of a bank''s total deposits will be withdrawn at any one time.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fragile', 'adjective', 'ˈfrædʒaɪl', 'easily broken or damaged', 'fragile china/glass/bones', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fragment', 'noun', 'ˈfræɡmənt', 'a small part of something that has broken off or comes from something larger', 'fragment (of something), Police found fragments of glass near the scene.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('framework', 'noun', 'ˈfreɪmwɜːk', 'the parts of a building or an object that support its weight and give it shape', 'built on a wooden framework', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('franchise', 'noun', 'ˈfræntʃaɪz', 'formal permission given by a company to somebody who wants to sell its goods or services in a particular area; formal permission given by a government to somebody who wants to operate a public service as a business', 'a franchise agreement/company', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('frankly', 'adverb', 'ˈfræŋkli', 'in an honest and direct way that people might not like', 'He spoke frankly about the ordeal.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fraud', 'noun', 'frɔːd', 'the crime of cheating somebody in order to get money or goods illegally', 'She was charged with credit card fraud.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('frequency', 'noun', 'ˈfriːkwənsi', 'the rate at which something happens or is repeated', 'Fatal road accidents have decreased in frequency over recent years.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('Friday', 'noun', 'ˈfraɪdeɪ', 'the day of the week after Thursday and before Saturday', 'It''s Friday today, isn''t it?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('frog', 'noun', 'frɒɡ', 'a small animal with smooth skin, that lives both on land and in water (= is an amphibian). Frogs have very long back legs for jumping, and no tail.', 'the croaking of frogs', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('frustrated', 'adjective', 'frʌˈstreɪtɪd', 'feeling annoyed and impatient because you cannot do or achieve what you want', 'It''s very easy to get frustrated in this job.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('frustrating', 'adjective', 'frʌˈstreɪtɪŋ', 'causing you to feel annoyed and impatient because you cannot do or achieve what you want', 'It''s frustrating to have to wait so long.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('frustration', 'noun', 'frʌˈstreɪʃn', 'the feeling of being frustrated', 'in frustration, Dave thumped the table in frustration.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fulfil', 'verb', 'fʊlˈfɪl', 'to do or achieve what was hoped for or expected', 'to fulfil your dream/ambition/potential', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('full-time', 'adjective, adverb', 'ˌfʊl ˈtaɪm', 'for all the hours of a week during which people normally work or study, rather than just for a part of it', 'students in full-time education', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('functional', 'adjective', 'ˈfʌŋkʃənl', 'practical and useful; with little or no decoration', 'Bathrooms don''t have to be purely functional.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fundamentally', 'adverb', 'ˌfʌndəˈmentəli', 'in every way that is important; completely', 'The two approaches are fundamentally different.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('funding', 'noun', 'ˈfʌndɪŋ', 'money for a particular purpose; the act of providing money for such a purpose', 'federal/state funding', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('fundraising', 'noun', 'ˈfʌndreɪzɪŋ', 'the activity of collecting money for a charity or organization, often by organizing social events or entertainments', 'The hospice is planning a major fundraising event for June.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('furious', 'adjective', 'ˈfjʊəriəs', 'very angry', 'Their incompetence made me furious.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('furthermore', 'adverb', 'ˌfɜːðəˈmɔː(r)', 'in addition to what has just been stated. Furthermore is used especially to add a point to an argument.', 'He said he had not discussed the matter with her. Furthermore, he had not even contacted her.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gallery', 'noun', 'ˈɡæləri', 'a room or building for showing works of art, especially to the public', 'a picture gallery', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gaming', 'noun', 'ˈɡeɪmɪŋ', 'playing computer games', 'online/mobile/console gaming', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gang', 'noun', 'ɡæŋ', 'an organized group of criminals', 'criminal gangs', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gathering', 'noun', 'ˈɡæðərɪŋ', 'a meeting of people for a particular purpose', 'a social/family gathering', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gay', 'adjective', 'ɡeɪ', 'sexually attracted to people of the same sex', 'gay men', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gaze', 'noun, verb', 'ɡeɪz', 'a long, steady look at somebody/something', 'He met her gaze (= looked at her while she looked at him).', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gender', 'noun', 'ˈdʒendə(r)', 'the fact of being male or female, especially when considered with reference to social and cultural differences, rather than differences in biology; members of a particular gender as a group', 'issues of class, race and gender', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gene', 'noun', 'dʒiːn', 'a unit inside a cell that controls a particular quality in a living thing that has been passed on from its parents', 'a dominant/recessive gene', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('generic', 'adjective', 'dʒəˈnerɪk', 'shared by, including or typical of a whole group of things; not specific', '‘Vine fruit’ is the generic term for currants and raisins.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('genetic', 'adjective', 'dʒəˈnetɪk', 'connected with genes (= the units in the cells of a living thing that control its physical characteristics) or genetics (= the study of genes)', 'genetic and environmental factors', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('genius', 'noun', 'ˈdʒiːniəs', 'unusually great intelligence, skill or artistic ability', 'the genius of Shakespeare', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('genocide', 'noun', 'ˈdʒenəsaɪd', 'the murder of a large number of people from a particular nation or ethnic group, with the aim of destroying that nation or group', 'Refugees gave accounts of the mass genocide.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('genre', 'noun', 'ˈʒɒ̃rə', 'a particular type or style of literature, art, film or music that you can recognize because of its special features', 'literary/musical genres', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gesture', 'noun', 'ˈdʒestʃə(r)', 'a movement that you make with your hands, your head or your face to show a particular meaning', 'He made a rude gesture at the driver of the other car.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ghost', 'noun', 'ɡəʊst', 'the spirit of a dead person that a living person believes they can see or hear', 'Do you believe in ghosts (= believe that they exist)?', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gig', 'noun', 'ɡɪɡ', 'a performance by musicians playing popular music or jazz in front of an audience; a similar performance by a comedian', 'They''re doing a gig in Boston tonight.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('glance', 'noun, verb', 'ɡlɑːns', 'a quick look', 'to take/have a glance at the newspaper headlines', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('glimpse', 'noun', 'ɡlɪmps', 'a sight of somebody/something for a very short time, when you do not see the person or thing completely', 'glimpse (of somebody/something), He caught a glimpse of her in the crowd.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('globalization', 'noun', 'ˌɡləʊbəlaɪˈzeɪʃn', '', NULL, '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('globe', 'noun', 'ɡləʊb', 'the world (used especially to emphasize its size)', 'tourists from every corner of the globe', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('glorious', 'adjective', 'ˈɡlɔːriəs', 'deserving or bringing great success and making somebody/something famous', 'We congratulate you on this glorious victory.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('glory', 'noun', 'ˈɡlɔːri', 'great success that brings somebody praise and honour and makes them famous', 'Olympic glory in the 100 metres', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('golden', 'adjective', 'ˈɡəʊldən', 'made of gold', 'a golden crown', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('golf', 'noun', 'ɡɒlf', 'a game played over a large area of ground using sticks with a special shape to hit a small hard ball (a golf ball) into a series of 9 or 18 holes, using as few shots as possible', 'I play golf every weekend.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('goodness', 'noun', 'ˈɡʊdnəs', 'the quality of being good', 'the essential goodness of human nature', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gorgeous', 'adjective', 'ˈɡɔːdʒəs', 'very beautiful and attractive; giving great pleasure ', 'a gorgeous girl/man', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('governance', 'noun', 'ˈɡʌvənəns', 'the activity of governing a country or controlling a company or an organization; the way in which a country is governed or a company or institution is controlled', 'He emphasized the company''s commitment to high standards of corporate governance.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('grace', 'noun', 'ɡreɪs', 'an attractive quality of movement that is smooth and done with control; a simple and beautiful quality', 'She moves with the natural grace of a ballerina.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('graduate', 'noun, verb', 'ˈɡrædʒuət', 'a person who has a university degree', 'job prospects for graduates', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('graphic', 'adjective', 'ˈɡræfɪk', 'connected with drawings and design, especially in the production of books, magazines, websites, etc.', 'graphic design', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('graphics', 'noun', 'ˈɡræfɪks', 'designs, drawings or pictures that are used especially in the production of books, magazines, websites, etc.', 'Text and graphics are prepared separately and then combined.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('grasp', 'noun, verb', 'ɡrɑːsp', 'a strong hold of somebody/something or control over somebody/something', 'I grabbed him, but he slipped from my grasp.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gravity', 'noun', 'ˈɡrævəti', 'the force that attracts objects in space towards each other, and that on the earth pulls them towards the centre of the planet, so that things fall to the ground when they are dropped', 'Newton’s law of gravity', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('greenhouse', 'noun', 'ˈɡriːnhaʊs', '', NULL, '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('greet', 'verb', 'ɡriːt', 'to say hello to somebody or to welcome them', 'greet somebody, He greeted all the guests warmly as they arrived.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('grid', 'noun', 'ɡrɪd', 'a pattern of straight lines, usually crossing each other to form squares', 'New York’s grid of streets', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('grief', 'noun', 'ɡriːf', 'a very sad feeling, especially when somebody dies', 'She was overcome with grief when her husband died.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('grin', 'noun, verb', 'ɡrɪn', 'a wide smile', 'She gave a broad grin.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('grind', 'verb', 'ɡraɪnd', 'to break or press something into very small pieces between two hard surfaces or using a special machine', 'to grind coffee/corn', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('grip', 'noun, verb', 'ɡrɪp', 'an act of holding somebody/something tightly; a particular way of doing this', 'Keep a tight grip on the rope.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gross', 'adjective', 'ɡrəʊs', 'being the total amount of something before anything is taken away', 'gross weight (= including the container or wrapping)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('guerrilla', 'noun', 'ɡəˈrɪlə', 'a member of a small group of soldiers who are not part of an official army and who fight against official soldiers, usually to try to change the government', 'urban guerrillas (= those who fight in towns)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('guidance', 'noun', 'ˈɡaɪdns', 'help or advice that is given to somebody, especially by somebody older or with more experience', 'guidance for teachers on how to use video in the classroom', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('guideline', 'noun', 'ˈɡaɪdlaɪn', 'a set of rules or instructions that are given by an official organization telling you how to do something, especially something difficult', 'The government has drawn up guidelines for schools during the pandemic.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('guilt', 'noun', 'ɡɪlt', 'the unhappy feelings caused by knowing or thinking that you have done something wrong', 'She had feelings of guilt about leaving her children and going to work.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('guitar', 'noun', 'ɡɪˈtɑː(r)', 'a musical instrument that usually has six strings and that you play with your fingers or with a plectrum', 'an acoustic/electric guitar', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gut', 'noun', 'ɡʌt', 'the tube in the body through which food passes when it leaves the stomach', 'It can take up to 72 hours for food to pass through the gut.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('gym', 'noun', 'dʒɪm', 'a room or hall with equipment for doing physical exercise, for example in a school', 'The school has recently built a new gym.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('habitat', 'noun', 'ˈhæbɪtæt', 'the place where a particular type of animal or plant is normally found', 'The panda''s natural habitat is the bamboo forest.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hail', 'verb', 'heɪl', 'to describe somebody/something as being very good or special, especially in newspapers, etc.', 'be hailed (as) something, The conference was hailed as a great success.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('halfway', 'adverb', 'ˌhɑːfˈweɪ', 'at an equal distance between two points; in the middle of a period of time', 'It''s about halfway between London and Bristol.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('halt', 'noun, verb', 'hɔːlt', 'an act of stopping the movement or progress of somebody/something', 'Work came to a halt when the machine broke down.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('handful', 'noun', 'ˈhændfʊl', 'the amount of something that can be held in one hand', 'a handful of rice', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('handling', 'noun', 'ˈhændlɪŋ', 'the way that somebody deals with or treats a situation, a person, an animal, etc.', 'I was impressed by his handling of the affair.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('handy', 'adjective', 'ˈhændi', 'easy to use or to do', 'a handy little tool', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('harassment', 'noun', 'ˈhærəsmənt', 'the act of annoying or worrying somebody by putting pressure on them or saying or doing unpleasant things to them', 'sexual/racial harassment', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('harbour', 'noun', 'ˈhɑːbə(r)', 'an area of water on the coast, protected from the open sea by strong walls, where ships can shelter', 'Several boats lay at anchor in the harbour.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hardware', 'noun', 'ˈhɑːdweə(r)', 'the machines and electronic parts in a computer or other electronic system', 'We supply computer hardware to businesses.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('harmony', 'noun', 'ˈhɑːməni', 'a state of peaceful existence and agreement', 'social/racial harmony', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('harsh', 'adjective', 'hɑːʃ', 'cruel, severe and unkind', 'The punishment was harsh and unfair.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('harvest', 'noun, verb', 'ˈhɑːvɪst', 'the time of year when the crops are gathered in on a farm, etc.; the act of cutting and gathering crops', 'harvest time', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('haunt', 'verb', 'hɔːnt', 'if the ghost of a dead person haunts a place, people say that they have seen it there', 'A headless rider haunts the country lanes.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hazard', 'noun', 'ˈhæzəd', 'something that can be dangerous or cause damage', 'a fire/safety hazard', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('headline', 'noun', 'ˈhedlaɪn', 'the title of a news article printed in large letters, especially at the top of the front page on a newspaper or the home page on a news website', 'a newspaper headline', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('headquarters', 'noun', 'ˌhedˈkwɔːtəz', 'a place from which an organization or a military operation is controlled; the people who work there', 'The firm’s headquarters is/are in London.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('healthcare', 'noun', 'ˈhelθ keə(r)', 'the service of providing medical care', 'the costs of healthcare for the elderly', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('heighten', 'verb', 'ˈhaɪtn', 'if a feeling or an effect heightens, or something heightens it, it becomes stronger or increases', 'Tension has heightened after the recent bomb attack.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('helicopter', 'noun', 'ˈhelɪkɒptə(r)', 'an aircraft without wings that has large blades (= long flat parts) on top that go round. It can fly straight up from the ground and can also stay in one position in the air.', 'a police/rescue helicopter', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('helmet', 'noun', 'ˈhelmɪt', 'a type of hard hat that protects the head, worn, for example, by a police officer, a soldier or a person riding a bike or motorbike or playing some sports', 'Police in riot helmets lined the streets.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('herb', 'noun', 'hɜːb', 'a plant whose leaves, flowers or seeds are used to add taste to food, in medicines or for their pleasant smell. parsley, mint and oregano are all herbs.', 'a herb garden', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('heritage', 'noun', 'ˈherɪtɪdʒ', 'the history, traditions, buildings and objects that a country or society has had for many years and that are considered an important part of its character', 'Spain’s rich cultural heritage', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hey', 'exclamation', 'heɪ', 'used to attract somebody’s attention or to express interest, surprise or anger', 'Hey, can I just ask you something?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hidden', 'adjective', 'ˈhɪdn', 'something that is hidden is kept or located in a place where it cannot be seen', 'Hidden dangers lurk in the ocean depths.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hierarchy', 'noun', 'ˈhaɪərɑːki', 'a system, especially in a society or an organization, in which people are organized into different levels of importance from highest to lowest', 'the social/political hierarchy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('high-profile', 'adjective', 'ˌhaɪ ˈprəʊfaɪl', 'receiving or involving a lot of attention and discussion in the media', 'a high-profile campaign', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hilarious', 'adjective', 'hɪˈleəriəs', 'extremely funny', 'a hilarious joke/story', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hint', 'noun, verb', 'hɪnt', 'something that you say or do in an indirect way in order to show somebody what you are thinking', 'He gave a broad hint (= one that was obvious) that he was thinking of retiring.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('historian', 'noun', 'hɪˈstɔːriən', 'a person who studies or writes about history; an expert in history', 'No serious historian today accepts this theory.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('historic', 'adjective', 'hɪˈstɒrɪk', 'important in history; likely to be thought of as important at some time in the future', 'the restoration of historic buildings', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hockey', 'noun', 'ˈhɒki', 'a game played on a field by two teams of 11 players, with curved sticks and a small hard ball. Teams try to hit the ball into the other team’s goal.', 'to play hockey', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('homeland', 'noun', 'ˈhəʊmlænd', 'the country where a person was born', 'Many refugees have been forced to flee their homeland.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('homeless', 'adjective', 'ˈhəʊmləs', 'having no home, and therefore typically living on the streets', 'The scheme has been set up to help homeless people.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('honesty', 'noun', 'ˈɒnəsti', 'the quality of being honest', 'She answered all my questions with her usual honesty.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hopeful', 'adjective', 'ˈhəʊpfl', 'believing that something you want will happen', 'hopeful (that…), I feel hopeful that we''ll find a suitable house very soon.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hopefully', 'adverb', 'ˈhəʊpfəli', 'used to express what you hope will happen', 'Hopefully, we''ll arrive before dark.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('horizon', 'noun', 'həˈraɪzn', 'the furthest that you can see, where the sky seems to meet the land or the sea', 'The sun sank below the horizon.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('horrible', 'adjective', 'ˈhɒrəbl', 'very bad or unpleasant; used to describe something that you do not like', 'What horrible weather!', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hostage', 'noun', 'ˈhɒstɪdʒ', 'a person who is captured and held prisoner by a person or group, and who may be injured or killed if people do not do what the person or group is asking', 'Three children were taken hostage during the bank robbery.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hostile', 'adjective', 'ˈhɒstaɪl', 'aggressive or unfriendly and ready to argue or fight', 'The speaker got a hostile reception from the audience.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hostility', 'noun', 'hɒˈstɪləti', 'aggressive or unfriendly feelings or behaviour ', 'There was a barely veiled hostility in her tone.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('humanitarian', 'adjective', 'hjuːˌmænɪˈteəriən', 'connected with helping people who are suffering and improving the conditions that they are living in', 'to provide humanitarian aid to the war zone', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('humanity', 'noun', 'hjuːˈmænəti', 'people in general', 'He was found guilty of crimes against humanity.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('humble', 'adjective', 'ˈhʌmbl', 'showing you do not think that you are as important as other people', 'Be humble enough to learn from your mistakes.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hundred', 'number', 'ˈhʌndrəd', '100', 'One hundred (of the children) have already been placed with foster families.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hunger', 'noun', 'ˈhʌŋɡə(r)', 'the state of not having enough food to eat, especially when this causes illness or death', 'Around fifty people die of hunger every day in the camp.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hurricane', 'noun', 'ˈhʌrɪkən', 'a violent storm with very strong winds, especially in the western Atlantic Ocean', 'A powerful hurricane hit the Florida coast.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hydrogen', 'noun', 'ˈhaɪdrədʒən', '', NULL, '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('hypothesis', 'noun', 'haɪˈpɒθəsɪs', 'an idea or explanation of something that is based on a few known facts but that has not yet been proved to be true or correct', 'to formulate/confirm a hypothesis', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('I', 'pronoun', 'aɪ', 'used as the subject of a verb when the speaker or writer is referring to himself/herself', 'I think I''d better go now.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('icon', 'noun', 'ˈaɪkɒn', 'a small symbol on a computer or smartphone screen that represents a program or a file', 'Click on the printer icon with the mouse.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ID', 'noun', 'ˌaɪ ˈdiː', 'an official way of showing who you are, for example a document with your name, date of birth and often a photograph on it (the abbreviation for ‘identity’ or ‘identification’) ', 'You must carry ID at all times.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('identical', 'adjective', 'aɪˈdentɪkl', 'similar in every detail', 'a row of identical houses', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('identification', 'noun', 'aɪˌdentɪfɪˈkeɪʃn', 'the process of showing, proving or recognizing who or what somebody/something is', 'The identification of the crash victims was a long and difficult task.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ideological', 'adjective', 'ˌaɪdiəˈlɒdʒɪkl', 'based on or connected with an ideology', 'ideological differences', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ideology', 'noun', 'ˌaɪdiˈɒlədʒi', 'a set of ideas that an economic or political system is based on', 'Marxist/capitalist ideology', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('idiot', 'noun', 'ˈɪdiət', 'a rude way to refer to somebody who you think is very stupid', 'When I lost my passport, I felt such an idiot.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ignorance', 'noun', 'ˈɪɡnərəns', 'a lack of knowledge or information about something', 'They fought a long battle against prejudice and ignorance.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('illusion', 'noun', 'ɪˈluːʒn', 'a false idea or belief, especially about somebody or about a situation', 'under the illusion that…, She''s under the illusion that (= believes wrongly that) she''ll get the job.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('illustration', 'noun', 'ˌɪləˈstreɪʃn', 'a drawing or picture in a book, magazine, for decoration or to explain something', '50 full-colour illustrations', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('imagery', 'noun', 'ˈɪmɪdʒəri', 'language that produces pictures in the minds of people reading or listening', 'poetic imagery', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('immense', 'adjective', 'ɪˈmens', 'extremely large or great', 'There is still an immense amount of work to be done.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('immigrant', 'noun', 'ˈɪmɪɡrənt', 'a person who has come to live permanently in a different country from the one they were born in', 'immigrant from…, immigrants from other European countries', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('immigration', 'noun', 'ˌɪmɪˈɡreɪʃn', 'the process of coming to live permanently in a different country from the one you were born in; the number of people who do this', 'legal/illegal immigration', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('imminent', 'adjective', 'ˈɪmɪnənt', 'likely to happen very soon', 'the imminent threat of invasion', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('immune', 'adjective', 'ɪˈmjuːn', 'that cannot catch or be affected by a particular disease or illness', 'Adults are often immune to German measles.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('implement', 'verb', 'ˈɪmplɪment', 'to make something that has been officially decided start to happen or be used', 'to implement changes/decisions/policies/reforms', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('implementation', 'noun', 'ˌɪmplɪmenˈteɪʃn', 'the act of making something that has been officially decided start to happen or be used', 'the implementation of the new system', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('imprison', 'verb', 'ɪmˈprɪzn', 'to put somebody in a prison or another place from which they cannot escape', 'be imprisoned (for something), They were imprisoned for possession of drugs.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('imprisonment', 'noun', 'ɪmˈprɪznmənt', 'the act of putting somebody in a prison or another place from which they cannot escape; the state of being there', 'to be sentenced to life imprisonment for murder', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inadequate', 'adjective', 'ɪnˈædɪkwət', 'not enough; not good enough', 'inadequate supplies', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inappropriate', 'adjective', 'ˌɪnəˈprəʊpriət', 'not suitable or appropriate in a particular situation', 'inappropriate behaviour/language', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('incentive', 'noun', 'ɪnˈsentɪv', 'something that encourages you to do something', 'There is no incentive for people to save fuel.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('incidence', 'noun', 'ˈɪnsɪdəns', 'the extent to which something happens or has an effect', 'an area with a high incidence of crime', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inclined', 'adjective', 'ɪnˈklaɪnd', 'wanting to do something', 'She was inclined to trust him.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('included', 'adjective', 'ɪnˈkluːdɪd', 'contained as part of something', 'all of Europe (Britain included)', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inclusion', 'noun', 'ɪnˈkluːʒn', 'the fact of including somebody/something; the fact of being included', 'His inclusion in the team is in doubt.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('incorporate', 'verb', 'ɪnˈkɔːpəreɪt', 'to include something so that it forms a part of something', 'incorporate something, The new car design incorporates all the latest safety features.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('incorrect', 'adjective', 'ˌɪnkəˈrekt', 'not accurate or true', 'incorrect information/spelling', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('incredible', 'adjective', 'ɪnˈkredəbl', 'impossible or very difficult to believe', 'an incredible story', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('incredibly', 'adverb', 'ɪnˈkredəbli', 'extremely', 'It was all incredibly difficult.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('incur', 'verb', 'ɪnˈkɜː(r)', 'if you incur something unpleasant, you are in a situation in which you have to deal with it', 'She had incurred the wrath of her father by marrying without his consent.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('indicator', 'noun', 'ˈɪndɪkeɪtə(r)', 'a sign that shows you what something is like or how a situation is changing', 'The economic indicators are better than expected.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('indictment', 'noun', 'ɪnˈdaɪtmənt', 'a sign that a system, society, etc. is very bad or very wrong', 'The poverty in our cities is a damning indictment of modern society.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('indigenous', 'adjective', 'ɪnˈdɪdʒənəs', 'coming from a particular place and having lived there for a long time before other people came there; relating to, belonging to or developed by these people', 'the indigenous peoples/languages of an area', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('induce', 'verb', 'ɪnˈdjuːs', 'to persuade or influence somebody to do something', 'Nothing would induce me to take the job.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('indulge', 'verb', 'ɪnˈdʌldʒ', 'to allow yourself to have or do something that you like, especially something that is considered bad for you', 'indulge in something, They went into town to indulge in some serious shopping.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inequality', 'noun', 'ˌɪnɪˈkwɒləti', 'the unfair difference between groups of people in society, when some have more wealth, status or opportunities than others', 'We need to tackle inequality of opportunity wherever we find it.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('infamous', 'adjective', 'ˈɪnfəməs', 'well known for being bad or evil', 'a general who was infamous for his brutality', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('infant', 'noun', 'ˈɪnfənt', 'a baby or very young child', 'a nursery for infants under two', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('infer', 'verb', 'ɪnˈfɜː(r)', 'to reach an opinion or decide that something is true on the basis of information that is available', 'infer something (from something), Much of the meaning must be inferred from the context.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inflation', 'noun', 'ɪnˈfleɪʃn', 'a general rise in the prices of services and goods in a particular country, resulting in a fall in the value of money; the rate at which this happens', 'the fight against rising inflation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inflict', 'verb', 'ɪnˈflɪkt', 'to make somebody/something suffer something unpleasant', 'inflict something on/upon somebody/something, They inflicted a humiliating defeat on the home team.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('influential', 'adjective', 'ˌɪnfluˈenʃl', 'having a lot of influence on somebody/something', 'a highly influential book', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('info', 'noun', 'ˈɪnfəʊ', 'information', 'For more info, click here.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('infrastructure', 'noun', 'ˈɪnfrəstrʌktʃə(r)', '', NULL, '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inhabitant', 'noun', 'ɪnˈhæbɪtənt', 'a person or an animal that lives in a particular place', 'the oldest inhabitant of the village', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inherent', 'adjective', 'ɪnˈherənt', 'that is a basic or permanent part of somebody/something and that cannot be removed', 'the difficulties inherent in a study of this type', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inherit', 'verb', 'ɪnˈherɪt', 'to receive money, property, etc. from somebody when they die', 'inherit something from somebody, She inherited a fortune from her father.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inhibit', 'verb', 'ɪnˈhɪbɪt', 'to prevent something from happening or make it happen more slowly or less frequently than normal', 'A lack of oxygen may inhibit brain development in the unborn child.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('initiate', 'verb', 'ɪˈnɪʃieɪt', 'to make something begin', 'to initiate legal proceedings against somebody', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inject', 'verb', 'ɪnˈdʒekt', 'to put a drug or other substance into a person’s or an animal’s body using a syringe', 'inject something (into yourself/somebody/something), Adrenaline was injected into the muscle.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('injection', 'noun', 'ɪnˈdʒekʃn', 'an act of injecting somebody with a drug or other substance', 'to give somebody an injection', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('injustice', 'noun', 'ɪnˈdʒʌstɪs', 'the fact of a situation being unfair and of people not being treated equally; an unfair act or an example of unfair treatment', 'We are committed to fighting against poverty and injustice.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inmate', 'noun', 'ˈɪnmeɪt', 'one of the people living in an institution such as a prison or a psychiatric hospital', 'The jail has 500 inmates.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('innovation', 'noun', 'ˌɪnəˈveɪʃn', 'the introduction of new things, ideas or ways of doing something', 'an age of technological innovation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('innovative', 'adjective', 'ˈɪnəveɪtɪv', 'introducing or using new ideas, ways of doing something, etc.', 'There will be a prize for the most innovative design.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('input', 'noun', 'ˈɪnpʊt', 'time, knowledge, ideas, etc. that you put into work, a project, etc. in order to make it succeed; the act of putting something in', 'I''d appreciate your input on this.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inquiry', 'noun', 'ɪnˈkwaɪəri', 'an official process to find out the cause of something or to find out information about something', 'a murder inquiry ', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('insertion', 'noun', 'ɪnˈsɜːʃn', 'the act of putting something inside something else; a thing that is put inside something else', 'An examination is carried out before the insertion of the tube.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('insider', 'noun', 'ɪnˈsaɪdə(r)', 'a person who knows a lot about a group or an organization, because they are part of it', 'The situation was described by one insider as ‘absolute chaos’.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('insight', 'noun', 'ˈɪnsaɪt', 'an understanding of what something is like', 'There are many valuable insights in her book.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inspect', 'verb', 'ɪnˈspekt', 'to look closely at something/somebody, especially to check that everything is as it should be', 'inspect something/somebody, The teacher walked around inspecting their work.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inspection', 'noun', 'ɪnˈspekʃn', 'an official visit to a school, factory, etc. in order to check that rules are being obeyed and that standards are acceptable', 'Regular inspections are carried out at the prison.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inspector', 'noun', 'ɪnˈspektə(r)', 'an officer of middle rank in the police force', 'Inspector Maggie Forbes', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inspiration', 'noun', 'ˌɪnspəˈreɪʃn', 'the process that takes place when somebody sees or hears something that causes them to have exciting new ideas or makes them want to create something, especially in art, music or literature', 'Dreams can be a rich source of inspiration for an artist.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('inspire', 'verb', 'ɪnˈspaɪə(r)', 'to give somebody the desire, confidence or enthusiasm to do something well', 'inspire somebody, The actors'' enthusiasm inspired the kids.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('installation', 'noun', 'ˌɪnstəˈleɪʃn', 'the act of fixing equipment or furniture in position so that it can be used', 'installation costs', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('instant', 'adjective', 'ˈɪnstənt', 'happening immediately', 'This account gives you instant access to your money.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('instantly', 'adverb', 'ˈɪnstəntli', 'immediately', 'Her voice is instantly recognizable.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('instinct', 'noun', 'ˈɪnstɪŋkt', 'a natural quality that makes people and animals tend to behave in a particular way using the knowledge and abilities that they were born with rather than thought or training', 'She did not seem to have any of the usual maternal instincts.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('institutional', 'adjective', 'ˌɪnstɪˈtjuːʃənl', 'connected with a large important organization, for example a university or bank', 'institutional investors', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('instruct', 'verb', 'ɪnˈstrʌkt', 'to tell somebody to do something, especially in a formal or official way', 'instruct somebody to do something, The letter instructed him to report to headquarters immediately.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('instructor', 'noun', 'ɪnˈstrʌktə(r)', 'a person whose job is to teach somebody a practical skill or sport', 'a fitness/driving/ski instructor', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('instrumental', 'adjective', 'ˌɪnstrəˈmentl', 'important in making something happen', 'The Conservation Trust performs an instrumental role in the protection of rural environments.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('insufficient', 'adjective', 'ˌɪnsəˈfɪʃnt', 'not large, strong or important enough for a particular purpose', 'insufficient time', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intact', 'adjective', 'ɪnˈtækt', 'complete and not damaged', 'Most of the house remains intact even after two hundred years.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intake', 'noun', 'ˈɪnteɪk', 'the amount of food, drink, etc. that you take into your body', 'high fluid intake', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('integral', 'adjective', 'ˈɪntɪɡrəl', 'being an essential part of something', 'Music is an integral part of the school''s curriculum.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('integrate', 'verb', 'ˈɪntɪɡreɪt', 'to combine two or more things so that they work together; to combine with something else in this way', 'integrate into/with something, These programs will integrate with your existing software.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('integrated', 'adjective', 'ˈɪntɪɡreɪtɪd', 'in which many different parts are closely connected and work successfully together', 'an integrated programme of patient care', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('integration', 'noun', 'ˌɪntɪˈɡreɪʃn', 'the act or process of combining two or more things so that they work together', 'The aim is to promote closer economic integration.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('integrity', 'noun', 'ɪnˈteɡrəti', 'the quality of being honest and having strong moral principles', 'personal/professional/artistic integrity', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intellectual', 'adjective, noun', 'ˌɪntəˈlektʃuəl', 'connected with or using a person’s ability to think in a logical way and understand things ', 'Gifted children typically show great intellectual curiosity and a wide range of interests.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intense', 'adjective', 'ɪnˈtens', 'very great; very strong', 'We were all suffering in the intense heat.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intensify', 'verb', 'ɪnˈtensɪfaɪ', 'to increase in degree or strength; to make something increase in degree or strength', 'Violence intensified during the night.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intensity', 'noun', 'ɪnˈtensəti', 'the state or quality of being intense', 'intensity of light/sound/colour', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intensive', 'adjective', 'ɪnˈtensɪv', 'involving a lot of work or activity done in a short time', 'an intensive language course', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intent', 'noun', 'ɪnˈtent', 'what you intend to do ', 'She denies possessing the drug with intent to supply.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('interact', 'verb', 'ˌɪntərˈækt', 'to communicate with somebody, especially while you work, play or spend time with them', 'Teachers have a limited amount of time to interact with each child.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('interaction', 'noun', 'ˌɪntərˈækʃn', 'the act of communicating with somebody, especially while you work, play or spend time with them', 'the interaction between performers and their audience', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('interactive', 'adjective', 'ˌɪntərˈæktɪv', 'that allows information to be passed continuously and in both directions between a computer or other device and the person who uses it', 'interactive displays/video', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('interface', 'noun', 'ˈɪntəfeɪs', 'the way a computer program presents information to a user or receives information from a user, in particular the layout of the screen and the menus', 'the user interface', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('interfere', 'verb', 'ˌɪntəˈfɪə(r)', 'to get involved in and try to influence a situation that should not really involve you, in a way that annoys other people', 'I wish my mother would stop interfering and let me make my own decisions.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('interference', 'noun', 'ˌɪntəˈfɪərəns', 'the act of getting involved in and trying to influence a situation that should not really involve you, in a way that annoys other people ', 'interference (in something), They resent foreign interference in the internal affairs of their country.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('interim', 'adjective', 'ˈɪntərɪm', 'intended to last for only a short time until somebody/something more permanent is found', 'an interim government/measure/report', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intermediate', 'adjective', 'ˌɪntəˈmiːdiət', 'located between two places, things, states, etc.', 'an intermediate stage/step in a process', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intervene', 'verb', 'ˌɪntəˈviːn', 'to become involved in a situation in order to improve or help it', 'She might have been killed if the neighbours hadn''t intervened.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intervention', 'noun', 'ˌɪntəˈvenʃn', 'action taken to improve or help a situation', 'calls for government intervention to save the steel industry', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intimate', 'adjective', 'ˈɪntɪmət', 'having a close and friendly relationship', 'intimate friends', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('intriguing', 'adjective', 'ɪnˈtriːɡɪŋ', 'very interesting because of being unusual or not having an obvious answer', 'These discoveries raise intriguing questions.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('invade', 'verb', 'ɪnˈveɪd', 'to enter a country, town, etc. using military force in order to take control of it', 'Troops invaded on August 9th that year.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('invasion', 'noun', 'ɪnˈveɪʒn', 'the act of an army entering another country by force in order to take control of it', 'the German invasion of Poland in 1939', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('investigator', 'noun', 'ɪnˈvestɪɡeɪtə(r)', 'a person who examines a situation such as an accident or a crime to find out the truth', 'air safety investigators', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('investor', 'noun', 'ɪnˈvestə(r)', 'a person or an organization that invests money in something', 'small investors (= private people)', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('invisible', 'adjective', 'ɪnˈvɪzəbl', 'that cannot be seen', 'a wizard who could make himself invisible', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('invoke', 'verb', 'ɪnˈvəʊk', 'to mention or use a law, rule, etc. as a reason for doing something', 'It is unlikely that libel laws will be invoked.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('involved', 'adjective', 'ɪnˈvɒlvd', 'taking part in something; being part of something or connected with something', 'Some people tried to stop the fight but I didn''t want to get involved.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ironic', 'adjective', 'aɪˈrɒnɪk', 'showing that you really mean the opposite of what you are saying; expressing irony', 'an ironic comment', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ironically', 'adverb', 'aɪˈrɒnɪkli', 'in a way that shows that you really mean the opposite of what you are saying; in a way that expresses irony', 'He smiled ironically.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('irony', 'noun', 'ˈaɪrəni', 'the funny or strange aspect of a situation that is very different from what you expect; a situation like this', 'It was one of life''s little ironies.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('irrelevant', 'adjective', 'ɪˈreləvənt', 'not important to or connected with a situation', 'totally/completely/largely irrelevant', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('isolate', 'verb', 'ˈaɪsəleɪt', 'to separate somebody/something physically or socially from other people or things', 'isolate somebody/yourself/something, Patients with the disease should be isolated.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('isolated', 'adjective', 'ˈaɪsəleɪtɪd', 'far away from any others', 'isolated rural areas', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('isolation', 'noun', 'ˌaɪsəˈleɪʃn', 'the act of separating somebody/something; the state of being separate', 'geographical isolation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('jail', 'noun, verb', 'dʒeɪl', 'a prison', 'She spent a year in jail.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('January', 'noun', 'ˈdʒænjuəri', 'the 1st month of the year, between December and February', 'She was born in January.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('jazz', 'noun', 'dʒæz', 'a type of music with strong rhythms, in which the players often improvise (= make up the music as they are playing), originally created by African American musicians at the beginning of the 20th century', 'traditional/modern jazz', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('jet', 'noun', 'dʒet', 'a plane driven by jet engines', 'a jet aircraft/fighter/airliner', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('journal', 'noun', 'ˈdʒɜːnl', 'a newspaper or magazine that deals with a particular subject or profession', 'a scientific/an academic journal', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('journalism', 'noun', 'ˈdʒɜːnəlɪzəm', 'the work of collecting and writing news stories for newspapers, magazines, radio, television or online news sites; the news stories that are written', 'I''d like a career in journalism.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('judicial', 'adjective', 'dʒuˈdɪʃl', 'connected with a court, a judge or legal judgement', 'judicial powers', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('July', 'noun', 'dʒuˈlaɪ', 'the 7th month of the year, between June and August', 'in July, She was born in July.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('junction', 'noun', 'ˈdʒʌŋkʃn', 'the place where two or more roads or railway lines meet', 'It was near the junction of City Road and Old Street.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('June', 'noun', 'dʒuːn', 'the 6th month of the year, between May and July', 'She was born in June.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('jurisdiction', 'noun', 'ˌdʒʊərɪsˈdɪkʃn', 'the authority that an official organization has to make legal decisions about somebody/something', 'jurisdiction over somebody/something, The English court had no jurisdiction over the defendants.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('jury', 'noun', 'ˈdʒʊəri', 'a group of members of the public who listen to the facts of a case in a court and decide whether or not somebody is guilty of a crime, or whether a claim has been proved', 'members of the jury', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('justification', 'noun', 'ˌdʒʌstɪfɪˈkeɪʃn', 'a good reason why something exists or is done', 'justification for doing something, I can see no possible justification for any further tax increases.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('kidnap', 'verb', 'ˈkɪdnæp', 'to take somebody away illegally and keep them as a prisoner, especially in order to get money or something else for returning them', 'Two businessmen have been kidnapped by terrorists.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('kidney', 'noun', 'ˈkɪdni', 'either of the two organs in the body that remove waste products from the blood and produce urine', 'a kidney infection', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('kingdom', 'noun', 'ˈkɪŋdəm', 'a country that has a king or queen as head of state (= official leader of the country)', 'the United Kingdom', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('kit', 'noun', 'kɪt', 'a set of tools or equipment that you use for a particular purpose', 'a first-aid kit', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lab', 'noun', 'læb', 'a laboratory', 'a computer/research lab', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('laboratory', 'noun', 'ləˈbɒrətri', 'a room or building used for scientific research, experiments, testing, etc.', 'a clinical/research laboratory', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lad', 'noun', 'læd', 'a boy or young man', 'Things have changed since I was a lad.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ladder', 'noun', 'ˈlædə(r)', 'a piece of equipment for climbing up and down a wall, the side of a building, etc., consisting of two lengths of wood or metal that are joined together by steps or rungs', 'to climb up/fall off a ladder', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('landing', 'noun', 'ˈlændɪŋ', 'an act of bringing an aircraft or a spacecraft down to the ground after a journey', 'a perfect/smooth/safe landing', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('landlord', 'noun', 'ˈlændlɔːd', 'a person or company from whom you rent a room, a house, an office, etc.', 'a buy-to-let landlord (= who buys houses and flats in order to rent them out)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('landmark', 'noun', 'ˈlændmɑːk', 'something, such as a large building, that you can see clearly from a distance and that will help you to know where you are', 'The Empire State Building is a familiar landmark on the New York skyline.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lap', 'noun', 'læp', 'the top part of your legs that forms a flat surface when you are sitting down', 'on somebody''s lap, There''s only one seat so you''ll have to sit on my lap.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('laptop', 'noun', 'ˈlæptɒp', 'a small computer that can work with a battery and be easily carried', 'I opened my laptop and started typing.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('large-scale', 'adjective', 'ˌlɑːdʒ ˈskeɪl', 'involving many people or things, especially over a wide area', 'Large areas of the forest will be cleared for ranching as part of a large-scale development plan.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('laser', 'noun', 'ˈleɪzə(r)', 'a device that gives out light in which all the waves oscillate (= change direction and strength) together, typically producing a powerful beam of light that can be used for cutting metal, in medical operations, etc.', 'a laser beam', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lately', 'adverb', 'ˈleɪtli', 'recently; in the recent past', 'Have you seen her lately?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('laughter', 'noun', 'ˈlɑːftə(r)', 'the act or sound of laughing', 'to roar/howl with laughter', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lawn', 'noun', 'lɔːn', 'an area of ground covered in short grass in a garden or park, or used for playing a game on', 'In summer we have to mow the lawn twice a week.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lawsuit', 'noun', 'ˈlɔːsuːt', 'a claim or complaint against somebody that a person or an organization can make in court', 'He filed a lawsuit against his record label.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('layout', 'noun', 'ˈleɪaʊt', 'the way in which the parts of something such as the page of a book, a website, a garden or a building are arranged', 'the layout of streets', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('leadership', 'noun', 'ˈliːdəʃɪp', 'the state or position of being a leader', 'a leadership role/position', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('leaflet', 'noun', 'ˈliːflət', 'a printed sheet of paper or a few printed pages that are given free to advertise or give information about something', 'We picked up a few leaflets on local places of interest.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('leak', 'noun, verb', 'liːk', 'a small hole that lets liquid or gas flow in or out of something by accident', 'a leak in the roof', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('leap', 'noun, verb', 'liːp', 'a long or high jump', 'a leap of six metres', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('learning', 'noun', 'ˈlɜːnɪŋ', 'the process of learning something', 'lifelong/adult learning', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('legacy', 'noun', 'ˈleɡəsi', 'money or property that is given to you by somebody when they die', 'They each received a legacy of $5 000.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('legend', 'noun', 'ˈledʒənd', 'a story from ancient times about people and events, that may or may not be true; this type of story', 'The film is based on the legend of Robin Hood.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('legendary', 'adjective', 'ˈledʒəndri', 'very famous and talked about a lot by people', 'a legendary figure', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('legislation', 'noun', 'ˌledʒɪsˈleɪʃn', 'a law or a set of laws passed by a parliament', 'an important piece of legislation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('legislative', 'adjective', 'ˈledʒɪslətɪv', 'connected with the act of making and passing laws', 'a legislative assembly/body/council', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('legislature', 'noun', 'ˈledʒɪslətʃə(r)', 'a group of people who have the power to make and change laws', 'a democratically elected legislature', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('legitimate', 'adjective', 'lɪˈdʒɪtɪmət', 'for which there is a fair and acceptable reason', 'a legitimate grievance', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('leisure', 'noun', 'ˈleʒə(r)', 'time when you are not working or studying; free time', 'These days we have more money and more leisure to enjoy it.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lengthy', 'adjective', 'ˈleŋkθi', 'very long, and often too long, in time or size', 'lengthy delays', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lens', 'noun', 'lenz', 'a curved piece of glass or plastic that makes things look larger, smaller or clearer when you look through it', 'a pair of glasses with tinted lenses', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lesbian', 'adjective', 'ˈlezbiən', 'sexually attracted to other women; connected with lesbians', 'the lesbian and gay community', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lesser', 'adjective', 'ˈlesə(r)', 'not as great in size, amount or importance as something/somebody else', 'people of lesser importance', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lethal', 'adjective', 'ˈliːθl', 'causing or able to cause death', 'She had been given a lethal dose of poison.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('liable', 'adjective', 'ˈlaɪəbl', 'legally responsible for paying the cost of something', 'You will be liable for any damage caused.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('liberal', 'adjective, noun', 'ˈlɪbərəl', 'willing to understand and respect other people’s behaviour, opinions, etc., especially when they are different from your own; believing people should be able to choose how they behave', 'liberal attitudes/views/opinions', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('liberation', 'noun', 'ˌlɪbəˈreɪʃn', 'the act or process of freeing a country or a person from the control of somebody else', 'a war of liberation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('liberty', 'noun', 'ˈlɪbəti', 'freedom to live as you choose without too many limits from government or authority', 'the fight for justice and liberty', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lifelong', 'adjective', 'ˈlaɪflɒŋ', 'lasting or existing all through your life', 'Paul became his lifelong friend.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lifestyle', 'noun', 'ˈlaɪfstaɪl', 'the way in which a person or a group of people lives and works', 'Many people are trying to adopt a healthy lifestyle these days.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lifetime', 'noun', 'ˈlaɪftaɪm', 'the length of time that somebody lives or that something lasts', 'a lifetime of experience', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lighting', 'noun', 'ˈlaɪtɪŋ', 'the arrangement or type of light in a place', 'electric/natural lighting', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('likelihood', 'noun', 'ˈlaɪklihʊd', 'the chance of something happening; how likely something is to happen', 'There is very little likelihood of that happening.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('likewise', 'adverb', 'ˈlaɪkwaɪz', 'the same; in a similar way', 'He voted for the change and he expected his colleagues to do likewise.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('limb', 'noun', 'lɪm', 'an arm or a leg; a similar part of an animal, such as a wing', 'an artificial limb', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('limitation', 'noun', 'ˌlɪmɪˈteɪʃn', 'the act or process of limiting or controlling somebody/something', 'They would resist any limitation of their powers.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('line-up', 'noun', 'ˈlaɪn ʌp', 'the people who are going to take part in a particular event', 'an impressive line-up of speakers', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('linear', 'adjective', 'ˈlɪniə(r)', 'of or in lines', 'In his art he broke the laws of scientific linear perspective.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('linger', 'verb', 'ˈlɪŋɡə(r)', 'to continue to exist for longer than expected', 'The faint smell of her perfume lingered in the room.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lion', 'noun', 'ˈlaɪən', 'a large, powerful animal of the cat family that hunts in groups and lives in parts of Africa and southern Asia. Lions have yellow-brown fur and the male has a mane (= long, thick hair round its neck).', 'The lion shook its mane and roared.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('listener', 'noun', 'ˈlɪsənə(r)', 'a person who listens', 'a good listener (= somebody who you can rely on to listen with attention or sympathy)', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('listing', 'noun', 'ˈlɪstɪŋ', 'a list, especially an official or published list of people or things, often arranged in alphabetical order', 'a comprehensive listing of all airlines', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('literacy', 'noun', 'ˈlɪtərəsi', 'the ability to read and write', 'a campaign to promote adult literacy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('literally', 'adverb', 'ˈlɪtərəli', 'in a literal way', 'The word ‘planet’ literally means ‘wandering body’.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('literary', 'adjective', 'ˈlɪtərəri', 'connected with literature', 'literary criticism/theory', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('litter', 'noun', 'ˈlɪtə(r)', 'small pieces of rubbish such as paper, cans and bottles, that people have left lying in a public place', 'There will be fines for people who drop litter.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('liver', 'noun', 'ˈlɪvə(r)', 'a large organ in the body that cleans the blood and produces bile', 'liver disease', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lobby', 'noun, verb', 'ˈlɒbi', 'a large area inside the entrance of a public building where people can meet and wait', 'a hotel lobby', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('log', 'noun, verb', 'lɒɡ', 'a thick piece of wood that is cut from or has fallen from a tree', 'logs for the fire', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('logo', 'noun', 'ˈləʊɡəʊ', 'a printed design or symbol that a company or an organization uses as its special sign', 'All over the world there are red and white paper cups bearing the company logo.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('long-standing', 'adjective', 'ˌlɒŋ ˈstændɪŋ', 'that has existed or lasted for a long time', 'a long-standing relationship', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('long-term', 'adjective, adverb', 'ˌlɒŋ ˈtɜːm', 'lasting or having an effect over a long period of time', 'Our long-term goal is to lower operating costs by 10 per cent.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('long-time', 'adjective', 'ˈlɒŋ taɪm', 'having been the particular thing mentioned for a long time', 'his long-time colleague', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('loom', 'verb', 'luːm', 'to appear as a large shape that is not clear, especially in a frightening way', 'A dark shape loomed up ahead of us.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('loop', 'noun', 'luːp', 'a shape like a curve or circle made by a line curving right round', 'The road went in a huge loop around the lake.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lot', 'adverb, determiner, pronoun', 'lɒt', 'used with verbs to mean ‘a great amount’', 'I care a lot about you.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lottery', 'noun', 'ˈlɒtəri', 'a way of raising money for a government, charity, etc. by selling tickets that have different numbers on them that people have chosen. Numbers are then chosen by chance and the people who have those numbers on their tickets win prizes.', 'the national/state lottery', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lower', 'verb', 'ˈləʊə(r)', 'to reduce something or to become less in value, quality, etc.', 'lower something, He lowered his voice to a whisper.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('loyalty', 'noun', 'ˈlɔɪəlti', 'the quality of being constant in your support of somebody/something', 'Can I count on your loyalty?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('luxury', 'adjective, noun', 'ˈlʌkʃəri', 'expensive and of very high quality', 'a luxury hotel/car/apartment', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('lyric', 'noun', 'ˈlɪrɪk', 'the words of a popular song', 'music and lyrics by Rodgers and Hart', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('magical', 'adjective', 'ˈmædʒɪkl', 'containing magic; used in magic', 'magical powers', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('magistrate', 'noun', 'ˈmædʒɪstreɪt', 'an official who acts as a judge in the lowest courts of law', 'to come up before the magistrates', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('magnetic', 'adjective', 'mæɡˈnetɪk', 'behaving like a magnet; that can be attracted by a magnet', 'magnetic materials', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('magnificent', 'adjective', 'mæɡˈnɪfɪsnt', 'extremely attractive and impressive; deserving praise', 'The Taj Mahal is a magnificent building.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('magnitude', 'noun', 'ˈmæɡnɪtjuːd', 'the great size or importance of something; the degree to which something is large or important', 'We did not realize the magnitude of the problem.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mainland', 'noun', 'ðə ˈmeɪnlənd', 'the main area of land of a country or region, not including any islands near to it', 'to/from the mainland, a boat to/from the mainland ', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mainstream', 'adjective, noun', 'ˈmeɪnstriːm', 'considered normal because it reflects what is done or accepted by most people ', 'mainstream culture/politics', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('maintenance', 'noun', 'ˈmeɪntənəns', 'the act of keeping something in good condition by checking or repairing it regularly', 'The school pays for heating and the maintenance of the buildings.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('making', 'noun', 'ˈmeɪkɪŋ', 'the act or process of making or producing something', 'strategic decision-making', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mandate', 'noun', 'ˈmændeɪt', 'the authority to do something, given to a government or other organization by the people who vote for it in an election', 'It is undemocratic to govern an area without an electoral mandate.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mandatory', 'adjective', 'ˈmændətəri', 'required by law', 'The offence carries a mandatory life sentence.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('manifest', 'verb', 'ˈmænɪfest', 'to show something clearly, especially a feeling, an attitude or a quality', 'Social tensions were manifested in the recent political crisis.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('manipulate', 'verb', 'məˈnɪpjuleɪt', 'to control or influence somebody/something, often in a dishonest way so that they do not realize it', 'manipulate somebody/something, She uses her charm to manipulate people.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('manipulation', 'noun', 'məˌnɪpjuˈleɪʃn', 'behaviour that controls or influences somebody/something, often in a dishonest way so that they do not realize it', 'Advertising like this is a cynical manipulation of the elderly.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('manuscript', 'noun', 'ˈmænjuskrɪpt', 'a copy of a book, piece of music, etc. before it has been printed', 'an unpublished/original manuscript', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('marathon', 'noun', 'ˈmærəθən', 'a long running race of about 42 kilometres or 26 miles', 'the London marathon', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('March', 'noun, noun, verb', 'mɑːtʃ', 'the 3rd month of the year, between February and April', 'She was born in March.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('margin', 'noun', 'ˈmɑːdʒɪn', 'the empty space at the side of a written or printed page', 'the left-hand/right-hand margin', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('marginal', 'adjective', 'ˈmɑːdʒɪnl', 'small and not important', 'a marginal improvement in weather conditions', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('marine', 'adjective', 'məˈriːn', 'connected with the sea and the creatures and plants that live there', 'marine life', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('marker', 'noun', 'ˈmɑːkə(r)', 'an object or a sign that shows the position of something', 'a boundary marker', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('marketplace', 'noun', 'ˈmɑːkɪtpleɪs', 'the activity of competing with other companies to buy and sell goods, services, etc.', 'Companies must be able to survive in the marketplace.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('martial', 'adjective', 'ˈmɑːʃl', '', NULL, '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mask', 'noun', 'mɑːsk', 'something that you wear over your face to hide it, or to frighten or entertain other people ', 'The robbers wore stocking masks.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('massacre', 'noun', 'ˈmæsəkə(r)', 'the killing of a large number of people especially in a cruel way', 'the bloody massacre of innocent civilians', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mathematical', 'adjective', 'ˌmæθəˈmætɪkl', 'connected with or involving mathematics', 'mathematical calculations/problems/models', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mathematics', 'noun', 'ˌmæθəˈmætɪks', 'the science of numbers and shapes. Branches of mathematics include arithmetic, algebra, geometry and trigonometry.', 'the school mathematics curriculum', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('maths', 'noun', 'mæθs', 'mathematics, especially as a subject in school', 'The core subjects are English, maths and science.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mature', 'adjective, verb', 'məˈtʃʊə(r)', 'behaving in a sensible way, like an adult', 'Jane is very mature for her age.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('maximize', 'verb', 'ˈmæksɪmaɪz', 'to increase something as much as possible', 'to maximize efficiency/fitness/profits', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('meaningful', 'adjective', 'ˈmiːnɪŋfl', 'serious and important', 'a meaningful relationship/discussion/experience', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('meantime', 'noun', 'ˈmiːntaɪm', 'for a short period of time but not permanently', 'I''m changing my email address but for the meantime you can use the old one.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mechanic', 'noun', 'məˈkænɪk', 'a person whose job is repairing machines, especially the engines of vehicles', 'a car/motor mechanic', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mechanical', 'adjective', 'məˈkænɪkl', 'operated by power from an engine', 'a mechanical device/toy/clock', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mechanism', 'noun', 'ˈmekənɪzəm', 'a set of moving parts in a machine that performs a task', 'a delicate watch mechanism', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('medal', 'noun', 'ˈmedl', 'a flat piece of metal, usually like a coin in shape, that is given to the winner of a competition or to somebody who has been brave, for example in war', 'to win a gold medal in the Olympics', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('medication', 'noun', 'ˌmedɪˈkeɪʃn', 'a drug or another form of medicine that you take to prevent or to treat an illness; treatment involving drugs', 'Are you currently taking any medication?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('medieval', 'adjective', 'ˌmediˈiːvl', 'connected with the Middle Ages (about AD 1000 to AD 1450)', 'medieval architecture/castles/manuscripts', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('meditation', 'noun', 'ˌmedɪˈteɪʃn', 'the practice of focusing your mind in silence, especially for religious reasons or in order to make your mind calm', 'She found peace through yoga and meditation.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('melody', 'noun', 'ˈmelədi', 'a tune, especially the main tune in a piece of music written for several instruments or voices', 'a haunting melody', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('memo', 'noun', 'ˈmeməʊ', 'an official note from one person to another in the same organization', 'to write/send a memo', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('memoir', 'noun', 'ˈmemwɑː(r)', 'an account written by somebody, especially somebody famous, about their life and experiences', 'O''Connor published a childhood memoir.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('memorable', 'adjective', 'ˈmemərəbl', 'worth remembering or easy to remember, especially because of being special or unusual', 'The holiday provided many memorable moments.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('memorial', 'noun', 'məˈmɔːriəl', 'a statue, stone, etc. that is built in order to remind people of an important past event or of a famous person who has died', 'a war memorial (= in memory of soldiers who died in a war)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mentor', 'noun', 'ˈmentɔː(r)', 'an experienced person who advises and helps somebody with less experience over a period of time', 'She was a friend and mentor to many young actors.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('merchant', 'noun', 'ˈmɜːtʃənt', 'a person who buys and sells goods in large quantities, especially one who imports and exports goods', 'a coal/wine merchant', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mercy', 'noun', 'ˈmɜːsi', 'a kind or forgiving attitude towards somebody that you have the power to harm or right to punish', 'to ask/beg/plead for mercy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('merge', 'verb', 'mɜːdʒ', 'to combine or make two or more things combine to form a single thing', 'The banks are set to merge next year.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('merger', 'noun', 'ˈmɜːdʒə(r)', 'the act of joining two or more organizations or businesses into one', 'If the merger goes through, thousands of jobs will be lost.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('merit', 'noun', 'ˈmerɪt', 'the quality of being good and of deserving praise or reward', 'a work of outstanding artistic merit', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('metaphor', 'noun', 'ˈmetəfə(r)', 'a word or phrase used to describe somebody/something else, in a way that is different from its normal use, in order to show that the two things have the same qualities and to make the description more powerful, for example She has a heart of stone; the use of such words and phrases', 'a game of football used as a metaphor for the competitive struggle of life', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('methodology', 'noun', 'ˌmeθəˈdɒlədʒi', 'a set of methods and principles used to perform a particular activity', 'recent changes in the methodology of language teaching', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('midst', 'noun', 'mɪdst', 'the middle part of something', 'in the midst of something, Such beauty was unexpected in the midst of the city.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('migration', 'noun', 'maɪˈɡreɪʃn', 'the movement every year of large numbers of birds or animals from one place to another', 'the seasonal migration of blue whales', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('militant', 'adjective, noun', 'ˈmɪlɪtənt', 'using, or willing to use, force or strong pressure to achieve your aims, especially to achieve social or political change', 'militant groups/leaders', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('militia', 'noun', 'məˈlɪʃə', 'a group of people who are not professional soldiers but who have had military training and can act as an army', 'He said he would call out the state militia if the rebels did not surrender.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mill', 'noun', 'mɪl', 'a building fitted with equipment for grinding grain into flour; a machine for grinding grain', 'The old mill has been converted into apartments.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('million', 'number', 'ˈmɪljən', '1 000 000', 'a population of half a million', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('miner', 'noun', 'ˈmaɪnə(r)', 'a person who works in a mine taking out coal, gold, diamonds, etc.', 'Rescuers are trying to save miners trapped underground after a gas explosion.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('minimal', 'adjective', 'ˈmɪnɪml', 'very small in size or amount; as small as possible', 'The work was carried out at minimal cost.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('minimize', 'verb', 'ˈmɪnɪmaɪz', 'to reduce something, especially something bad, to the lowest possible level', 'Good hygiene helps to minimize the risk of infection.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mining', 'noun', 'ˈmaɪnɪŋ', 'the process of getting coal and other minerals from under the ground; the industry involved in this', 'coal/diamond/gold/tin mining', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('miracle', 'noun', 'ˈmɪrəkl', 'an act or event that does not follow the laws of nature and is believed to be caused by God', 'the miracle of rising from the grave', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('miserable', 'adjective', 'ˈmɪzrəbl', 'very unhappy or uncomfortable', 'We were cold, wet and thoroughly miserable.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('misery', 'noun', 'ˈmɪzəri', 'great physical or mental pain', 'Fame brought her nothing but misery.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('misleading', 'adjective', 'ˌmɪsˈliːdɪŋ', 'giving the wrong idea or impression and making you believe something that is not true', 'misleading information/advertisements', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('missile', 'noun', 'ˈmɪsaɪl', 'a weapon that is sent through the air and that explodes when it hits the thing that it is aimed at', 'nuclear missiles', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mission', 'noun', 'ɪmˈpɒsəbl', 'that cannot exist or be done; not possible', 'almost/virtually/nearly impossible', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mob', 'noun', 'mɒb', 'a large crowd of people, especially one that may become violent or cause trouble', 'an angry/unruly mob', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mobility', 'noun', 'məʊˈbɪləti', 'the ability to move easily from one place, social class or job to another', 'social/geographical/career mobility', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mobilize', 'verb', 'ˈməʊbəlaɪz', 'to work together in order to achieve a particular aim; to organize a group of people to do this', 'The unions mobilized thousands of workers in a protest against the cuts.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mode', 'noun', 'məʊd', 'a particular way of doing something; a particular type of something', 'a mode of communication', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('moderate', 'adjective', 'ˈmɒdərət', 'that is neither very good, large, hot, etc. nor very bad, small, cold, etc.', 'students of moderate ability', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('modest', 'adjective', 'ˈmɒdɪst', 'not very large, expensive, important, etc.', 'modest improvements/reforms', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('modification', 'noun', 'ˌmɒdɪfɪˈkeɪʃn', 'the act or process of changing something in order to improve it or make it more acceptable; a change that is made', 'Considerable modification of the existing system is needed.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('modify', 'verb', 'ˈmɒdɪfaɪ', 'to change something slightly, especially in order to make it more suitable for a particular purpose', 'Patients are taught how to modify their diet.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('momentum', 'noun', 'məˈmentəm', 'the ability to keep increasing or developing', 'The fight for his release gathers momentum each day.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('Monday', 'noun', 'ˈmʌndeɪ', 'the day of the week after Sunday and before Tuesday, the first day of the working week', 'It''s Monday today, isn''t it?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('monk', 'noun', 'mʌŋk', 'a member of a religious group of men who often live apart from other people in a monastery and who do not marry or have personal possessions', 'Benedictine/Buddhist monks', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('monkey', 'noun', 'ˈmʌŋki', 'an animal with a long tail, that climbs trees and lives in hot countries. There are several types of monkey and they are related to apes and humans.', 'Like humans, apes and monkeys live in complex social groupings.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('monopoly', 'noun', 'məˈnɒpəli', 'the complete control of trade in particular goods or the supply of a particular service; a type of goods or a service that is controlled in this way', 'In the past central government had a monopoly on television broadcasting.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('monster', 'noun', 'ˈmɒnstə(r)', '(in stories) an imaginary creature that is very large, ugly and frightening', 'a monster with three heads', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('monthly', 'adjective', 'ˈmʌnθli', 'happening once a month or every month', 'a monthly meeting/visit/magazine', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('monument', 'noun', 'ˈmɒnjumənt', 'a building, column, statue, etc. built to remind people of a famous person or event', 'A monument to him was erected in St Paul''s Cathedral.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('morality', 'noun', 'məˈræləti', 'principles relating to right and wrong or good and bad behaviour', 'matters of public/private morality', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mortgage', 'noun', 'ˈmɔːɡɪdʒ', 'a legal agreement by which a bank or similar organization lends you money to buy a house, etc., and you pay the money back over a particular number of years; the sum of money that you borrow', 'to apply for/take out/pay off a mortgage', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mosque', 'noun', 'mɒsk', 'a building where Muslims go to worship (= praise God)', 'I used to pray at the local mosque with my father and grandfather.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('motivate', 'verb', 'ˈməʊtɪveɪt', 'to be the reason why somebody does something or behaves in a particular way', 'motivate somebody (to do something), What motivates people to carry out such attacks?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('motivation', 'noun', 'ˌməʊtɪˈveɪʃn', 'the reason why somebody does something or behaves in a particular way', 'motivation (behind something), What is the motivation behind this sudden change?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('motive', 'noun', 'ˈməʊtɪv', 'a reason for doing something', 'There seemed to be no motive for the murder.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('motorist', 'noun', 'ˈməʊtərɪst', 'a person driving a car', 'The accident was reported by a passing motorist.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('multiple', 'adjective', 'ˈmʌltɪpl', 'many in number; involving many different people or things', 'The shape appears multiple times within each painting.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('municipal', 'adjective', 'mjuːˈnɪsɪpl', 'connected with or belonging to a town, city or district that has its own local government', 'municipal elections/councils', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('mutual', 'adjective', 'ˈmjuːtʃuəl', 'used to describe feelings that two or more people have for each other equally, or actions that affect two or more people equally', 'mutual respect/understanding', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('myth', 'noun', 'mɪθ', 'a story from ancient times, especially one that was told to explain natural events or to describe the early history of a people; this type of story', 'ancient Greek myths', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('namely', 'adverb', 'ˈneɪmli', 'used to introduce more exact and detailed information about something that you have just mentioned', 'We need to concentrate on our target audience, namely women aged between 20 and 30.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('narrative', 'adjective, noun', 'ˈnærətɪv', 'describing events or telling a story', 'narrative fiction', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nasty', 'adjective', 'ˈnɑːsti', 'very bad or unpleasant', 'He had a nasty accident.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nationwide', 'adjective', 'ˌneɪʃnˈwaɪd', 'happening or existing in all parts of a particular country', 'a nationwide campaign', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('native', 'adjective, noun', 'ˈneɪtɪv', 'connected with the place where you were born and lived for the first years of your life', 'your native land/country/city', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('naval', 'adjective', 'ˈneɪvl', 'connected with the navy of a country', 'a naval base/officer/battle', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('navigation', 'noun', 'ˌnævɪˈɡeɪʃn', 'the skill or the process of planning a route for a ship or other vehicle and taking it there', 'a maker of in-car navigation systems', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('necessity', 'noun', 'nəˈsesəti', 'the fact that something must happen or be done; the need for something', 'necessity for something, We recognize the necessity for a written agreement.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('neglect', 'noun, verb', 'nɪˈɡlekt', 'the fact of not giving enough care or attention to something/somebody; the state of not receiving enough care or attention', 'The buildings are crumbling from years of neglect.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('negotiate', 'verb', 'nɪˈɡəʊʃieɪt', 'to try to reach an agreement by formal discussion', 'negotiate (with somebody) (for something), The government will not negotiate with terrorists.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('negotiation', 'noun', 'nɪˌɡəʊʃiˈeɪʃn', 'formal discussion between people who are trying to reach an agreement', 'peace/trade/contract negotiations', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('neighbouring', 'adjective', 'ˈneɪbərɪŋ', 'located or living near or next to a place or person', 'a neighbouring house', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('neutral', 'adjective', 'ˈnjuːtrəl', 'not supporting or helping either side in a disagreement, competition, etc.', 'Journalists are supposed to be politically neutral.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('newsletter', 'noun', 'ˈnjuːzletə(r)', 'a report containing news of the activities of a club or organization that is sent regularly to all its members', 'Our sailing club produces a monthly newsletter.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('next to', 'preposition', 'ˈnekst tə', 'in or into a position right by somebody/something', 'We sat next to each other.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('niche', 'noun', 'niːʃ', 'a comfortable or suitable role, job, way of life, etc.', 'He eventually found his niche in sports journalism.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nightmare', 'noun', 'ˈnaɪtmeə(r)', 'a dream that is very frightening or unpleasant', 'He still has nightmares about the accident.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nine', 'number', 'naɪn', '9', 'There are only nine of these rare animals left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nineteen', 'number', 'ˌnaɪnˈtiːn', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ninety', 'number', 'ˈnaɪnti', '90', 'The temperature must be in the nineties today.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('no one', 'pronoun', 'ˈnəʊ wʌn', 'not anyone; no person', 'No one was at home.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('noble', 'adjective', 'ˈnəʊbl', 'having or showing fine personal qualities that people admire, such as courage, honesty and care for others', 'a noble leader', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nobody', 'pronoun', 'ˈnəʊbədi', 'not anyone; no person', 'Nobody knew what to say.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nod', 'verb', 'nɒd', 'if you nod, nod your head or your head nods, you move your head up and down to show agreement, understanding, etc.', 'I asked him if he would help me and he nodded.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nominate', 'verb', 'ˈnɒmɪneɪt', 'to formally suggest that somebody/something should be chosen for an important role, prize, position, etc.', 'nominate somebody/something (for something), She has been nominated for the presidency.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nomination', 'noun', 'ˌnɒmɪˈneɪʃn', 'the act of suggesting or choosing somebody as a candidate in an election, or for a job or an award; the fact of being suggested for this', 'Membership of the club is by nomination only.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nominee', 'noun', 'ˌnɒmɪˈniː', 'a person who has been formally suggested for a job, a prize, etc.', 'He was chosen as the party''s presidential nominee.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('non-profit', 'adjective', 'ˌnɒn ˈprɒfɪt', 'without the aim of making a profit', 'an independent non-profit organization', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nonetheless', 'adverb', 'ˌnʌnðəˈles', 'despite this fact', 'The book is too long but, nonetheless, informative and entertaining.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('noon', 'noun', 'nuːn', '12 o’clock in the middle of the day', 'We should be there by noon.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('norm', 'noun', 'nɔːm', 'a situation or a pattern of behaviour that is usual or expected', 'The new design is a departure from the norm.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('notable', 'adjective', 'ˈnəʊtəbl', 'deserving to be noticed or to receive attention; important', 'a notable success/achievement/example', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('notably', 'adverb', 'ˈnəʊtəbli', 'used for giving a good or the most important example of something', 'The house had many drawbacks, most notably its price.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('notebook', 'noun', 'ˈnəʊtbʊk', 'a small book of plain paper for writing notes in', 'The police officer wrote the details down in his notebook.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('notify', 'verb', 'ˈnəʊtɪfaɪ', 'to formally or officially tell somebody about something', 'notify somebody, Competition winners will be notified by post.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('notion', 'noun', 'ˈnəʊʃn', 'an idea, a belief or an understanding of something', 'notion of something, a political system based on the notions of equality and liberty', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('notorious', 'adjective', 'nəʊˈtɔːriəs', 'well known for being bad', 'a notorious criminal', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('novelist', 'noun', 'ˈnɒvəlɪst', 'a person who writes novels', 'a romantic/historical novelist', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('November', 'noun', 'nəʊˈvembə(r)', 'the 11th month of the year, between October and December', 'She was born in November.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nowadays', 'adverb', 'ˈnaʊədeɪz', 'at the present time, in contrast with the past', 'Nowadays most kids prefer going online to reading books.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('number', 'noun, verb', 'ˈnʌmbə(r)', 'a word or symbol that represents an amount or a quantity', 'Think of a number and multiply it by two.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('numerous', 'adjective', 'ˈnjuːmərəs', 'existing in large numbers ', 'He has been late on numerous occasions.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nursery', 'noun', 'ˈnɜːsəri', 'a place where young children are cared for while their parents are at work; a day nursery or nursery school', 'at nursery, Her youngest child is at nursery now.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nursing', 'noun', 'ˈnɜːsɪŋ', 'the job or skill of caring for people who are sick or injured', 'a career in nursing', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('nutrition', 'noun', 'njuˈtrɪʃn', 'the process by which living things receive the food necessary for them to grow and be healthy', 'advice on diet and nutrition', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('o''clock', 'adverb', 'əˈklɒk', 'used with the numbers 1 to 12 when telling the time, to mean an exact hour', 'He left between five and six o''clock.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('obesity', 'noun', 'əʊˈbiːsəti', 'the quality or fact of being very fat, in a way that is not healthy', 'Obesity can increase the risk of heart disease.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('objection', 'noun', 'əbˈdʒekʃn', 'a reason why you do not like or are opposed to something; a statement about this', 'I''d like to come too, if you have no objection.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('obligation', 'noun', 'ˌɒblɪˈɡeɪʃn', 'the state of being forced to do something because it is your duty, or because of a law, etc.', 'obligation to do something, You are under no obligation to buy anything.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('oblige', 'verb', 'əˈblaɪdʒ', 'to force somebody to do something, by law, because it is a duty, etc.', 'Parents are obliged by law to send their children to school.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('observer', 'noun', 'əbˈzɜːvə(r)', 'a person who watches somebody/something', 'According to observers, the plane exploded shortly after take-off.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('obsess', 'verb', 'əbˈses', 'to completely fill your mind so that you cannot think of anything else, in a way that is not reasonable or normal', 'be obsessed by somebody/something, He''s obsessed by computers.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('obsession', 'noun', 'əbˈseʃn', 'the state in which a person’s mind is completely filled with thoughts of one particular thing or person in a way that is not reasonable or normal', 'Her fear of flying is bordering on obsession.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('obstacle', 'noun', 'ˈɒbstəkl', 'a situation, an event, etc. that makes it difficult for you to do or achieve something', 'So far, we have managed to overcome all the obstacles that have been placed in our path.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('occasional', 'adjective', 'əˈkeɪʒənl', 'happening or done sometimes but not often', 'He works for us on an occasional basis.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('occupation', 'noun', 'ˌɒkjuˈpeɪʃn', 'a job or profession', 'Please state your name, age and occupation below.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('occurrence', 'noun', 'əˈkʌrəns', 'something that happens or exists', 'a common/everyday/frequent/regular occurrence', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('October', 'noun', 'ɒkˈtəʊbə(r)', 'the 10th month of the year, between September and November', 'She was born in October.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('odds', 'noun', 'ɒdz', 'the degree to which something is likely to happen', 'The odds are very much in our favour (= we are likely to succeed).', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('offender', 'noun', 'əˈfendə(r)', 'a person who commits a crime', 'a persistent/serious/violent, etc. offender', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('offering', 'noun', 'ˈɒfərɪŋ', 'something that is produced for other people to use, watch, enjoy, etc.', 'the latest offering from the Canadian-born writer', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('offspring', 'noun', 'ˈɒfsprɪŋ', 'a child of a particular person or couple', 'the problems parents have with their teenage offspring', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('OK', 'adjective, adverb, exclamation', 'əʊˈkeɪ', 'safe and well; in a calm or happy state', 'Are you OK?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('one', 'determiner, number, pronoun', 'wʌn', 'the number 1', 'Do you want one or two?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ongoing', 'adjective', 'ˈɒnɡəʊɪŋ', 'continuing to exist or develop', 'an ongoing debate/discussion/process', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('online', 'adjective, adverb', 'ˌɒnˈlaɪn', 'available on or done using the internet or other computer network', 'Online shopping is both cheap and convenient.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('opera', 'noun', 'ˈɒprə', 'a dramatic work in which all or most of the words are sung to music; works of this type as an art form or entertainment', 'Puccini’s operas', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('operational', 'adjective', 'ˌɒpəˈreɪʃənl', 'connected with the way in which a business, machine, system, etc. works', 'operational activities/costs/difficulties', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('operator', 'noun', 'ˈɒpəreɪtə(r)', 'a person who operates equipment or a machine', 'a computer/machine operator', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('opposed', 'adjective', 'əˈpəʊzd', 'disagreeing strongly with something and trying to stop it', 'opposed to something, He was strongly opposed to modernism in art.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('opt', 'verb', 'ɒpt', 'to choose to take or not to take a particular course of action', 'opt for/against something, After graduating she opted for a career in music.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('optical', 'adjective', 'ˈɒptɪkl', 'connected with the sense of sight or the relationship between light and sight', 'optical effects', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('optimism', 'noun', 'ˈɒptɪmɪzəm', 'a feeling that good things will happen and that something will be successful', 'a mood of cautious optimism', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('optimistic', 'adjective', 'ˌɒptɪˈmɪstɪk', 'expecting good things to happen or something to be successful; showing this feeling', 'We are now taking a more optimistic view.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('or', 'conjunction', 'ɔː(r)', 'used to introduce another possibility', 'Is your sister older or younger than you?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('oral', 'adjective', 'ˈɔːrəl', 'spoken rather than written', 'a test of both oral and written French', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('orchestra', 'noun', 'ˈɔːkɪstrə', 'a large group of people who play various musical instruments together, led by a conductor', 'She plays the flute in the school orchestra.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('organic', 'adjective', 'ɔːˈɡænɪk', 'produced or practised without using artificial chemicals', 'organic cheese/vegetables/wine, etc.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('organizational', 'adjective', 'ˌɔːɡənaɪˈzeɪʃənl', 'connected with the way in which the different parts of something are arranged; connected with an organization', 'organizational changes within the party', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('organizer', 'noun', 'ˈɔːɡənaɪzə(r)', 'a person who makes the arrangements for something', 'the organizers of the festival', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('orientation', 'noun', 'ˌɔːriənˈteɪʃn', 'a person’s basic beliefs or feelings about a particular subject', 'religious/political orientation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('originate', 'verb', 'əˈrɪdʒɪneɪt', 'to happen or appear for the first time in a particular place or situation', 'The disease is thought to have originated in the tropics.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ought', 'modal verb', 'ˈɔːt tə', 'used to say what is the right thing to do', 'They ought to apologize.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outbreak', 'noun', 'ˈaʊtbreɪk', 'the sudden start of something unpleasant, especially violence or a disease', 'the outbreak of war', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outcome', 'noun', 'ˈaʊtkʌm', 'the result or effect of an action or event', 'The likely outcome is a compromise.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outfit', 'noun', 'ˈaʊtfɪt', 'a set of clothes that you wear together, especially for a particular occasion or purpose', 'She was wearing an expensive new outfit.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outing', 'noun', 'ˈaʊtɪŋ', 'a trip that you go on for pleasure or education, usually with a group of people and lasting no more than one day', 'a family outing', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outlet', 'noun', 'ˈaʊtlet', 'a shop or an organization that sells goods made by a particular company or of a particular type', 'The business has 34 retail outlets in this state alone.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outlook', 'noun', 'ˈaʊtlʊk', 'the attitude to life and the world of a particular person, group or culture', 'Travel broadens your outlook.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outrage', 'noun, verb', 'ˈaʊtreɪdʒ', 'a strong feeling of shock and anger', 'The judge''s remarks caused public outrage.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('outsider', 'noun', 'ˌaʊtˈsaɪdə(r)', 'a person who is not accepted as a member of a society, group, etc.', 'Here she felt she would always be an outsider.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('overlook', 'verb', 'ˌəʊvəˈlʊk', 'to fail to see or notice something', 'He seems to have overlooked one important fact.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('overly', 'adverb', 'ˈəʊvəli', 'too; very', 'I''m not overly fond of pasta.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('overnight', 'adverb', 'ˌəʊvəˈnaɪt', 'during or for the night', 'We stayed overnight in London after the theatre.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('overseas', 'adjective, adverb', 'ˌəʊvəˈsiːz', 'connected with foreign countries, especially those separated from your country by the sea or ocean', 'The firm is expanding into overseas markets.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('oversee', 'verb', 'ˌəʊvəˈsiː', 'to watch somebody/something and make sure that a job or an activity is done correctly', 'United Nations observers oversaw the elections.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('overturn', 'verb', 'ˌəʊvəˈtɜːn', 'if something overturns, or if somebody overturns it, it turns into a position in which the top of it is where the bottom of it normally is or on its side', 'The car skidded and overturned.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('overwhelm', 'verb', 'ˌəʊvəˈwelm', 'to have such a strong emotional effect on somebody that it is difficult for them to resist or know how to react', 'She was overwhelmed by feelings of guilt.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('overwhelming', 'adjective', 'ˌəʊvəˈwelmɪŋ', 'very great or very strong; so powerful that you cannot resist it or decide how to react', 'The evidence against him was overwhelming.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ownership', 'noun', 'ˈəʊnəʃɪp', 'the fact of owning something', 'a growth in home ownership', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('oxygen', 'noun', 'ˈɒksɪdʒən', 'a chemical element. Oxygen is a gas that is present in air and water and is necessary for people, animals and plants to live.', 'The patient didn''t seem to be getting enough oxygen.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pad', 'noun', 'pæd', 'a thick piece of soft material that is used, for example, for cleaning or protecting something or for holding liquid', 'medicated cleansing pads for sensitive skin', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('palm', 'noun', 'pɑːm', 'a straight tree with a mass of long leaves at the top, growing in tropical countries. There are several types of palm tree, some of which produce fruit.', 'a date palm', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('panic', 'noun', 'ˈpænɪk', 'a sudden feeling of great fear that cannot be controlled and prevents you from thinking clearly', 'a moment of panic', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('parade', 'noun', 'pəˈreɪd', 'a public celebration of a special day or event, usually with bands in the streets and decorated vehicles', 'the Lord Mayor’s parade', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('paragraph', 'noun', 'ˈpærəɡrɑːf', 'a section of a piece of writing, usually consisting of several sentences dealing with a single subject. The first sentence of a paragraph starts on a new line.', 'an opening/introductory paragraph', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('parameter', 'noun', 'pəˈræmɪtə(r)', 'something that decides or limits the way in which something can be done', 'to set/define the parameters', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('parental', 'adjective', 'pəˈrentl', 'connected with a parent or parents', 'parental responsibility/rights', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('parish', 'noun', 'ˈpærɪʃ', 'an area that has its own church and that a priest is responsible for', 'a parish church/priest', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('parking', 'noun', 'ˈpɑːkɪŋ', 'the act of stopping a vehicle at a place and leaving it there for a period of time', 'There is no parking here between 9 a.m. and 6 p.m.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('parliamentary', 'adjective', 'ˌpɑːləˈmentri', 'connected with a parliament; having a parliament', 'parliamentary elections', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('part-time', 'adjective', 'ˌpɑːt ˈtaɪm', 'for part of the day or week in which people work', 'She''s looking for a part-time job.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('partial', 'adjective', 'ˈpɑːʃl', 'not complete or whole', 'It was only a partial solution to the problem.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('partially', 'adverb', 'ˈpɑːʃəli', 'partly; not completely', 'The road was partially blocked by a fallen tree.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('participant', 'noun', 'pɑːˈtɪsɪpənt', 'a person who is taking part in an activity or event', 'The average age of study participants was 48 years.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('participate', 'verb', 'pɑːˈtɪsɪpeɪt', 'to take part in or become involved in an activity', 'Anyone who wishes to participate is welcome.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('participation', 'noun', 'pɑːˌtɪsɪˈpeɪʃn', 'the act of taking part in an activity or event', 'a show with lots of audience participation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('passion', 'noun', 'ˈpæʃn', 'a very strong feeling of love, hate, anger, enthusiasm, etc.', 'I admire the passion and commitment shown by the players.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('passionate', 'adjective', 'ˈpæʃənət', 'having or showing strong feelings of sexual love or of anger, etc.', 'to have a passionate nature', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('passive', 'adjective', 'ˈpæsɪv', 'accepting what happens or what people do without trying to change anything or oppose them', 'He played a passive role in the relationship.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('password', 'noun', 'ˈpɑːswɜːd', 'a series of letters, numbers, etc. that you must type into a computer or computer system in order to be able to use it', 'Enter a username and password to get into the system.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pastor', 'noun', 'ˈpɑːstə(r)', 'a minister in charge of a Christian church or group, especially in some Nonconformist churches', 'He was ordained a pastor in the Lutheran Church.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('patch', 'noun', 'pætʃ', 'a small area of something, especially one which is different from the area around it', 'a black dog with a white patch on its back', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('patent', 'noun', 'ˈpætnt', 'an official right to be the only person to make, use or sell a product or an invention; a document that proves this', 'patent on something, to apply for/obtain/take out a patent on an invention', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pathway', 'noun', 'ˈpɑːθweɪ', 'a track that serves as a path', 'They came out of the woods and onto a pathway.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('patrol', 'noun, verb', 'pəˈtrəʊl', 'the act of going to different parts of a building, an area, etc. to make sure that there is no trouble or crime', 'Security guards make regular patrols at night.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('patron', 'noun', 'ˈpeɪtrən', 'a person who gives money and support to artists and writers', 'Frederick the Great was the patron of many artists.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('peasant', 'noun', 'ˈpeznt', '(especially in the past, or in poorer countries) a farmer who owns or rents a small piece of land', 'peasant farmers', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('peculiar', 'adjective', 'pɪˈkjuːliə(r)', 'strange or unusual, especially in a way that is unpleasant or makes you worried', 'a peculiar smell/taste', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('peer', 'noun', 'pɪə(r)', 'a person who is the same age or who has the same social status as you', 'She enjoys the respect of her peers.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('penalty', 'noun', 'ˈpenəlti', 'a punishment for breaking a law, rule or contract', 'to impose a penalty', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('per cent', 'adjective, adverb, noun', 'pə ˈsent', 'by, in or for every hundred', 'a 15 per cent rise in price', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('perceive', 'verb', 'pəˈsiːv', 'to understand or think of somebody/something in a particular way', 'perceive somebody/something/yourself (as something), This discovery was perceived as a major breakthrough.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('percentage', 'noun', 'pəˈsentɪdʒ', 'the number, amount or rate of something, expressed as if it is part of a total that is 100; a part or share of a whole', 'percentage of something/somebody, What percentage of the population is/are overweight?', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('perception', 'noun', 'pəˈsepʃn', 'an idea, a belief or an image you have as a result of how you see or understand something', 'a campaign to change public perception of the police', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('persist', 'verb', 'pəˈsɪst', 'to continue to do something despite difficulties or opposition, in a way that can seem unreasonable', 'persist in doing something, Why do you persist in blaming yourself for what happened?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('persistent', 'adjective', 'pəˈsɪstənt', 'determined to do something despite difficulties, especially when other people are against you and think that you are being annoying or unreasonable', 'How do you deal with persistent salesmen who won''t take no for an answer?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('personnel', 'noun', 'ˌpɜːsəˈnel', 'the people who work for an organization or one of the armed forces', 'There is a severe shortage of skilled personnel.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('perspective', 'noun', 'pəˈspektɪv', 'a particular attitude towards something; a way of thinking about something', 'a global perspective', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('petition', 'noun', 'pəˈtɪʃn', 'a written document signed by a large number of people that asks somebody in a position of authority to do or change something', 'petition against something, Would you like to sign our petition against experiments on animals?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('phenomenon', 'noun', 'fəˈnɒmɪnən', 'a fact or an event in nature or society, especially one that is not fully understood', 'cultural/natural phenomena', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('philosopher', 'noun', 'fəˈlɒsəfə(r)', 'a person who studies or writes about philosophy', 'We studied the writings of the Greek philosopher Aristotle.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('philosophical', 'adjective', 'ˌfɪləˈsɒfɪkl', 'connected with philosophy', 'the philosophical writings of Kant', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('phone', 'noun, verb', 'fəʊn', 'a piece of equipment for talking to people who are not in the same place as you', 'I have to make a phone call.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('photo', 'noun', 'ˈfəʊtəʊ', 'a picture that is made by using a camera that stores images in digital form or that has a film sensitive to light inside it', 'a colour/black-and-white photo', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('photograph', 'noun, verb', 'ˈfəʊtəɡrɑːf', 'a picture that is made by using a camera that stores images in digital form or that has a film sensitive to light inside it', 'aerial photographs of the crash site ', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('physician', 'noun', 'fɪˈzɪʃn', 'a doctor, especially one who is a specialist in general medicine and not surgery', 'Dr Dennett is a practicing family physician in Atlanta.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pioneer', 'noun, verb', 'ˌpaɪəˈnɪə(r)', 'a person who is the first to study and develop a particular area of knowledge, culture, etc. that other people then continue to develop', 'a pioneer in the field of microsurgery', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pipeline', 'noun', 'ˈpaɪplaɪn', 'a series of pipes that are usually underground and are used for carrying oil, gas, etc. over long distances', 'There are plans to lay a gas pipeline through the region.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pirate', 'noun', 'ˈpaɪrət', '(especially in the past) a person on a ship who attacks other ships at sea in order to steal from them', 'There were reports that a pirate ship had come looking for treasure in the cove.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pit', 'noun', 'pɪt', 'a large deep hole in the ground', 'We dug a deep pit in the yard.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('placement', 'noun', 'ˈpleɪsmənt', 'the act of finding somebody a suitable job or place to live', 'a job placement service', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('plea', 'noun', 'pliː', 'a serious emotional request, especially for something needing action now', 'plea for something, She made an impassioned plea for help.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('plead', 'verb', 'pliːd', 'to ask somebody for something in a very strong and serious way', 'plead (with somebody) (to do something), She pleaded with him not to go.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pledge', 'noun, verb', 'pledʒ', 'a serious promise', 'pledge (of something), a pledge of support', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('plunge', 'verb', 'plʌndʒ', 'to move or make somebody/something move suddenly forwards and/or downwards', '+ adv./prep., She lost her balance and plunged 100 feet to her death.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('poet', 'noun', 'ˈpəʊɪt', 'a person who writes poems', 'an internationally renowned poet', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('policeman', 'noun', 'pəˈliːsmən', 'a male police officer', 'a plain-clothes/uniformed policeman', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('poll', 'noun', 'pəʊl', 'the process of questioning people who are representative of a larger group in order to get information about the general opinion', 'to carry out/conduct a poll', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pond', 'noun', 'pɒnd', 'a small area of still water, especially one that is artificial', 'a fish pond', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('popularity', 'noun', 'ˌpɒpjuˈlærəti', 'the state of being liked, enjoyed or supported by a large number of people', 'the increasing popularity of cycling', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('portfolio', 'noun', 'pɔːtˈfəʊliəʊ', 'a thin flat case used for carrying documents, drawings, etc.', 'I left my portfolio on the train.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('portion', 'noun', 'ˈpɔːʃn', 'one part of something larger', 'a substantial/significant portion of the population', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('portrait', 'noun', 'ˈpɔːtreɪt', 'a painting, drawing or photograph of a person, especially of the head and shoulders', 'portrait of somebody, a portrait of his wife ', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('portray', 'verb', 'pɔːˈtreɪ', 'to show somebody/something in a picture; to describe somebody/something in a piece of writing', 'The painting portrays the duke’s third wife.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('post-war', 'adjective', 'ˌpəʊst ˈwɔː(r)', 'existing, happening or made in the period after a war, especially the Second World War', 'the post-war years', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('poster', 'noun', 'ˈpəʊstə(r)', 'a large notice, often with a picture on it, that is put in a public place to advertise something', 'campaign/election posters', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('postpone', 'verb', 'pəˈspəʊn', 'to arrange for an event, etc. to take place at a later time or date than originally planned', 'postpone something, The game has already been postponed three times.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('poverty', 'noun', 'ˈpɒvəti', 'the state of being poor', 'conditions of extreme/abject poverty', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('practitioner', 'noun', 'prækˈtɪʃənə(r)', 'a person who works in a profession, especially medicine or law', 'dental practitioners', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pray', 'verb', 'preɪ', 'to speak to God, especially to give thanks or ask for help', 'They knelt down and prayed.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('preach', 'verb', 'priːtʃ', 'to give a religious talk in a public place, especially in a church during a service', 'She preached to the congregation about forgiveness.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('precede', 'verb', 'prɪˈsiːd', 'to happen before something or come before something/somebody in order', 'the years preceding the war', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('precedent', 'noun', 'ˈpresɪdənt', 'an official action or decision that has happened in the past and that is seen as an example or a rule to be followed in a similar situation later', 'The ruling set a precedent for future libel cases.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('precious', 'adjective', 'ˈpreʃəs', 'rare and worth a lot of money', 'a precious vase', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('precision', 'noun', 'prɪˈsɪʒn', 'the quality of being exact, accurate and careful', 'Her writing is imaginative but lacks precision.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('predator', 'noun', 'ˈpredətə(r)', 'an animal that kills and eats other animals', 'Some animals have no natural predators.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('predecessor', 'noun', 'ˈpriːdəsesə(r)', 'a person who did a job before somebody else', 'The new president reversed many of the policies of his predecessor.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('predictable', 'adjective', 'prɪˈdɪktəbl', 'if something is predictable, you know in advance that it will happen or what it will be like', 'a predictable result', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prediction', 'noun', 'prɪˈdɪkʃn', 'a statement that says what you think will happen; the act of making such a statement', 'The results of the experiment confirmed our predictions.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('predominantly', 'adverb', 'prɪˈdɒmɪnəntli', 'mostly; mainly', 'She works in a predominantly male environment.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pregnancy', 'noun', 'ˈpreɡnənsi', 'the state of being pregnant', 'a pregnancy test', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prejudice', 'noun', 'ˈpredʒədɪs', 'an unreasonable dislike of or preference for a person, group, custom, etc., especially when it is based on their race, religion, sex, etc.', 'a victim of racial prejudice', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('preliminary', 'adjective', 'prɪˈlɪmɪnəri', 'happening before a more important action or event', 'After a few preliminary remarks he announced the winners.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('premier', 'adjective', 'ˈpremiə(r)', 'most important, famous or successful', 'one of the country’s premier chefs', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('premise', 'noun', 'ˈpremɪs', 'a statement or an idea that forms the basis for a reasonable line of argument', 'the basic premise of her argument', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('premium', 'noun', 'ˈpriːmiəm', 'an amount of money that you pay once or regularly for an insurance policy', 'a monthly premium of £6.25', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prescribe', 'verb', 'prɪˈskraɪb', 'to tell somebody to take a particular medicine or have a particular treatment; to write a prescription for a particular medicine, etc.', 'prescribe something, Valium is usually prescribed to treat anxiety.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prescription', 'noun', 'prɪˈskrɪpʃn', 'an official piece of paper on which a doctor writes the type of medicine you should have, and which enables you to get it from a chemist''s ', 'prescription for something, The doctor gave me a prescription for antibiotics.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('presently', 'adverb', 'ˈprezntli', 'at the time you are speaking or writing; now', 'The crime is presently being investigated by the police.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('preservation', 'noun', 'ˌprezəˈveɪʃn', 'the act of keeping something in its original state or in good condition', 'building/environmental/food preservation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('preside', 'verb', 'prɪˈzaɪd', 'to lead or be in charge of a meeting, ceremony, etc.', 'the presiding judge', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('presidency', 'noun', 'ˈprezɪdənsi', 'the job of being president of a country or an organization; the period of time somebody holds this job', 'the current holder of the EU presidency', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('presidential', 'adjective', 'ˌprezɪˈdenʃl', 'connected with the position or activities of a president', 'a presidential campaign/candidate/election', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prestigious', 'adjective', 'preˈstɪdʒəs', 'respected and admired as very important or of very high quality', 'a prestigious award', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('presume', 'verb', 'prɪˈzjuːm', 'to suppose that something is true, although you do not have actual proof', 'They are very expensive, I presume?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prevail', 'verb', 'prɪˈveɪl', 'to exist or be very common at a particular time or in a particular place', 'prevail in something, We were horrified at the conditions prevailing in local prisons.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prevalence', 'noun', 'ˈprevələns', 'the fact of existing or being very common at a particular time or in a particular place', 'an increase in the prevalence of smoking among young people', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prevention', 'noun', 'prɪˈvenʃn', 'the act of stopping something bad from happening', 'accident/crime prevention', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prey', 'noun', 'preɪ', 'an animal, a bird, etc. that is hunted, killed and eaten by another', 'The lion will often stalk its prey for hours.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prime', 'adjective', 'praɪm', 'main; most important; basic', 'My prime concern is to protect my property.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('principal', 'adjective, noun', 'ˈprɪnsəpl', 'most important; main', 'The principal reason for this omission is lack of time.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('privacy', 'noun', 'ˈprɪvəsi', 'the state of being alone and not watched or interrupted by other people', 'She was longing for some peace and privacy.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('privatization', 'noun', 'ˌpraɪvətaɪˈzeɪʃn', 'the act of selling a business or an industry so that it is no longer owned by the government', 'There were fears that privatization would lead to job losses.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('privilege', 'noun', 'ˈprɪvəlɪdʒ', 'a special right or advantage that a particular person or group of people has', 'Education should be a universal right and not a privilege.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('probability', 'noun', 'ˌprɒbəˈbɪləti', 'how likely something is to happen', 'The probability is that prices will rise rapidly.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('probe', 'noun, verb', 'prəʊb', 'a complete and careful investigation of something', 'a police probe into the financial affairs of the company', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('problematic', 'adjective', 'ˌprɒbləˈmætɪk', 'difficult to deal with or to understand; full of problems; not certain to be successful', 'The situation is more problematic than we first thought.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('proceeding', 'noun', 'prəˈsiːdɪŋ', 'the process of using a court to settle an argument or to deal with a complaint', 'court/legal/judicial proceedings', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('proceeds', 'noun', 'ˈprəʊsiːdz', 'the money that you receive when you sell something or organize a performance, etc.; profits', 'She sold her car and bought a piano with the proceeds.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('processing', 'noun', 'ˈprəʊsesɪŋ', 'the treatment of raw material, food, etc. in order to change it, preserve it, etc.', 'the food processing industry', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('processor', 'noun', 'ˈprəʊsesə(r)', 'a machine, person or company that processes things', 'The company is Ireland''s largest dairy processor.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('proclaim', 'verb', 'prəˈkleɪm', 'to publicly and officially tell people about something important', 'proclaim something, The president proclaimed a state of emergency.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('productive', 'adjective', 'prəˈdʌktɪv', 'making goods or growing crops, especially in large quantities', 'highly productive farming land', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('productivity', 'noun', 'ˌprɒdʌkˈtɪvəti', 'the rate at which a worker, a company or a country produces goods, and the amount produced, compared with how much time, work and money is needed to produce them', 'high/improved/increased productivity', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('profile', 'noun', 'ˈprəʊfaɪl', 'a description of somebody/something that gives useful information', 'We first build up a detailed profile of our customers and their requirements.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('profitable', 'adjective', 'ˈprɒfɪtəbl', 'that makes or is likely to make money', 'a highly profitable business', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('profound', 'adjective', 'prəˈfaʊnd', 'very great; felt or experienced very strongly', 'profound changes in the earth’s climate', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('programming', 'noun', 'ˈprəʊɡræmɪŋ', 'the process of writing and testing computer programs', 'programming languages', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('progressive', 'adjective', 'prəˈɡresɪv', 'in favour of new ideas, modern methods and change', 'progressive schools', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prohibit', 'verb', 'prəˈhɪbɪt', 'to stop something from being done or used especially by law', 'prohibit something, a law prohibiting the sale of alcohol', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('projection', 'noun', 'prəˈdʒekʃn', 'an estimate or a statement of what figures, amounts, or events will be in the future, or what they were in the past, based on what is happening now', 'to make forward/backward projections of population figures', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prominent', 'adjective', 'ˈprɒmɪnənt', 'important or well known', 'a prominent politician', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('promising', 'adjective', 'ˈprɒmɪsɪŋ', 'showing signs of being good or successful', 'He was voted the most promising new actor for his part in the movie.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pronounced', 'adjective', 'prəˈnaʊnst', 'very obvious, easy to notice or strongly expressed', 'He walked with a pronounced limp.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('propaganda', 'noun', 'ˌprɒpəˈɡændə', 'ideas or statements that may be false or present only one side of an argument that are used in order to gain support for a political leader, party, etc.', 'enemy propaganda', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('proposition', 'noun', 'ˌprɒpəˈzɪʃn', 'an idea or a plan of action that is suggested, especially in business', 'I''d like to put a business proposition to you.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prosecute', 'verb', 'ˈprɒsɪkjuːt', 'to officially charge somebody with a crime in court', 'The police decided not to prosecute.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prosecution', 'noun', 'ˌprɒsɪˈkjuːʃn', 'the process of trying to prove in court that somebody is guilty of a crime (= of prosecuting them); the process of being officially charged with a crime in court', 'Prosecution for a first minor offence rarely leads to imprisonment.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prosecutor', 'noun', 'ˈprɒsɪkjuːtə(r)', 'a public official who charges somebody officially with a crime and prosecutes them in court', 'the public/state prosecutor', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prospective', 'adjective', 'prəˈspektɪv', 'expected to do something or to become something', 'a prospective buyer', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('prosperity', 'noun', 'prɒˈsperəti', 'the state of being successful, especially in making money', 'Our future prosperity depends on economic growth.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('protective', 'adjective', 'prəˈtektɪv', 'providing or intended to provide protection', 'Workers should wear full protective clothing.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('protein', 'noun', 'ˈprəʊtiːn', 'a substance, found within all living things, that forms the structure of muscles, organs, etc. There are many different proteins and they are an essential part of what humans and animals eat to help them grow and stay healthy.', 'essential proteins and vitamins', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('protester', 'noun', 'prəˈtestə(r)', 'a person who makes a public protest', 'Thousands of protesters marched through the city.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('protocol', 'noun', 'ˈprəʊtəkɒl', 'a system of fixed rules and formal behaviour used at official meetings, usually between governments', 'a breach of protocol', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('province', 'noun', 'ˈprɒvɪns', 'one of the areas that some countries are divided into with its own local government', 'the provinces of Canada', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('provincial', 'adjective', 'prəˈvɪnʃl', 'connected with one of the large areas that some countries are divided into, with its own local government', 'provincial assemblies/elections', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('provision', 'noun', 'prəˈvɪʒn', 'the act of supplying somebody with something that they need or want; something that is supplied', 'housing provision', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('provoke', 'verb', 'prəˈvəʊk', 'to cause a particular reaction or have a particular effect', 'The announcement provoked a storm of protest.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('psychiatric', 'adjective', 'ˌsaɪkiˈætrɪk', 'relating to psychiatry or to mental illnesses', 'psychiatric disorders', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('psychological', 'adjective', 'ˌsaɪkəˈlɒdʒɪkl', 'connected with a person’s mind and the way in which it works', 'the psychological development of children', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('psychologist', 'noun', 'saɪˈkɒlədʒɪst', 'a scientist who studies and is trained in psychology', 'to see a psychologist', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('psychology', 'noun', 'saɪˈkɒlədʒi', 'the scientific study of the mind and how it influences behaviour', 'clinical/educational/child/sport psychology', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pub', 'noun', 'pʌb', 'a building where people go to drink and meet their friends. Pubs serve alcoholic and other drinks, and often also food.', 'We''re all going to the pub after work.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pulse', 'noun', 'pʌls', 'the regular beat of the heart as it sends blood around the body, that can be felt in different places, especially on the inside part of the wrist; the number of times the heart beats in a minute', 'a strong/weak pulse', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pump', 'noun, verb', 'pʌmp', 'a machine that is used to force liquid, gas or air into or out of something', '(British English), a petrol pump', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('punk', 'noun', 'pʌŋk', 'a type of loud and aggressive rock music popular in the late 1970s and early 1980s', 'a punk band', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('pursuit', 'noun', 'pəˈsjuːt', 'the act of looking for or trying to get something', 'pursuit of something, the pursuit of happiness/knowledge/profit', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('puzzle', 'noun', 'ˈpʌzl', 'a game, etc. that you have to think about carefully in order to answer it or do it', 'a crossword puzzle', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('query', 'noun', 'ˈkwɪəri', 'a question, especially one asking for information or expressing a doubt about something', 'Our assistants will be happy to answer your queries.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('quest', 'noun', 'kwest', 'a long search for something, especially for some quality such as happiness', 'quest for something, the quest for happiness/knowledge/truth', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('questionnaire', 'noun', 'ˌkwestʃəˈneə(r)', 'a written list of questions that are answered by a number of people so that information can be collected from the answers', '(British English), to fill in a questionnaire', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('queue', 'noun, verb', 'kjuː', 'a line of people, cars, etc. waiting for something or to do something', 'There were long queues at polling stations.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('quota', 'noun', 'ˈkwəʊtə', 'a limited number or amount of people or things that is officially allowed', 'to introduce a strict import quota on grain', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('quotation', 'noun', 'kwəʊˈteɪʃn', 'a group of words or a short piece of writing taken from a book, play, speech, etc. and repeated because it is interesting or useful', 'a dictionary of quotations', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('racial', 'adjective', 'ˈreɪʃl', 'happening or existing between people of different races', 'racial hatred/prejudice/tension/violence', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('racism', 'noun', 'ˈreɪsɪzəm', 'the unfair treatment of people who belong to a different race; violent behaviour towards them', 'a victim of racism', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('racist', 'adjective, noun', 'ˈreɪsɪst', 'having the belief that some races of people are better than others or having general beliefs about other people based only on their race; showing this through violent or unfair treatment of people of other races', 'racist attitudes/remarks', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('radar', 'noun', 'ˈreɪdɑː(r)', 'a system that uses radio waves to find the position and movement of objects, for example planes and ships, when they cannot be seen', 'They located the ship by radar.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('radiation', 'noun', 'ˌreɪdiˈeɪʃn', 'powerful and very dangerous rays that are sent out from radioactive substances', 'high levels/doses of radiation that damage cells', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('radical', 'adjective', 'ˈrædɪkl', 'relating to the most basic and important parts of something; complete and detailed', 'the need for radical changes in education', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rage', 'noun', 'reɪdʒ', 'a feeling of violent anger that is difficult to control', 'His face was dark with rage.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('raid', 'noun, verb', 'reɪd', 'a short surprise attack on an enemy by soldiers, ships or aircraft', 'to conduct/launch a raid', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rally', 'noun, verb', 'ˈræli', 'a large public meeting, especially one held to support a particular idea or political party', 'to attend/hold a rally', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('random', 'adjective', 'ˈrændəm', 'done, chosen, etc. without somebody deciding in advance what is going to happen, or without any regular pattern', 'the random killing of innocent people', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ranking', 'noun', 'ˈræŋkɪŋ', 'the position of somebody/something on a scale that shows how good or important they are in relation to other similar people or things, especially in sport', 'He has improved his ranking this season from 67th to 30th.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rape', 'noun, verb', 'reɪp', 'the crime of forcing somebody to have sex when they do not want it or are not able to agree to it', 'He was charged with rape.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rat', 'noun', 'ræt', 'a small animal with a long tail, that looks like a large mouse, usually considered a pest (= an animal which is disliked because it destroys food or spreads disease)', 'rat poison', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rating', 'noun', 'ˈreɪtɪŋ', 'a measurement of how good, popular, important, etc. somebody/something is, especially in relation to other people or things', 'The poll gave an approval rating of 39 per cent for the president.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ratio', 'noun', 'ˈreɪʃiəʊ', 'the relationship between two groups of people or things that is represented by two numbers showing how much larger one group is than the other', 'The school has a very high teacher-student ratio.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rational', 'adjective', 'ˈræʃnəl', 'based on reason rather than emotions', 'a rational argument/choice/decision', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ray', 'noun', 'reɪ', 'a narrow line of light, heat or other energy', 'The last of the sun''s rays shone on the grass.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('readily', 'adverb', 'ˈredɪli', 'quickly and without difficulty', 'All ingredients are readily available from your local store.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('realization', 'noun', 'ˌriːəlaɪˈzeɪʃn', 'the process of becoming aware of something', 'As realization dawned, he went pale.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('realm', 'noun', 'relm', 'an area of activity, interest or knowledge', 'in the realm of something, in the realm of literature', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reasoning', 'noun', 'ˈriːzənɪŋ', 'the process of thinking about things in a logical way; opinions and ideas that are based on logical thinking', 'What is the reasoning behind this decision?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reassure', 'verb', 'ˌriːəˈʃʊə(r)', 'to say or do something that makes somebody less frightened or worried', 'reassure somebody (about something), They tried to reassure her, but she still felt anxious.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rebel', 'noun', 'ˈrebl', 'a person who fights against the government of their country', 'rebel forces', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rebellion', 'noun', 'rɪˈbeljən', 'an attempt by some of the people in a country to change their government, using violence', 'in rebellion (against somebody/something), The north of the country rose in rebellion against the government.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rebuild', 'verb', 'ˌriːˈbɪld', 'to build or put something together again', 'After the earthquake, the people set about rebuilding their homes.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('receiver', 'noun', 'rɪˈsiːvə(r)', 'the part of a phone that you hold close to your mouth and ear', 'to pick up/lift/put down/replace the receiver', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recession', 'noun', 'rɪˈseʃn', 'a difficult time for the economy of a country, when there is less trade and industrial activity than usual and more people are unemployed', 'How do you assess the impact of the current recession on manufacturing?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recipe', 'noun', 'ˈresəpi', 'a set of instructions that tells you how to cook something and the ingredients (= items of food) you need for it', 'recipe for something, a recipe for chicken soup', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recipient', 'noun', 'rɪˈsɪpiənt', 'a person who receives something', 'recipients of awards', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recommendation', 'noun', 'ˌrekəmenˈdeɪʃn', 'an official suggestion about the best thing to do', 'to accept/reject a recommendation', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reconstruction', 'noun', 'ˌriːkənˈstrʌkʃn', 'the process of changing or improving the condition of something or the way it works; the process of putting something back into the state it was in before', 'the reconstruction of the educational system', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recount', 'verb', NULL, 'sound or pictures that have been recorded on computer files or on CD, DVD, video, etc.', 'an audio recording', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recovery', 'noun', 'rɪˈkʌvəri', 'the process of becoming well again after an illness or injury', 'My father has made a full recovery from the operation.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recruit', 'noun, verb', 'rɪˈkruːt', 'a person who has recently joined the armed forces or the police', 'the training of new recruits', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recruitment', 'noun', 'rɪˈkruːtmənt', 'the act or process of finding new people to join a company, an organization, the armed forces, etc.', 'the recruitment of new members', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('recycle', 'verb', 'ˌriːˈsaɪkl', 'to treat things that have already been used so that they can be used again', 'to recycle waste/rubbish', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('refer', 'verb', 'rɪˈfɜː(r)', 'to send somebody/something to somebody/something for help, advice or a decision', 'refer somebody/something to somebody/something, My doctor referred me to a specialist.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('referee', 'noun', 'ˌrefəˈriː', 'the official who controls the game in some sports', 'He was sent off for arguing with the referee.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('referendum', 'noun', 'ˌrefəˈrendəm', 'an occasion when all the people of a country can vote on an important issue', 'referendum on something, Switzerland decided to hold a referendum on joining the EU.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reflection', 'noun', 'rɪˈflekʃn', 'an image in a mirror, on a shiny surface, on water, etc.', 'He admired his reflection in the mirror.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('refuge', 'noun', 'ˈrefjuːdʒ', 'shelter or protection from danger, trouble, etc.', 'A further 300 people have taken refuge in the US embassy.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('refugee', 'noun', 'ˌrefjuˈdʒiː', 'a person who has been forced to leave their country or home, because there is a war or for political, religious or social reasons', 'There has been a steady flow of refugees from the war zone.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('regain', 'verb', 'rɪˈɡeɪn', 'to get back something you no longer have, especially an ability or a quality', 'I struggled to regain some dignity.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('regardless', 'adverb', 'rɪˈɡɑːdləs', 'paying no attention, even if the situation is bad or there are difficulties', 'The weather was terrible but we carried on regardless.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('regime', 'noun', 'reɪˈʒiːm', 'a method or system of government, especially one that has not been elected in a fair way', 'a fascist/totalitarian/military, etc. regime', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('registration', 'noun', 'ˌredʒɪˈstreɪʃn', 'the act of making an official record of something/somebody', 'the registration of letters and parcels', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('regulate', 'verb', 'ˈreɡjuleɪt', 'to control something by means of rules', 'The department is responsible for regulating the insurance industry.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('regulator', 'noun', 'ˈreɡjuleɪtə(r)', 'a person or an organization that officially controls an area of business or industry and makes sure that it is operating fairly', 'Ofgas, the gas industry regulator', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('regulatory', 'adjective', 'ˈreɡjələtəri', 'having the power to control an area of business or industry and make sure that it is operating fairly', 'regulatory bodies/authorities/agencies', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rehabilitation', 'noun', 'ˌriːəˌbɪlɪˈteɪʃn', 'the process of helping somebody to return to a normal, healthy life after they have been in prison or very ill', 'a drug rehabilitation centre', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reign', 'noun, verb', 'reɪn', 'the period during which a king, queen, emperor, etc. rules', 'By the end of his reign, the vast empire was in decline.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reinforce', 'verb', 'ˌriːɪnˈfɔːs', 'to make a feeling, an idea, etc. stronger', 'The experience reinforced my sense of loss.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rejection', 'noun', 'rɪˈdʒekʃn', 'the act of refusing to accept or consider something', 'Her proposal met with unanimous rejection.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('relevance', 'noun', 'ˈreləvəns', 'a close connection with the subject you are discussing or the situation you are in', 'I don''t see the relevance of your question.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reliability', 'noun', 'rɪˌlaɪəˈbɪləti', 'the quality of being able to be trusted to do what somebody wants or needs', 'The incident cast doubt on her motives and reliability.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reliable', 'adjective', 'rɪˈlaɪəbl', 'that can be trusted to do something well; that you can rely on', 'We are looking for someone who is reliable and hard-working.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('relieve', 'verb', 'rɪˈliːv', 'to remove or reduce an unpleasant feeling or pain', 'to relieve the symptoms of a cold', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('relieved', 'adjective', 'rɪˈliːvd', 'feeling happy because something unpleasant has stopped or has not happened; showing this', 'She sounded relieved.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reluctant', 'adjective', 'rɪˈlʌktənt', 'hesitating before doing something because you do not want to do it or because you are not sure that it is the right thing to do', 'He finally gave a reluctant smile.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rely', 'verb', 'rɪˈlaɪ', '', NULL, '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('remainder', 'noun', 'rɪˈmeɪndə(r)', 'the people, things or time that remain', 'I kept some of his books and gave away the remainder.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('remedy', 'noun', 'ˈremədi', 'a way of dealing with or improving an unpleasant or difficult situation', 'When the reservoir becomes blocked, the only remedy lies in cleaning the entire system.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reminder', 'noun', 'rɪˈmaɪndə(r)', 'something that makes you think about or remember somebody/something, that you have forgotten or would like to forget', 'reminder of something, The sheer size of the cathedral is a constant reminder of the power of religion.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('render', 'verb', 'ˈrendə(r)', 'to cause somebody/something to be in a particular state or condition', 'to render something harmless/useless/ineffective', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('renew', 'verb', 'rɪˈnjuː', 'to begin something again after it stopped or was interrupted', 'The army renewed its assault on the capital.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('renowned', 'adjective', 'rɪˈnaʊnd', 'famous and respected', 'a renowned author', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rental', 'noun', 'ˈrentl', 'the amount of money that you pay to use something for a particular period of time', 'Telephone charges include line rental.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('replacement', 'noun', 'rɪˈpleɪsmənt', 'the act of replacing one thing with another, especially something that is newer or better', 'the replacement of worn car parts', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reportedly', 'adverb', 'rɪˈpɔːtɪdli', 'according to what some people say', 'The band have reportedly decided to split up.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reporter', 'noun', 'rɪˈpɔːtə(r)', 'a person who collects and reports news for newspapers, radio or television', 'He leaked the story to a news reporter.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reporting', 'noun', 'rɪˈpɔːtɪŋ', 'the presenting of and writing about news on television and radio, and in newspapers', 'accurate/balanced/objective reporting', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('representation', 'noun', 'ˌreprɪzenˈteɪʃn', 'the act of presenting somebody/something in a particular way; something that shows or describes something', 'the negative representation of single mothers in the media', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reproduction', 'noun', 'ˌriːprəˈdʌkʃn', 'the act or process of producing babies, young animals or plants', 'sexual reproduction', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('republic', 'noun', 'rɪˈpʌblɪk', 'a country that is governed by a president and politicians elected by the people and where there is no king or queen', 'newly independent republics', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('researcher', 'noun', 'rɪˈsɜːtʃə(r)', 'a person who studies something carefully and tries to discover new facts about it', 'European researchers say olive oil could help prevent cancer.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('resemble', 'verb', 'rɪˈzembl', 'to look like or be similar to another person or thing', 'She closely resembles her sister.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('reside', 'verb', 'rɪˈzaɪd', 'to live in a particular place', 'He returned to Britain in 1939, having resided abroad for many years.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('residence', 'noun', 'ˈrezɪdəns', 'a house, especially a large or impressive one', 'a desirable family residence for sale (= for example, in an advertisement)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('residential', 'adjective', 'ˌrezɪˈdenʃl', 'suitable for living in; consisting of houses rather than factories or offices', 'a quiet residential area', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('residue', 'noun', 'ˈrezɪdjuː', 'a small amount of something that remains at the end of a process', 'pesticide residues in fruit and vegetables', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('resign', 'verb', 'rɪˈzaɪn', 'to officially tell somebody that you are leaving your job, an organization, etc.', 'She was forced to resign due to ill health.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('resignation', 'noun', 'ˌrezɪɡˈneɪʃn', 'the act of giving up your job or position; the occasion when you do this', 'a letter of resignation', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('resolution', 'noun', 'ˌrezəˈluːʃn', 'a definite decision to do or not to do something', 'Have you made any New Year''s resolutions (= for example, to give up smoking from 1 January)?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('respective', 'adjective', 'rɪˈspektɪv', 'belonging or relating separately to each of the people or things already mentioned', 'They are each recognized specialists in their respective fields.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('respectively', 'adverb', 'rɪˈspektɪvli', 'in the same order as the people or things already mentioned', 'Julie and Mark, aged 17 and 19 respectively', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('restoration', 'noun', 'ˌrestəˈreɪʃn', 'the work of repairing and cleaning an old building, a painting, etc. so that its condition is as good as it originally was', 'restoration work', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('restraint', 'noun', 'rɪˈstreɪnt', 'a rule, a fact, an idea, etc. that limits or controls what people can do', 'The government has imposed export restraints on some products.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('resume', 'verb', 'rɪˈzjuːm', 'if you resume an activity, or if it resumes, it begins again or continues after being interrupted', 'resume (something), to resume talks/negotiations', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('retail', 'noun', 'ˈriːteɪl', 'the selling of goods to the public, usually through shops', 'The recommended retail price is £9.99.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('retreat', 'noun, verb', 'rɪˈtriːt', 'a movement away from a place or an enemy because of danger or defeat', 'Napoleon’s retreat from Moscow', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('retrieve', 'verb', 'rɪˈtriːv', 'to bring or get something back, especially from a place where it should not be', 'retrieve something from somebody/something, She bent to retrieve her comb from the floor.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('revelation', 'noun', 'ˌrevəˈleɪʃn', 'a fact that people are made aware of, especially one that has been secret and is surprising', 'revelation about/concerning something, startling/sensational revelations about her private life', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('revenge', 'noun', 'rɪˈvendʒ', 'something that you do in order to make somebody suffer because they have made you suffer', 'revenge for something, She is seeking revenge for the murder of her husband.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('revenue', 'noun', 'ˈrevənjuː', 'the money that a government receives from taxes or that an organization, etc. receives from its business', 'The government is currently facing a shortfall in tax revenue.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('revival', 'noun', 'rɪˈvaɪvl', 'an improvement in the condition or strength of something', 'the revival of trade', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('revive', 'verb', 'rɪˈvaɪv', 'to become, or to make somebody/something become, conscious or healthy and strong again', 'The flowers soon revived in water.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('revolutionary', 'adjective', 'ˌrevəˈluːʃənəri', 'connected with political revolution', 'a revolutionary leader', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rhetoric', 'noun', 'ˈretərɪk', 'speech or writing that is intended to influence people, but that is not completely honest or sincere', 'the rhetoric of political slogans', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rifle', 'noun', 'ˈraɪfl', 'a gun with a long barrel which you hold to your shoulder to fire', 'a hunting rifle', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('riot', 'noun', 'ˈraɪət', 'a situation in which a group of people behave in a violent way in a public place, often as a protest', 'One prison guard was killed when a riot broke out in the jail.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rip', 'verb', 'rɪp', 'to tear something or to become torn, often suddenly or violently', 'rip (something), I ripped my jeans on the fence.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('risky', 'adjective', 'ˈrɪski', 'involving the possibility of something bad happening', 'Life as an aid worker can be a risky business (= dangerous).', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ritual', 'noun', 'ˈrɪtʃuəl', 'a series of actions that are always performed in the same way, especially as part of a religious ceremony', 'religious rituals', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('robbery', 'noun', 'ˈrɒbəri', 'the crime of stealing money or goods from a bank, shop, person, etc., especially using violence or threats', 'armed robbery (= using a gun, knife, etc.)', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('robot', 'noun', 'ˈrəʊbɒt', 'a machine that can perform a complicated series of tasks by itself', 'These cars are built by robots.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('robust', 'adjective', 'rəʊˈbʌst', 'strong and healthy', 'She was almost 90, but still very robust.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rocket', 'noun', 'ˈrɒkɪt', 'a spacecraft in the shape of a tube that is driven by a stream of gases let out behind it when fuel is burned inside', 'a space rocket', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rod', 'noun', 'rɒd', 'a long straight piece of wood, metal or glass', 'The concrete is reinforced with steel rods.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('romance', 'noun', 'rəʊˈmæns', 'an exciting, usually short, relationship between two people who are in love with each other', 'a holiday romance', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rose', 'noun', 'rəʊz', 'a flower with a sweet smell that grows on a bush with thorns (= sharp points) on its stems', 'a bunch of red roses', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rotate', 'verb', 'rəʊˈteɪt', 'to move or turn around a central fixed point; to make something do this', 'Stay well away from the helicopter when its blades start to rotate.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rotation', 'noun', 'rəʊˈteɪʃn', 'the action of an object moving in a circle around a central fixed point', 'the daily rotation of the earth on its axis', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('rugby', 'noun', 'ˈrʌɡbi', 'a game played by two teams of 13 or 15 players, using an oval ball which may be kicked or carried. Teams try to put the ball over the other team’s line.', 'to play a game of rugby', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ruling', 'noun', 'ˈruːlɪŋ', 'an official decision made by somebody in a position of authority, especially a judge', 'The court will make its ruling on the case next week.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sacred', 'adjective', 'ˈseɪkrɪd', 'connected with God or a god; considered to be holy', 'a sacred image/shrine/temple', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sacrifice', 'noun, verb', 'ˈsækrɪfaɪs', 'the fact of giving up something important or valuable to you in order to get or do something that seems more important; something that you give up in this way', 'The makers of the product assured us that there had been no sacrifice of quality.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('saint', 'noun', 'seɪnt', 'a person that the Christian Church recognizes as being very holy, because of the way they have lived or died', 'St John', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sake', 'noun', 'seɪk', '', NULL, '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sanction', 'noun', 'ˈsæŋkʃn', 'an official order that limits trade, contact, etc. with a particular country, in order to make it do something, such as obeying international law', 'Trade sanctions were imposed against any country that refused to sign the agreement.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sandwich', 'noun', 'ˈsænwɪtʃ', 'two slices of bread, often spread with butter, with a layer of meat, cheese, etc. between them', 'a ham/tuna/egg sandwich', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('satellite', 'noun', 'ˈsætəlaɪt', 'an electronic device that is sent into space and moves around the earth or another planet. It is used for communicating by radio, television, etc. and for gathering information.', 'a weather/communications/spy satellite ', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('Saturday', 'noun', 'ˈsætədeɪ', 'the day of the week after Friday and before Sunday', 'It''s Saturday today, isn''t it?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scan', 'verb', 'skæn', 'to look quickly but not very carefully at a document, etc.', 'scan something for something, I scanned the list quickly for my name.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scandal', 'noun', 'ˈskændl', 'behaviour or an event that people think is morally or legally wrong and causes public feelings of shock or anger', 'a series of sex scandals', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scary', 'adjective', 'ˈskeəri', 'frightening', 'It was a really scary moment.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scattered', 'adjective', 'ˈskætəd', 'spread far apart over a wide area or over a long period of time', 'a few scattered settlements', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scenario', 'noun', 'səˈnɑːriəʊ', 'a description of how things might happen in the future', 'Let me suggest a possible scenario.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sceptical', 'adjective', 'ˈskeptɪkl', 'having doubts that a claim or statement is true or that something will happen', 'She looked highly sceptical.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scholar', 'noun', 'ˈskɒlə(r)', 'a person who knows a lot about a particular subject because they have studied it in detail', 'a classical scholar', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scholarship', 'noun', 'ˈskɒləʃɪp', 'an amount of money given to somebody by an organization to help pay for their education', 'She won a scholarship to study at Stanford.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scope', 'noun', 'skəʊp', 'the opportunity or ability to do or achieve something', 'scope for something, There''s still plenty of scope for improvement.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('screening', 'noun', 'ˈskriːnɪŋ', 'the act of showing a film or television programme', 'This will be the movie''s first screening in this country.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('script', 'noun', 'skrɪpt', 'a written text of a play, film, broadcast, talk, etc.', 'That line isn''t in the original script.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('scrutiny', 'noun', 'ˈskruːtəni', 'careful and complete examination', 'Her argument doesn''t really stand up to scrutiny.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sculpture', 'noun', 'ˈskʌlptʃə(r)', 'a work of art that is a solid figure or object made by carving or shaping wood, stone, clay, metal, etc.', 'a marble sculpture of Venus', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('secondly', 'adverb', 'ˈsekəndli', 'used to introduce the second of a list of points you want to make in a speech or piece of writing', 'Firstly, it''s expensive, and secondly, it''s too slow.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('secular', 'adjective', 'ˈsekjələ(r)', 'not connected with spiritual or religious matters', 'secular music', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seeker', 'noun', 'ˈsiːkə(r)', 'a person who is trying to find or get the thing mentioned', 'an attention/a publicity seeker', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seem', 'linking verb', 'siːm', 'to give the impression of being or doing something', '+ adj., You seem happy.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seemingly', 'adverb', 'ˈsiːmɪŋli', 'in a way that appears to be true but may in fact not be', 'a seemingly stupid question', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('segment', 'noun', 'ˈseɡmənt', 'a part of something that is separate from the other parts or can be considered separately', 'She cleaned a small segment of the painting.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seize', 'verb', 'siːz', 'to take somebody/something in your hand suddenly and using force', 'seize something from somebody, She tried to seize the gun from him.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seldom', 'adverb', 'ˈseldəm', 'not often', 'He had seldom seen a child with so much talent.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('selective', 'adjective', 'sɪˈlektɪv', 'affecting or involving only a small number of people or things from a larger group', 'the selective breeding of cattle', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seminar', 'noun', 'ˈsemɪnɑː(r)', 'a class at a university or college when a small group of students and a teacher discuss or study a particular topic', 'Teaching is by lectures and seminars.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sensation', 'noun', 'senˈseɪʃn', 'a feeling that you get when something affects your body', 'a tingling/burning sensation ', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sensitivity', 'noun', 'ˌsensəˈtɪvəti', 'the ability to understand other people’s feelings', 'sensitivity to the needs of children', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sentiment', 'noun', 'ˈsentɪmənt', 'a feeling or an opinion, especially one based on emotions', 'the spread of nationalist sentiments', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sequence', 'noun', 'ˈsiːkwəns', 'a set of events, actions, numbers, etc. which have a particular order and which lead to a particular result', 'He described the sequence of events leading up to the robbery.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('serial', 'adjective', 'ˈsɪəriəl', 'doing the same thing in the same way several times; done in the same way several times', 'a serial rapist', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('set-up', 'noun', 'ˈset ʌp', 'a way of organizing something; a system', 'I''ve only been here a couple of weeks and I don''t really know the set-up.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('setting', 'noun', 'ˈsetɪŋ', 'an environment where something is located; the place at which something happens', 'a rural/an ideal/a beautiful/an idyllic setting', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('settlement', 'noun', 'ˈsetlmənt', 'an official agreement that ends an argument between two people or groups', 'to negotiate a peace settlement', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('settler', 'noun', 'ˈsetlə(r)', 'a person who goes to live in a new country or region', 'Most of the settlers came from England.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seven', 'number', 'ˈsevn', '7', 'There are seven cookies left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seventeen', 'number', 'ˌsevnˈtiːn', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('seventy', 'number', 'ˈsevnti', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sexuality', 'noun', 'ˌsekʃuˈæləti', 'the feelings and activities connected with a person’s sexual desires', 'He was confused about his sexuality.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sexy', 'adjective', 'ˈseksi', 'sexually attractive', 'the sexy lead singer', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shareholder', 'noun', 'ˈʃeəhəʊldə(r)', 'an owner of shares in a company or business', 'the major shareholders in the company', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shatter', 'verb', 'ˈʃætə(r)', 'to suddenly break into small pieces; to make something suddenly break into small pieces', 'shatter (into something), He dropped the vase and it shattered into pieces on the floor.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shed', 'verb', 'ʃed', 'to get rid of something that is no longer wanted', 'The factory is shedding a large number of jobs.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sheer', 'adjective', 'ʃɪə(r)', 'used to emphasize the size, degree or amount of something', 'The area is under threat from the sheer number of tourists using it.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shipping', 'noun', 'ˈʃɪpɪŋ', 'ships in general or considered as a group', 'The canal is open to shipping.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shore', 'noun', 'ʃɔː(r)', 'the land along the edge of the sea, the ocean or a lake', 'a rocky/sandy shore', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('short-term', 'adjective', 'ˌʃɔːt ˈtɜːm', 'lasting a short time; designed only for a short period of time in the future', 'a short-term loan', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shortage', 'noun', 'ˈʃɔːtɪdʒ', 'a situation when there is not enough of the people or things that are needed', 'food/housing/water shortages', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shrink', 'verb', 'ʃrɪŋk', 'to become smaller, especially when washed in water that is too hot; to make clothes, cloth, etc. smaller in this way', 'My sweater shrank in the wash.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('shrug', 'verb', 'ʃrʌɡ', 'to raise your shoulders and then drop them to show that you do not know or care about something', 'Sam shrugged and said nothing.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sibling', 'noun', 'ˈsɪblɪŋ', 'a brother or sister', 'squabbles between siblings', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sigh', 'noun, verb', 'saɪ', 'an act or the sound of sighing', 'to give/heave/let out a sigh', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('significance', 'noun', 'sɪɡˈnɪfɪkəns', 'the importance of something, especially when this has an effect on what happens in the future', 'a decision of major political significance', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('similarity', 'noun', 'ˌsɪməˈlærəti', 'the state of being similar to somebody/something but not exactly the same', 'similarity between A and B, The report highlights the similarity between the two groups.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('simulate', 'verb', 'ˈsɪmjuleɪt', 'to create particular conditions that exist in real life using computers, models, etc., usually for study or training purposes', 'Computer software can be used to simulate conditions on the seabed.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('simulation', 'noun', 'ˌsɪmjuˈleɪʃn', 'a situation in which a particular set of conditions is created artificially in order to study or experience something that could exist in reality', 'a computer simulation of how the planet functions', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('simultaneously', 'adverb', 'ˌsɪmlˈteɪniəsli', 'at the same time as something else', 'The game will be broadcast simultaneously on TV and radio.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sin', 'noun', 'sɪn', 'an offence against God or against a religious or moral law', 'to commit a sin', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('site', 'noun', 'saɪt', 'a place where a building, town, etc. was, is or will be located', 'the site of a sixteenth-century abbey', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('situated', 'adjective', 'ˈsɪtʃueɪtɪd', 'in a particular place or position', 'My bedroom was situated on the top floor of the house.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('six', 'number', 'sɪks', '6', 'There are six cookies left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sixteen', 'number', 'ˌsɪksˈtiːn', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sixty', 'number', 'ˈsɪksti', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sketch', 'noun', 'sketʃ', 'a simple picture that is drawn quickly and does not have many details', 'The artist is making sketches for his next painting.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ski', 'adjective, noun, verb', 'skiː', 'connected with the sport of skiing', 'a ski resort', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('skiing', 'noun', 'ˈskiːɪŋ', 'the sport or activity of moving over snow on skis', 'He also enjoys skiing and mountain biking.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('skip', 'verb', 'skɪp', 'to move forwards lightly and quickly making a little jump with each step', 'She skipped happily along beside me.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('skull', 'noun', 'skʌl', 'the bone structure that forms the head and surrounds and protects the brain', 'a fractured skull', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('slam', 'verb', 'slæm', 'to shut, or to make something shut, with a lot of force, making a loud noise', 'I heard the door slam behind him.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('slap', 'verb', 'slæp', 'to hit somebody/something with the flat part of your hand', 'She slapped his face hard.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('slash', 'verb', 'slæʃ', 'to make a long cut with a sharp object, especially in a violent way', 'slash something, Someone had slashed the tyres on my car.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('slave', 'noun', 'sleɪv', 'a person who is owned by another person and is forced to work for and obey them', 'A former slave, he graduated from Clafflin University in South Carolina.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('slavery', 'noun', 'ˈsleɪvəri', 'the state of being forced to work as a slave', 'to be sold into slavery', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('slogan', 'noun', 'ˈsləʊɡən', 'a word or phrase that is easy to remember, used for example by a political party or in advertising to attract people’s attention or to suggest an idea quickly', 'an advertising slogan', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('slot', 'noun', 'slɒt', 'a long, narrow opening, into which you put or fit something', 'to put some coins in the slot', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('smartphone', 'noun', 'ˈsmɑːtfəʊn', 'a mobile phone that also has some of the functions of a computer, for example the facility to use apps and the internet', 'You can use your smartphone to access the internet.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('snap', 'verb', 'snæp', 'to break something suddenly with a sharp noise; to be broken in this way', 'snap something, The wind had snapped the tree in two.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('so-called', 'adjective', 'ˌsəʊ ˈkɔːld', 'used to show that you do not think that the word or phrase that is being used to describe somebody/something is appropriate', 'the opinion of a so-called ‘expert’', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('soak', 'verb', 'səʊk', 'to put something in liquid for a time so that it becomes completely wet; to become completely wet in this way', 'soak something (in something), I usually soak the beans overnight.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('soar', 'verb', 'sɔː(r)', 'if the value, amount or level of something soars, it rises very quickly', 'soaring costs/prices/temperatures', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('soccer', 'noun', 'ˈsɒkə(r)', 'a game played by two teams of 11 players, using a round ball which players kick up and down the playing field. Teams try to kick the ball into the other team’s goal.', 'I played soccer when I was younger.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('socialist', 'adjective', 'ˈsəʊʃəlɪst', 'connected with socialism', 'socialist beliefs', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('solar', 'adjective', 'ˈsəʊlə(r)', 'of or connected with the sun', 'solar radiation', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sole', 'adjective', 'səʊl', 'only; single', 'the sole surviving member of the family', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('solely', 'adverb', 'ˈsəʊlli', 'only; not involving somebody/something else', 'She was motivated solely by self-interest.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('solicitor', 'noun', 'səˈlɪsɪtə(r)', 'a lawyer who prepares legal documents, for example for the sale of land or buildings, advises people on legal matters, and can speak for them in some courts of law', 'Her first step was to contact a solicitor for advice.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('solidarity', 'noun', 'ˌsɒlɪˈdærəti', 'support by one person or group of people for another because they share feelings, opinions, aims, etc.', 'community solidarity', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('solo', 'adjective, noun', 'ˈsəʊləʊ', 'done by one person alone, without anyone helping them', 'his first solo flight', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('somebody', 'pronoun', 'ˈsʌmbədi', 'a person who is not known or mentioned by name', 'Somebody should have told me.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('someone', 'pronoun', 'ˈsʌmwʌn', 'a person who is not known or mentioned by name', 'There''s someone at the door.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sometime', 'adverb', 'ˈsʌmtaɪm', 'at a time that you do not know exactly or has not yet been decided', 'I saw him sometime last summer.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sophisticated', 'adjective', 'səˈfɪstɪkeɪtɪd', 'clever and complicated in the way that it works or is presented', 'highly sophisticated computer systems', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sovereignty', 'noun', 'ˈsɒvrənti', 'complete power to govern a country', 'The country claimed sovereignty over the island.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spam', 'noun', 'spæm', 'advertising material sent by email to people who have not asked for it; advertising material on the internet that is not wanted ', 'to send/block spam', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('span', 'noun, verb', 'spæn', 'the length of time that something lasts or is able to continue', 'I worked with him over a span of six years.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spark', 'verb', 'spɑːk', 'to cause something to start or develop, especially suddenly', 'spark something, The proposal would spark a storm of protest around the country.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('specialize', 'verb', 'ˈspeʃəlaɪz', 'to become an expert in a particular area of work, study or business; to spend more time on one area of work, etc. than on others', 'Many students prefer not to specialize too soon.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('specialized', 'adjective', 'ˈspeʃəlaɪzd', 'designed or developed for a particular purpose or area of knowledge', 'specialized equipment', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('species', 'noun', 'ˈspiːʃiːz', 'a group into which animals, plants, etc. that are able to have sex with each other and produce healthy young are divided, smaller than a genus and identified by a Latin name', 'a conservation area for endangered species', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('specification', 'noun', 'ˌspesɪfɪˈkeɪʃn', 'a detailed description of how something is, or should be, designed or made', 'the technical specifications of the new model (= of car)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('specify', 'verb', 'ˈspesɪfaɪ', 'to state something, especially by giving an exact measurement, time, exact instructions, etc.', 'specify something, Remember to specify your size when ordering clothes.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('specimen', 'noun', 'ˈspesɪmən', 'a small amount of something that shows what the rest of it is like', 'Astronauts have brought back specimens of rock from the moon.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spectacle', 'noun', 'ˈspektəkl', 'two lenses in a frame that rests on the nose and ears. People wear spectacles in order to be able to see better or to protect their eyes from bright light.', 'a pair of spectacles', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spectacular', 'adjective', 'spekˈtækjələ(r)', 'very impressive', 'The coastal road has spectacular scenery.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spectator', 'noun', 'spekˈteɪtə(r)', 'a person who is watching an event, especially a sports event', 'The new football stadium will hold 75 000 spectators.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spectrum', 'noun', 'ˈspektrəm', 'a band of coloured lights in order of their wavelengths, as seen in a rainbow and into which light may be separated', 'A spectrum is formed by a ray of light passing through a prism.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('speculate', 'verb', 'ˈspekjuleɪt', 'to form an opinion about something without knowing all the details or facts', 'speculate (about/on/as to something), We all speculated about the reasons for her resignation.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('speculation', 'noun', 'ˌspekjuˈleɪʃn', 'the act of forming opinions about what has happened or what might happen without knowing all the facts', 'His private life is the subject of much speculation.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spending', 'noun', 'ˈspendɪŋ', 'the amount of money that is spent by a government, an organization or a person', 'to increase/cut/reduce spending', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sphere', 'noun', 'sfɪə(r)', 'a solid figure that is completely round, with every point on its surface at an equal distance from the centre', 'The Earth is not a perfect sphere.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spill', 'verb', 'spɪl', 'to flow over the edge of a container by accident; to make liquid do this', 'Water had spilled out of the bucket onto the floor.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spine', 'noun', 'spaɪn', 'the row of small bones that are connected together down the middle of the back', 'A shiver went down my spine.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spokesman', 'noun', 'ˈspəʊksmən', 'a person who speaks for a group or an organization', 'a police spokesman', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spokesperson', 'noun', 'ˈspəʊkspɜːsn', 'a person who speaks for a group or an organization', 'a council spokesperson', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spokeswoman', 'noun', 'ˈspəʊkswʊmən', 'a woman who speaks for a group or an organization', 'a government spokeswoman', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sponsor', 'noun, verb', 'ˈspɒnsə(r)', 'a person or company that pays for a radio or television programme, or for a concert or sporting event, usually in return for advertising', 'The programme is funded by a number of corporate sponsors.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sponsorship', 'noun', 'ˈspɒnsəʃɪp', 'financial support from a sponsor', 'a $50 million sponsorship deal', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sporting', 'adjective', 'ˈspɔːtɪŋ', 'connected with sports', 'a major sporting event', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spotlight', 'noun', 'ˈspɒtlaɪt', 'a light with a single, very bright beam that can be directed at a particular place or person, especially a performer on the stage', 'The room was lit by spotlights.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spouse', 'noun', 'spaʊs', 'a husband or wife', 'Fill in your spouse’s name here.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('spy', 'noun, verb', 'spaɪ', 'a person who tries to get secret information about another country, organization or person, especially somebody who is employed by a government or the police', 'He was denounced as a foreign spy.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('squad', 'noun', 'skwɒd', 'a section of a police force that deals with a particular type of crime', 'the drugs/fraud/bomb/riot squad ', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stab', 'verb', 'stæb', 'to push a sharp, pointed object, especially a knife, into somebody, killing or injuring them', 'He was stabbed to death in a racist attack.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stability', 'noun', 'stəˈbɪləti', 'the quality or state of being steady and not changing or being upset in any way (= the quality of being stable)', 'political/economic/social stability', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stabilize', 'verb', 'ˈsteɪbəlaɪz', 'to become or to make something become steady and unlikely to change; to make something stable', 'The patient''s condition stabilized.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stadium', 'noun', 'ˈsteɪdiəm', 'a large sports ground surrounded by rows of seats and usually other buildings', 'a football/sports stadium', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stake', 'noun', 'steɪk', 'money that somebody invests in a company', 'a 20 per cent stake in the business', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stall', 'noun', 'stɔːl', 'a table or small shop with an open front that people sell things from, especially at a market', 'He works on a market stall in the Square.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stance', 'noun', 'stæns', 'the opinions that somebody has about something and expresses publicly', 'What is the newspaper''s stance on the war?', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('standing', 'adjective', 'ˈstændɪŋ', 'done from a position in which you are standing rather than sitting or running', 'a standing jump/start', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stark', 'adjective', 'stɑːk', 'unpleasant; real, and impossible to avoid', 'The author paints a stark picture of life in a prison camp.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('starve', 'verb', 'stɑːv', 'to suffer or die because you do not have enough food to eat; to make somebody suffer or die in this way', 'The animals were left to starve to death.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('statistic', 'noun', 'stəˈtɪstɪk', 'a collection of information shown in numbers', 'Analysis of crime statistics showed high levels of violent crime within the area.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('statistical', 'adjective', 'stəˈtɪstɪkl', 'connected with or based on statistics', 'statistical analysis', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stem', 'noun, verb', 'stem', 'the main long, thin part of a plant above the ground from which the leaves or flowers grow; a smaller part that grows from this and supports flowers or leaves', 'long, trailing stems of ivy', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stereotype', 'noun', 'ˈsteriətaɪp', 'a fixed idea or image that many people have of a particular type of person or thing, but which is often not true in reality and may cause hurt and offence', 'cultural/gender/racial stereotypes', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stimulate', 'verb', 'ˈstɪmjuleɪt', 'to make something develop or become more active; to encourage something', 'The exhibition has stimulated interest in her work.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stimulus', 'noun', 'ˈstɪmjələs', 'something that helps somebody/something to develop better or more quickly', 'stimulus for something, Books provide children with ideas and a stimulus for play.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('storage', 'noun', 'ˈstɔːrɪdʒ', 'the process of keeping something in a particular place until it is needed; the space where things can be kept', 'tables that fold flat for storage', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('straightforward', 'adjective', 'ˌstreɪtˈfɔːwəd', 'easy to do or to understand; not complicated', 'It''s a relatively straightforward process.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('strand', 'noun', 'strænd', 'a single thin piece of thread, wire, hair, etc.', 'He pulled at a loose strand of wool in his sweater.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('strategic', 'adjective', 'strəˈtiːdʒɪk', 'done as part of a plan that is meant to achieve a particular purpose or to gain an advantage', 'strategic planning', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('street', 'noun', 'striːt', 'a public road in a city or town that has houses and buildings on one side or both sides', 'along/down/up the street, I was just walking along the street when it happened.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('strengthen', 'verb', 'ˈstreŋkθn', 'to become more powerful or effective; to make somebody/something more powerful or effective', 'Her position in the party has strengthened in recent weeks.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('strive', 'verb', 'straɪv', 'to try very hard to achieve something', 'strive for something, We encourage all members to strive for the highest standards.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('structural', 'adjective', 'ˈstrʌktʃərəl', 'connected with the way in which something is built or organized', 'Storms have caused structural damage to hundreds of homes.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stumble', 'verb', 'ˈstʌmbl', 'to hit your foot against something while you are walking or running and almost fall', 'The child stumbled and fell.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stun', 'verb', 'stʌn', 'to make a person or an animal unconscious for a short time, especially by hitting them on the head', 'The fall stunned me for a moment.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('stunning', 'adjective', 'ˈstʌnɪŋ', 'extremely attractive or impressive', 'You look absolutely stunning!', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('submission', 'noun', 'səbˈmɪʃn', 'the act of accepting that somebody has defeated you and that you must obey them', 'a gesture of submission', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('submit', 'verb', 'səbˈmɪt', 'to give a document, proposal, etc. to somebody in authority so that they can study or consider it', 'submit something, to submit an application/a claim/a proposal', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('subscriber', 'noun', 'səbˈskraɪbə(r)', 'a person who pays money, usually once a year, to receive regular copies of a magazine or newspaper or have access to it online', 'subscribers to ‘New Scientist’', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('subscription', 'noun', 'səbˈskrɪpʃn', 'an amount of money that you pay regularly to receive a service, be a member of a club, support a charity or receive regular copies of a newspaper or magazine; the act of paying this money', 'an annual subscription', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('subsequent', 'adjective', 'ˈsʌbsɪkwənt', 'happening or coming after something else', 'subsequent generations', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('subsequently', 'adverb', 'ˈsʌbsɪkwəntli', 'afterwards; later; after something else has happened', 'The original interview notes were subsequently lost.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('subsidy', 'noun', 'ˈsʌbsədi', 'money that is paid by a government or an organization to reduce the costs of services or of producing goods so that their prices can be kept low', 'agricultural subsidies', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('substitution', 'noun', 'ˌsʌbstɪˈtjuːʃn', 'an act of using one person or thing in the place of another', 'Two substitutions were made during the game.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('subtle', 'adjective', 'ˈsʌtl', 'not very obvious or easy to notice ', 'subtle colours/flavours/smells, etc.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('suburb', 'noun', 'ˈsʌbɜːb', 'an area where people live that is outside the centre of a city', 'a suburb of London', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('suburban', 'adjective', 'səˈbɜːbən', 'in or connected with a suburb', 'suburban areas', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('succession', 'noun', 'səkˈseʃn', 'a number of people or things that follow each other in time or order', 'a succession of visitors', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('successive', 'adjective', 'səkˈsesɪv', 'following immediately one after the other', 'This was their fourth successive win.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('successor', 'noun', 'səkˈsesə(r)', 'a person or thing that comes after somebody/something else and takes their/its place', 'Who''s the likely successor to him as party leader?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sue', 'verb', 'suː', 'to make a claim against a person or an organization in court about something that they have said or done to harm you', 'They threatened to sue if the work was not completed.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('suicide', 'noun', 'ˈsuːɪsaɪd', 'the act of killing yourself deliberately', 'to commit suicide', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('suite', 'noun', 'swiːt', 'a set of rooms, especially in a hotel', 'a hotel/private/honeymoon suite', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('summarize', 'verb', 'ˈsʌməraɪz', 'to give a summary of something', 'This essay briefly summarizes some of our approaches.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('summit', 'noun', 'ˈsʌmɪt', 'the highest point of something, especially the top of a mountain', 'We reached the summit at noon.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('super', 'adjective', 'ˈsuːpə(r)', 'extremely good', 'a super meal', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('superb', 'adjective', 'suːˈpɜːb', 'excellent; of very good quality', 'a superb player', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('supervise', 'verb', 'ˈsuːpəvaɪz', 'to be in charge of somebody/something and make sure that everything is done correctly, safely, etc.', 'supervise (somebody/something), to supervise building work', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('supervision', 'noun', 'ˌsuːpəˈvɪʒn', 'the work or activity involved in being in charge of somebody/something and making sure that everything is done correctly, safely, etc.', 'Very young children should not be left to play without supervision.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('supervisor', 'noun', 'ˈsuːpəvaɪzə(r)', 'a person who supervises somebody/something', 'I have a meeting with my supervisor about my research topic.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('supplement', 'noun, verb', 'ˈsʌplɪmənt', 'a thing that is added to something else to improve or complete it', 'vitamin/dietary supplements (= vitamins and other foods eaten in addition to what you usually eat)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('supportive', 'adjective', 'səˈpɔːtɪv', 'encouraging somebody or giving them help or sympathy', 'a supportive family', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('supposedly', 'adverb', 'səˈpəʊzɪdli', 'according to what is generally thought or believed but not known for certain', 'The novel is supposedly based on a true story.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('suppress', 'verb', 'səˈpres', 'to put an end, often by force, to a group or an activity that is believed to threaten authority', 'The rebellion was brutally suppressed.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('supreme', 'adjective', 'suˈpriːm', 'highest in rank or position', 'the Supreme Commander of the armed forces', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('surge', 'noun, verb', 'sɜːdʒ', 'a sudden increase of a strong feeling', 'She felt a sudden surge of anger.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('surgeon', 'noun', 'ˈsɜːdʒən', 'a doctor who is trained to perform surgery (= medical operations that involve cutting open a person’s body)', 'a brain/heart surgeon', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('surgery', 'noun', 'ˈsɜːdʒəri', 'medical treatment of injuries or diseases that involves cutting open a person’s body and often removing or replacing some parts; the branch of medicine connected with this treatment', 'major/minor surgery', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('surgical', 'adjective', 'ˈsɜːdʒɪkl', 'used in or connected with surgery', 'surgical procedures', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('surplus', 'noun', 'ˈsɜːpləs', 'an amount that is extra or more than you need', 'food surpluses', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('surrender', 'verb', 'səˈrendə(r)', 'to admit that you have been defeated and want to stop fighting; to allow yourself to be caught, taken prisoner, etc.', 'The rebel soldiers were forced to surrender.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('surveillance', 'noun', 'sɜːˈveɪləns', 'the act of carefully watching a person suspected of a crime or a place where a crime may be committed', 'The police are keeping the suspects under constant surveillance.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('survival', 'noun', 'səˈvaɪvl', 'the state of continuing to live or exist, often despite difficulty or danger', 'the struggle/battle/fight for survival', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('survivor', 'noun', 'səˈvaɪvə(r)', 'a person who continues to live, especially despite being nearly killed or experiencing great danger or difficulty', 'the sole/only survivor of the massacre', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('suspend', 'verb', 'səˈspend', 'to hang something from something else', 'be suspended from something, A lamp was suspended from the ceiling.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('suspension', 'noun', 'səˈspenʃn', 'the act of officially removing somebody from their job, school, team, etc. for a period of time, usually as a punishment', 'suspension from school', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sustain', 'verb', 'səˈsteɪn', 'to provide enough of what somebody/something needs in order to live or exist', 'Which planets can sustain life?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sustainable', 'adjective', 'səˈsteɪnəbl', 'involving the use of natural products and energy in a way that does not harm the environment', 'sustainable forest management', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('sword', 'noun', 'sɔːd', 'a weapon with a long metal blade (= sharp cutting part) and a handle', 'to draw/sheathe a sword (= to take it out of/put it into its cover)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('symbolic', 'adjective', 'sɪmˈbɒlɪk', 'containing symbols, or being used as a symbol', 'He shook his fist in a symbolic gesture of defiance.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('symptom', 'noun', 'ˈsɪmptəm', 'a change in your body or mind that shows that you are not healthy', 'Symptoms include a headache and sore throat.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('syndrome', 'noun', 'ˈsɪndrəʊm', 'a set of physical conditions that show you have a particular disease or medical problem', 'PMS or premenstrual syndrome', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('synthesis', 'noun', 'ˈsɪnθəsɪs', 'the act of combining separate ideas, beliefs, styles, etc.; a mixture or combination of ideas, beliefs, styles, etc.', 'synthesis of A with B, the synthesis of art with everyday life', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('systematic', 'adjective', 'ˌsɪstəˈmætɪk', 'done according to a system or plan, in a complete, efficient or determined way', 'a systematic approach to solving the problem', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('T-shirt', 'noun', 'ˈtiː ʃɜːt', 'an informal shirt, usually with short sleeves (= arms) no collar or buttons, or just a few buttons at the top', 'He was wearing a faded pair of blue jeans and an old T-shirt.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tactic', 'noun', 'ˈtæktɪk', 'the particular method you use to achieve something', 'They tried all kinds of tactics to get us to go.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tactical', 'adjective', 'ˈtæktɪkl', 'connected with the particular method you use to achieve something', 'tactical planning', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tag', 'noun, verb', 'tæɡ', 'a small piece of paper, cloth, plastic, etc. attached to something to identify it or give information about it', 'He put name tags on all his shirts.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tale', 'noun', 'teɪl', 'a story created using the imagination, especially one that is full of action and adventure', 'a coming-of-age/morality tale', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('talent', 'noun', 'ˈtælənt', 'a natural ability to do something well', 'The festival showcases the talent of young musicians.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('talented', 'adjective', 'ˈtæləntɪd', 'having a natural ability to do something well', 'a talented player/musician/artist ', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('taxpayer', 'noun', 'ˈtækspeɪə(r)', 'a person who pays tax to the government, especially on the money that they earn', 'Hundreds of thousands of pounds of taxpayers'' money (= money paid in taxes) have been spent on the project.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('technological', 'adjective', 'ˌteknəˈlɒdʒɪkl', 'connected with technology ', 'technological advances', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('teenage', 'adjective', 'ˈtiːneɪdʒ', 'between 13 and 19 years old; connected with people of this age', 'a teenage girl/boy', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('teenager', 'noun', 'ˈtiːneɪdʒə(r)', 'a person who is between 13 and 19 years old', 'a magazine aimed at teenagers', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('teens', 'noun', 'tiːnz', 'the years of a person’s life when they are between 13 and 19 years old', 'in your teens, She began writing poetry in her teens.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('telephone', 'noun, verb', 'ˈtelɪfəʊn', 'a system for talking to somebody else over long distances, using wires or radio; a machine used for this', 'The telephone rang and Pat answered it.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('television', 'noun', 'ˈtelɪvɪʒn', 'a piece of electrical equipment with a screen on which you can watch programmes with moving pictures and sounds', 'a widescreen/flat-screen/plasma television', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('temple', 'noun', 'ˈtempl', 'a building used for religious worship, especially in religions other than Christianity', 'the Temple of Diana at Ephesus', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tempt', 'verb', 'tempt', 'to attract somebody or make somebody want to do or have something, even if they know it is wrong', 'tempt somebody, I was tempted by the dessert menu.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ten', 'number', 'ten', '10', 'There are only ten of these rare animals left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tenant', 'noun', 'ˈtenənt', 'a person who pays rent for the use of a room, building, land, etc. to the person who owns it', 'They had evicted their tenants for non-payment of rent.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tender', 'adjective', 'ˈtendə(r)', 'kind, gentle and loving', 'tender words', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tennis', 'noun', 'ˈtenɪs', 'a game in which two or four players use rackets to hit a ball backwards and forwards across a net on a specially marked court ', 'to play tennis', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tenure', 'noun', 'ˈtenjə(r)', 'the period of time when somebody holds an important job, especially a political one; the act of holding an important job', 'his four-year tenure as president', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terminal', 'adjective, noun', 'ˈtɜːmɪnl', 'that cannot be cured and will lead to death, often slowly', 'He has terminal lung cancer.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terminate', 'verb', 'ˈtɜːmɪneɪt', 'to end; to make something end', 'Your contract of employment terminates in December.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terms', 'noun', 'tɜːmz', 'the conditions that people offer, demand or accept when they make an agreement, an arrangement or a contract', 'peace terms', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terrain', 'noun', 'təˈreɪn', 'used to refer to an area of land when you are mentioning its natural features, for example, if it is rough, flat, etc.', 'difficult/rough/mountainous terrain', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terrific', 'adjective', 'təˈrɪfɪk', 'excellent; wonderful', 'I feel absolutely terrific today!', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terrify', 'verb', 'ˈterɪfaɪ', 'to make somebody feel extremely frightened', 'terrify somebody, Flying terrifies her.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('territory', 'noun', 'ˈterətri', 'land that is under the control of a particular country or political leader', 'enemy/disputed/foreign territory', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terror', 'noun', 'ˈterə(r)', 'a feeling of extreme fear', 'a feeling of sheer/pure terror', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terrorism', 'noun', 'ˈterərɪzəm', 'the use of violent action in order to achieve political aims or to force a government to act', 'an act of terrorism', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('terrorist', 'noun', 'ˈterərɪst', 'a person who takes part in terrorism', 'The terrorists are threatening to blow up the plane.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('testify', 'verb', 'ˈtestɪfaɪ', 'to make a statement that something happened or that something is true, especially as a witness in court', 'testify against somebody/something, She refused to testify against her husband.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('testimony', 'noun', 'ˈtestɪməni', 'a thing that shows that something else exists or is true', 'This increase in exports bears testimony to the successes of industry.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('testing', 'noun', 'ˈtestɪŋ', 'the activity of testing somebody/something in order to find something out, see if it works, etc.', 'nuclear testing', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('textbook', 'noun', 'ˈtekstbʊk', 'a book that teaches a particular subject and that is used especially in schools and colleges', 'a school/medical/history textbook', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('texture', 'noun', 'ˈtekstʃə(r)', 'the way a surface, substance or piece of cloth feels when you touch it, for example how rough, smooth, hard or soft it is', 'the soft texture of velvet', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thankfully', 'adverb', 'ˈθæŋkfəli', 'used to show that you are pleased that something good has happened or that something bad has been avoided', 'There was a fire in the building, but thankfully no one was hurt.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('theatrical', 'adjective', 'θiˈætrɪkl', 'connected with the theatre', 'a theatrical agent', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('theft', 'noun', 'θeft', 'the crime of stealing something from a person or place', 'car theft', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('theology', 'noun', 'θiˈɒlədʒi', 'the study of religion and beliefs', 'a degree in theology', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('theoretical', 'adjective', 'ˌθɪəˈretɪkl', 'connected with the ideas and principles on which a particular subject is based, rather than with practice and experiment', 'a theoretical approach', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('therapist', 'noun', 'ˈθerəpɪst', 'a specialist who treats a particular type of illness or problem, or who uses a particular type of treatment', 'a speech therapist', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('therapy', 'noun', 'ˈθerəpi', 'the treatment of a physical problem or an illness', 'He is receiving therapy for cancer.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thereafter', 'adverb', 'ˌðeərˈɑːftə(r)', 'after the time or event mentioned', 'She married at 17 and gave birth to her first child shortly thereafter.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thereby', 'adverb', 'ˌðeəˈbaɪ', 'used to introduce the result of the action or situation mentioned', 'Regular exercise strengthens the heart, thereby reducing the risk of heart attack.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thesis', 'noun', 'ˈθiːsɪs', 'a long piece of writing completed by a student as part of a university degree, based on their own research', 'Students must submit a thesis on an agreed subject within four years.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('third', 'noun, ordinal number', 'θɜːd', 'each of three equal parts of something', 'He divided the money into thirds.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thirteen', 'number', 'ˌθɜːˈtiːn', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thirty', 'number', 'ˈθɜːti', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thought-provoking', 'adjective', 'ˈθɔːt prəvəʊkɪŋ', 'making people think seriously about a particular subject or issue', 'a brilliant and thought-provoking play', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thoughtful', 'adjective', 'ˈθɔːtfl', 'quiet, because you are thinking', 'He looked thoughtful.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thousand', 'number', 'ˈθaʊznd', '1 000', 'There were thousands of people there.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('three', 'number', 'θriː', '3', 'There are only three cookies left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('threshold', 'noun', 'ˈθreʃhəʊld', 'the floor or ground at the bottom of a doorway, considered as the entrance to a building or room', 'He stepped across the threshold.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thrilled', 'adjective', 'θrɪld', 'very excited and pleased', '‘Are you pleased?’ ‘I''m thrilled.’', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('thrive', 'verb', 'θraɪv', 'to become, and continue to be, successful, strong, healthy, etc.', 'New businesses thrive in this area.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('Thursday', 'noun', 'ˈθɜːzdeɪ', 'the day of the week after Wednesday and before Friday', 'It''s Thursday today, isn''t it?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tide', 'noun', 'taɪd', 'a regular rise and fall in the level of the sea, caused by the pull of the moon and sun; the flow of water that happens as the sea rises and falls', 'the ebb and flow of the tide', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tighten', 'verb', 'ˈtaɪtn', 'to hold or fix something more securely in position; to make something or become more difficult to move, open or separate', 'tighten something, to tighten a lid/screw/rope/knot', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('till', 'conjunction, preposition', 'tɪl', 'until', 'We''re open till 6 o''clock.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('timber', 'noun', 'ˈtɪmbə(r)', 'trees that are grown to be used in building or for making things', 'the timber industry', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('timely', 'adjective', 'ˈtaɪmli', 'happening at exactly the right time', 'A nasty incident was prevented by the timely arrival of the police.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('timing', 'noun', 'ˈtaɪmɪŋ', 'the act of choosing when something happens; a particular point or period of time when something happens or is planned', 'The timing of the decision was a complete surprise.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tissue', 'noun', 'ˈtɪʃuː', 'a piece of soft paper, used especially as a handkerchief', 'a box of tissues', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tobacco', 'noun', 'təˈbækəʊ', 'the dried leaves of the tobacco plant that are used for making cigarettes, smoking in a pipe, etc.', 'tobacco smoke', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tolerance', 'noun', 'ˈtɒlərəns', 'the quality of being willing to accept or tolerate somebody/something, especially opinions or behaviour that you may not agree with, or people who are not like you', 'She had no tolerance for jokes of any kind.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tolerate', 'verb', 'ˈtɒləreɪt', 'to allow somebody to do something that you do not agree with or like', 'tolerate something, Their relationship was tolerated but not encouraged.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('toll', 'noun', 'təʊl', 'money that you pay to use a particular road or bridge', 'motorway tolls', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('torture', 'noun, verb', 'ˈtɔːtʃə(r)', 'the act of causing somebody severe pain in order to punish them or make them say or do something', 'Many of the refugees have suffered torture.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('toss', 'verb', 'tɒs', 'to throw something lightly or carelessly', 'toss something + adv./prep., I tossed the book aside and got up.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tourism', 'noun', 'ˈtʊərɪzəm', 'the business activity connected with providing accommodation, services and entertainment for people who are visiting a place for pleasure', 'The area is heavily dependent on tourism.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tournament', 'noun', 'ˈtʊənəmənt', 'a sports competition involving a number of teams or players who take part in different games and must leave the competition if they lose. The competition continues until there is only the winner left.', 'a golf/tennis/soccer/chess tournament', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('toxic', 'adjective', 'ˈtɒksɪk', 'containing poison; poisonous', 'toxic chemicals/fumes/gases/substances', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trademark', 'noun', 'ˈtreɪdmɑːk', 'a name, symbol or design that a company uses for its products and that cannot be used by anyone else', '‘Big Mac’ is McDonald''s best-known trademark.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tragedy', 'noun', 'ˈtrædʒədi', 'a very sad event or situation, especially one that involves death', 'It''s a tragedy that she died so young.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tragic', 'adjective', 'ˈtrædʒɪk', 'making you feel very sad, usually because somebody has died or suffered a lot', 'He was killed in a tragic accident at the age of 24.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trail', 'noun, verb', 'treɪl', 'a long line or series of marks that is left by somebody/something', 'a trail of blood', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trailer', 'noun', 'ˈtreɪlə(r)', 'a truck, or a container with wheels, that is pulled by another vehicle', 'a car towing a trailer with a boat on it', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trainer', 'noun', 'ˈtreɪnə(r)', 'a shoe that you wear for sports or as informal clothing', 'a pair of trainers', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trait', 'noun', 'treɪt', 'a particular quality in your personality', 'personality traits', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transaction', 'noun', 'trænˈzækʃn', 'a piece of business that is done between people, especially an act of buying or selling', 'financial transactions between companies', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transcript', 'noun', 'ˈtrænskrɪpt', 'a written or printed copy of words that have been spoken', 'a transcript of the interview', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transformation', 'noun', 'ˌtrænsfəˈmeɪʃn', 'a complete change in somebody/something', 'The way in which we work has undergone a complete transformation in the past decade.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transit', 'noun', 'ˈtrænzɪt', 'the process of being moved or carried from one place to another', 'The cost includes transit.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transition', 'noun', 'trænˈzɪʃn', 'the process or a period of changing from one state or condition to another', 'transition from something to something, the transition from school to full-time work', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transmission', 'noun', 'trænzˈmɪʃn', 'the act or process of passing something from one person, place or thing to another', 'the transmission of the disease', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transmit', 'verb', 'trænzˈmɪt', 'to send an electronic signal, radio or television broadcast, etc.', 'signals transmitted from a satellite', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transparency', 'noun', 'trænsˈpærənsi', 'the quality of something, such as a situation or an argument, that makes it easy to understand', 'a need for greater transparency in legal documents', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('transportation', 'noun', 'ˌtrænspɔːˈteɪʃn', 'a system for carrying people or goods from one place to another using vehicles, roads, etc.', 'public transportation (= the system of buses, trains, etc. provided for people to travel from one place to another)', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trauma', 'noun', 'ˈtrɔːmə', 'a mental condition caused by severe shock, stress or fear, especially when the harmful effects last for a long time', 'the effects of trauma and stress on the body', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('treasure', 'noun', 'ˈtreʒə(r)', 'a collection of valuable things such as gold, silver and jewellery', 'buried treasure', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('treaty', 'noun', 'ˈtriːti', 'a formal agreement between two or more countries', 'the Treaty of Rome', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tremendous', 'adjective', 'trəˈmendəs', 'very great', 'a tremendous explosion', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tribal', 'adjective', 'ˈtraɪbl', 'connected with a tribe or tribes', 'tribal art', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tribe', 'noun', 'traɪb', 'a social group in a traditional society consisting of people with the same language, culture, religion, etc., living in a particular area and often having one leader known as a chief ', 'They were a nomadic horse-riding tribe.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tribunal', 'noun', 'traɪˈbjuːnl', 'a type of court with the authority to deal with a particular problem or disagreement', 'an international war crimes tribunal', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tribute', 'noun', 'ˈtrɪbjuːt', 'an act, a statement or a gift that is intended to show your love or respect, especially for a dead person', 'At her funeral her oldest friend paid tribute to her life and work.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trigger', 'noun, verb', 'ˈtrɪɡə(r)', 'the part of a gun that you press in order to fire it', 'to pull/squeeze the trigger', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trillion', 'number', 'ˈtrɪljən', '', NULL, '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trio', 'noun', 'ˈtriːəʊ', 'a group of three people or things', 'A trio of English runners featured in the women’s 1 500 metres.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('triumph', 'noun', 'ˈtraɪʌmf', 'a great success, achievement or victory', 'one of the greatest triumphs of modern science', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('troop', 'noun', 'truːp', 'soldiers, especially in large groups', 'They announced the withdrawal of 12 000 troops from the area.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trophy', 'noun', 'ˈtrəʊfi', 'an object such as a silver cup that is given as a prize for winning a competition', 'a trophy cabinet', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('troubled', 'adjective', 'ˈtrʌbld', 'worried and anxious', 'She looked into his troubled face.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('trustee', 'noun', 'trʌˈstiː', 'a person or an organization that has control of money or property that has been put into a trust for somebody', 'The bank will act as trustees for the estate until the child is 18.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tsunami', 'noun', 'tsuːˈnɑːmi', 'an extremely large wave in the sea caused, for example, by an earthquake', 'A tsunami early warning system was set up in Hawaii.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('Tuesday', 'noun', 'ˈtjuːzdeɪ', 'the day of the week after Monday and before Wednesday', 'It''s Tuesday today, isn''t it?', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('tuition', 'noun', 'tjuˈɪʃn', 'the act of teaching something, especially to one person or to people in small groups', 'She received private tuition in French.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('turnout', 'noun', 'ˈtɜːnaʊt', 'the number of people who attend a particular event', 'This year''s festival attracted a record turnout.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('turnover', 'noun', 'ˈtɜːnəʊvə(r)', 'the total amount of goods or services sold by a company during a particular period of time', 'an annual turnover of $75 million', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('TV', 'noun', 'ˌtiː ˈviː', 'television', 'We spent the evening watching TV.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('twelve', 'number', 'twelv', '12', 'There are only twelve of these rare animals left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('twenty', 'number', 'ˈtwenti', '', NULL, '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('two', 'number', 'tuː', '2', 'There are only two cookies left.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('uncertainty', 'noun', 'ʌnˈsɜːtnti', 'the state of being uncertain', 'There is considerable uncertainty about the company''s future.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('undergo', 'verb', 'ˌʌndəˈɡəʊ', 'to experience something, especially a change or something unpleasant', 'to undergo tests/trials/repairs', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('undergraduate', 'noun', 'ˌʌndəˈɡrædʒuət', 'a university or college student who is studying for their first degree', 'a first-year undergraduate', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('underlying', 'adjective', 'ˌʌndəˈlaɪɪŋ', 'important in a situation but not always easily noticed or stated clearly', 'The underlying assumption is that the amount of money available is limited.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('undermine', 'verb', 'ˌʌndəˈmaɪn', 'to make something, especially somebody’s confidence or authority, gradually weaker or less effective', 'Our confidence in the team has been seriously undermined by their recent defeats.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('undertake', 'verb', 'ˌʌndəˈteɪk', 'to make yourself responsible for something and start doing it', 'to undertake a task/project', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('undoubtedly', 'adverb', 'ʌnˈdaʊtɪdli', 'used to emphasize that something exists or is definitely true', 'There is undoubtedly a great deal of truth in what he says.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('unfold', 'verb', 'ʌnˈfəʊld', 'to spread open or flat something that has previously been folded; to become open and flat', 'to unfold a map', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('unify', 'verb', 'ˈjuːnɪfaɪ', 'to join people, things, parts of a country, etc. together so that they form a single unit', 'The new leader hopes to unify the country.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('unity', 'noun', 'ˈjuːnəti', 'the state of being in agreement and working together; the state of being joined together to form one unit', 'European unity', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('universal', 'adjective', 'ˌjuːnɪˈvɜːsl', 'done by or involving all the people in the world or in a particular group', 'Such problems are a universal feature of old age.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('unprecedented', 'adjective', 'ʌnˈpresɪdentɪd', 'that has never happened, been done or been known before', 'The situation is unprecedented in modern times.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('until', 'conjunction, preposition', 'ənˈtɪl', 'up to the point in time or the event mentioned', 'Let''s wait until the rain stops.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('unveil', 'verb', 'ˌʌnˈveɪl', 'to remove a cover or curtain from a painting, statue, etc. so that it can be seen in public for the first time', 'The Queen unveiled a plaque to mark the official opening of the hospital.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('upcoming', 'adjective', 'ˈʌpkʌmɪŋ', 'going to happen soon', 'the upcoming presidential election', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('update', 'noun, verb', 'ˈʌpdeɪt', 'a report or broadcast that gives the most recent information about something; a new version of something containing the most recent information', 'They will send you regular updates by email.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('upgrade', 'noun, verb', 'ˈʌpɡreɪd', 'the act of making a machine, computer system, etc. more powerful and efficient; the more powerful and efficient machine, computer system, etc.', 'instructions for installing an upgrade to the existing system', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('uphold', 'verb', 'ʌpˈhəʊld', 'to support something that you think is right and make sure that it continues to exist', 'We have a duty to uphold the law.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('usage', 'noun', 'ˈjuːsɪdʒ', 'the way in which words are used in a language', 'a book on current English usage', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('utility', 'noun', 'juːˈtɪləti', 'a service provided for the public, for example an electricity, water or gas supply', 'a privatized electricity utility', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('utilize', 'verb', 'ˈjuːtəlaɪz', 'to use something, especially for a practical purpose', 'The Romans were the first to utilize concrete as a building material.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('utterly', 'adverb', 'ˈʌtəli', 'completely', 'We''re so utterly different from each other.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vacuum', 'noun', 'ˈvækjuːm', 'a space that is completely empty of all substances, including all air or other gas', 'a vacuum pump (= one that creates a vacuum)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vague', 'adjective', 'veɪɡ', 'not clear in a person’s mind', 'to have a vague impression/memory/recollection of something', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('validity', 'noun', 'vəˈlɪdəti', 'the state of being legally or officially acceptable', 'The period of validity of the agreement has expired.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vanish', 'verb', 'ˈvænɪʃ', 'to disappear suddenly and/or in a way that you cannot explain', 'He turned around and vanished into the house.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('variable', 'adjective, noun', 'ˈveəriəbl', 'often changing; likely to change', 'variable temperatures', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vein', 'noun', 'veɪn', 'any of the tubes that carry blood from all parts of the body towards the heart', 'the jugular vein', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('venue', 'noun', 'ˈvenjuː', 'a place where people meet for an organized event, for example a concert, sporting event or conference', 'The band will be playing at 20 different venues on their UK tour.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('verbal', 'adjective', 'ˈvɜːbl', 'relating to words', 'The job applicant must have good verbal skills.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('verdict', 'noun', 'ˈvɜːdɪkt', 'an official judgement made in court or at an inquest (= an official investigation into somebody''s death)', 'Has the jury reached a verdict?', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('verify', 'verb', 'ˈverɪfaɪ', 'to check that something is true or accurate', 'verify something, We have no way of verifying his story.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('verse', 'noun', 'vɜːs', 'writing that is arranged in lines, often with a regular rhythm or pattern of rhyme', 'in verse, Most of the play is written in verse, but some of it is in prose.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('versus', 'preposition', 'ˈvɜːsəs', 'used to show that two teams or sides are against each other', 'It is France versus Brazil in the final.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vessel', 'noun', 'ˈvesl', 'a tube that carries blood through the body of a person or an animal, or liquid through the parts of a plant', 'to burst/rupture a blood vessel', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('veteran', 'noun', 'ˈvetərən', 'a person who has a lot of experience in a particular area or activity', 'the veteran American actor, Clint Eastwood', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('viable', 'adjective', 'ˈvaɪəbl', 'that can be done; that will be successful', 'a viable option/proposition', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vibrant', 'adjective', 'ˈvaɪbrənt', 'full of life and energy', 'a vibrant city', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vice', 'noun', 'vaɪs', 'criminal activities that involve sex or drugs', 'At the door were two plain-clothes detectives from the vice squad.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vicious', 'adjective', 'ˈvɪʃəs', 'violent and cruel', 'a vicious attack', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('viewer', 'noun', 'ˈvjuːə(r)', 'a person watching television or a video on the internet', 'The programme attracted millions of viewers.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('viewpoint', 'noun', 'ˈvjuːpɔɪnt', 'a way of thinking about a subject', 'from a… viewpoint, Try looking at things from a different viewpoint.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('villager', 'noun', 'ˈvɪlɪdʒə(r)', 'a person who lives in a village', 'Some of the villagers have lived here all their lives.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('violate', 'verb', 'ˈvaɪəleɪt', 'to go against or refuse to obey a law, an agreement, etc.', 'to violate international law', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('violation', 'noun', 'ˌvaɪəˈleɪʃn', 'the act of going against or refusing to obey a law, an agreement, etc.', 'They were in open violation of the treaty.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('virtual', 'adjective', 'ˈvɜːtʃuəl', 'made to appear to exist by the use of computer software, for example on the internet', 'a system to help programmers create virtual environments ', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('virtue', 'noun', 'ˈvɜːtʃuː', 'behaviour or attitudes that show high moral standards', 'He led a life of virtue.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('visa', 'noun', 'ˈviːzə', 'a stamp or mark put in your passport by officials of a foreign country that gives you permission to enter, pass through or leave their country', 'to apply for a visa', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('visual', 'adjective', 'ˈvɪʒuəl', 'of or connected with seeing or sight', 'the visual arts', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vitamin', 'noun', 'ˈvɪtəmɪn', 'a natural substance found in food that is an essential part of what humans and animals need to help them grow and stay healthy. There are many different vitamins.', 'vitamin A/B/D/E', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vocal', 'adjective', 'ˈvəʊkl', 'connected with the voice', 'vocal music', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('voluntary', 'adjective', 'ˈvɒləntri', 'done willingly, not because you are forced', 'a voluntary agreement', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('volunteer', 'noun, verb', 'ˌvɒlənˈtɪə(r)', 'a person who does a job without being paid for it', 'Schools need volunteers to help children to read.', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('voting', 'noun', 'ˈvəʊtɪŋ', 'the action of choosing somebody/something in an election or at a meeting', 'He was eliminated in the first round of voting.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vow', 'verb', 'vaʊ', 'to make a formal and serious promise to do something or a formal statement that is true', 'vow to do something, She vowed never to speak to him again.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vulnerability', 'noun', 'ˌvʌlnərəˈbɪləti', 'the fact of being weak and easily hurt physically or emotionally', 'the vulnerability of newborn babies to disease', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('vulnerable', 'adjective', 'ˈvʌlnərəbl', 'weak and easily hurt physically or emotionally', 'These offices are highly vulnerable to terrorist attack.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('waiter', 'noun', 'ˈweɪtə(r)', 'a man whose job is to serve customers at their tables in a restaurant, etc.', 'I''ll ask the waiter for the bill.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wake', 'verb', 'weɪk', 'to stop sleeping; to make somebody stop sleeping', 'I always wake early in the summer.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('ward', 'noun', 'wɔːd', 'a separate room or area in a hospital for people with the same type of medical condition', 'a maternity/surgical/psychiatric/children’s ward', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('warehouse', 'noun', 'ˈweəhaʊs', 'a building where large quantities of goods are stored, especially before they are sent to shops to be sold', 'Police are investigating a fire at a furniture warehouse.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('warfare', 'noun', 'ˈwɔːfeə(r)', 'the activity of fighting a war, especially using particular weapons or methods', 'air/naval/guerrilla warfare', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('warming', 'noun', 'ˈwɔːmɪŋ', 'the process of making something, or of becoming, warm or warmer', 'atmospheric warming', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('warrant', 'noun, verb', 'ˈwɒrənt', 'a legal document that is signed by a judge and gives the police authority to do something', 'an arrest warrant', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('warrior', 'noun', 'ˈwɒriə(r)', '(especially in the past) a person who fights in a battle or war', 'a warrior nation (= whose people are skilled in fighting)', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('weaken', 'verb', 'ˈwiːkən', 'to make somebody/something less strong or powerful; to become less strong or powerful', 'The team has been weakened by injury.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wealthy', 'adjective', 'ˈwelθi', 'having a lot of money, possessions, etc.', 'a wealthy businessman/individual/family', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('weave', 'verb', 'wiːv', 'to make cloth, a carpet, a basket, etc. by crossing threads or narrow pieces of material across, over and under each other by hand or on a machine called a loom', 'weave A from B, The baskets are woven from strips of willow.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('weed', 'noun', 'wiːd', 'a wild plant growing where it is not wanted, especially among crops or garden plants', 'The yard was overgrown with weeds.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('weird', 'adjective', 'wɪəd', 'very strange or unusual and difficult to explain', 'I had a really weird dream last night.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('welfare', 'noun', 'ˈwelfeə(r)', 'the general health, happiness and safety of a person, an animal or a group', 'We are concerned about the child''s welfare.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('well-being', 'noun', 'ˈwel biːɪŋ', 'general health and happiness', 'emotional/physical/psychological well-being', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('whatsoever', 'adverb', 'ˌwɒtsəʊˈevə(r)', 'not at all; not of any kind', 'They received no help whatsoever.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wheat', 'noun', 'wiːt', 'a plant grown for its grain that is used to produce the flour for bread, cakes, pasta, etc.; the grain of this plant', 'wheat flour', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('whereby', 'adverb', 'weəˈbaɪ', 'by which; because of which', 'They have introduced a new system whereby all employees must undergo regular training.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('whip', 'verb', 'wɪp', 'to hit a person or an animal hard with a whip, as a punishment or to make them go faster or work harder', 'He was taken back to the jail and soundly whipped.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wholly', 'adverb', 'ˈhəʊlli', 'completely', 'wholly inappropriate behaviour', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('widen', 'verb', 'ˈwaɪdn', 'to become wider; to make something wider', 'Her eyes widened in surprise.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('widespread', 'adjective', 'ˈwaɪdspred', 'existing or happening over a large area or among many people', 'The storm caused widespread damage.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('widow', 'noun', 'ˈwɪdəʊ', 'a woman whose husband or wife has died and who has not married again', 'She gets a widow’s pension.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wildlife', 'noun', 'ˈwaɪldlaɪf', 'animals, birds, insects, etc. that are wild and live in a natural environment', 'policies designed to protect wildlife', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wipe', 'verb', 'waɪp', 'to rub something against a surface, in order to remove dirt or liquid from it; to rub a surface with a cloth, etc. in order to clean it', 'wipe something (on something), Please wipe your feet on the mat.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wisdom', 'noun', 'ˈwɪzdəm', 'the ability to make sensible decisions and give good advice because of the experience and knowledge that you have', 'She was known to be a woman of great wisdom.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wit', 'noun', 'wɪt', 'the ability to say or write things that are both clever and humorous', 'to have a quick/sharp/dry/ready wit', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('withdrawal', 'noun', 'wɪðˈdrɔːəl', 'the act of taking an amount of money out of your bank account', 'You can make withdrawals of up to $250 a day.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('word', 'noun', 'wɜːd', 'a single unit of language that means something and can be spoken or written', 'Do not write more than 200 words.', '[]', 'A1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('workforce', 'noun', 'ˈwɜːkfɔːs', 'all the people who work for a particular company, organization, etc.', 'The factory has a 1 000-strong workforce.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('workout', 'noun', 'ˈwɜːkaʊt', 'a period of physical exercise that you do to keep fit', 'She does a 20-minute workout every morning.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('workplace', 'noun', 'ˈwɜːkpleɪs', 'the office, factory, etc. where people work', 'the introduction of new technology into the workplace', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('workshop', 'noun', 'ˈwɜːkʃɒp', 'a period of discussion and practical work on a particular subject, in which a group of people share their knowledge and experience', 'There will be the opportunity for practical theatre work in drama workshops.', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('worldwide', 'adjective, adverb', 'ˌwɜːldˈwaɪd', 'affecting all parts of the world', 'an increase in worldwide sales', '[]', 'B1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('worm', 'noun', 'wɜːm', 'a long, thin creature with a soft body and no bones or legs', 'birds looking for worms', '[]', 'B2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('worse', 'adjective, adverb, noun', 'wɜːs', 'of poorer quality or lower standard; more unpleasant', 'The rooms were awful and the food was worse.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('worst', 'adjective, adverb, noun', 'wɜːst', 'of the poorest quality or lowest standard; worse than any other person or thing of a similar kind', 'It was by far the worst speech he had ever made.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('worthwhile', 'adjective', 'ˌwɜːθˈwaɪl', 'important, pleasant, interesting, etc.; worth spending time, money or effort on', 'It was in aid of a worthwhile cause (= a charity, etc.).', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('worthy', 'adjective', 'ˈwɜːði', 'having the qualities that deserve somebody/something', 'Very few of his ideas are worthy of further attention.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('wow', 'exclamation', 'waʊ', 'used to show that you are very surprised or impressed by somebody/something', 'Wow! You look terrific!', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('yell', 'verb', 'jel', 'to shout loudly, for example because you are angry, excited, frightened or in pain', 'yell (at somebody/something), He yelled at the other driver.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('yield', 'noun, verb', 'jiːld', 'the total amount of crops, profits, etc. that are produced', 'a high crop yield', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('youngster', 'noun', 'ˈjʌŋstə(r)', 'a young person or a child', 'The camp is for youngsters aged 8 to 14.', '[]', 'C1') ON CONFLICT(term) DO NOTHING;
INSERT INTO vocab (term, type, pronounce, meaning, example, word_family, level) VALUES ('zero', 'number', 'ˈzɪərəʊ', '0', 'Five, four, three, two, one, zero… We have lift-off.', '[]', 'A2') ON CONFLICT(term) DO NOTHING;
